class Solution:
    def addTwoNumbers(self, l1: Optional[ListNode], l2: Optional[ListNode]) -> Optional[ListNode]:
        carry, head = 0, l1
        while l1 or l2:
            if not l1.next and l2: l1.next, l2.next = l2.next, l1.next

            val1 = l1.val if l1 else 0
            val2 = l2.val if l2 else 0

            carry, l1.val = divmod(val1 + val2 + carry, 10)

            prev = l1
            if l1: l1 = l1.next
            if l2: l2 = l2.next

        if carry: prev.next = ListNode(carry)
        return head

class Solution:
    def addTwoNumbers(self, l1: Optional[ListNode], l2: Optional[ListNode]) -> Optional[ListNode]:
        carryOver = 0
        result = ListNode(-1)
        resultTail = result

        while l1 or l2:
            total = 0
            if l1: 
                total += l1.val
                l1 = l1.next
            if l2: 
                total += l2.val
                l2 = l2.next

            total += carryOver
            carryOver, remainder = divmod(total, 10)
            resultTail.next = ListNode(remainder)
            resultTail = resultTail.next

        if carryOver > 0:
            resultTail.next = ListNode(carryOver)

        return result.next

