        actual_row = 0
        actual_col = 0
        s = [letter for letter in s]
        matriz = [[0]*(len(s)) for _ in range(numRows)]
        while s:
            if actual_row == 0:
                for row in range(numRows):
                    if not s:
                        break
                    matriz[row][actual_col] = s.pop(0)
                    actual_row = row
                if numRows == 1:
                    actual_col+=1
            else:
                actual_col+=1
                actual_row-=1
                if actual_row > 0:
                    matriz[actual_row][actual_col] = s.pop(0)

