                            min_step = step
        @lru_cache(None)
        def dfs(cur, step):
            nonlocal graph
            if step > min_step:
                return []
            if cur == endWord:
                return [[endWord]]
            res = []
            for nxt in graph[cur]:
                tmp = dfs(nxt,step+1)
                res += [[cur] + x for x in tmp]
