class Solution(object):
    @cache  # the memory trick can save some time
    def partition(self, s):
        if not s: return [[]]
        ans = []
        for i in range(1, len(s) + 1):
            if s[:i] == s[:i][::-1]:  # prefix is a palindrome
                for suf in self.partition(s[i:]):  # process suffix recursively
                    ans.append([s[:i]] + suf)
        return ans

class Solution(object):
    def __init__(self):
        self.memory = collections.defaultdict(list)

    def partition(self, s):
        if not s: return [[]]
        if s in self.memory: return self.memory[s]  # the memory trick can save some time
        ans = []
        for i in range(1, len(s) + 1):
            if s[:i] == s[:i][::-1]:  # prefix is a palindrome
                for suf in self.partition(s[i:]):  # process suffix recursively
                    ans.append([s[:i]] + suf)
        self.memory[s] = ans
        return ans

class Solution:
    def partition(self, s: str) -> List[List[str]]:
        l = len(s)

        def isPalindrom(s):
            return s == s[::-1]

        @cache
        def rec(start):
            if start == l:
                return []

            res = []
            for i in range(start + 1, l + 1):
                sub = s[start:i]

                if isPalindrom(sub):
                    subres = rec(i)
                    if not subres:
                        res.append(deque([sub]))
                    else:
                        for arr in subres:
                            copy = arr.copy()
                            copy.appendleft(sub)
                            res.append(copy)

            return res

        return rec(0)

class Solution:
    def partition(self, s: str) -> List[List[str]]:
        dp = []
        n = len(s)

        for i in range(n+1):
            dp.append([])  # create dp of size n+1

        dp[-1].append([])  # because for s[n:] i.e. empty string ,  answer = [[]]

        # dp[i] store all possible palindrome partitions of string s[i:] 

        for i in range(n-1,-1,-1):
            for j in range(i+1,n+1):
                curr = s[i:j] # cosider each substring of s start from i-th character

                if curr == curr[::-1]:  # if substring is palindrome

                    # Consider first element of each partition is curr then add curr in the front of all partitions of string s[j:]  , which are already stored in dp[j] 
                    for e in dp[j]:   
                        dp[i].append ([curr] + e)

        return dp[0]      # All palindrome partitions of s[0:] = s

class Solution:
    def partition(self, s: str) -> List[List[str]]:
        res, part = [], []

        def dfs(i):
            if i >= len(s):
                res.append(part.copy())
                return
            for j in range(i, len(s)):
                if isPali(s, i, j):
                    part.append(s[i:j+1])
                    dfs(j + 1)
                    part.pop()
        dfs(0)
        return res

def isPali( s, l, r):
        while l < r:
            if s[l] != s[r]:
                return False
            l, r = l + 1, r - 1
        return True

class Solution:
    def partition(self, s: str) -> List[List[str]]:
        substring = []
        result = []

        # backtracking 
        def dfs(i):
            if i >= len(s):
                result.append(substring.copy())
                return 

            for j in range(i, len(s)):
                if self.check_palindrome(s, i, j):
                    substring.append(s[i:j+1])
                    dfs(j+1)
                    substring.pop()

        dfs(0)

        return result 

    # check if it is palindrome 
    def check_palindrome(self, s, l, r):
        while l < r:
            if s[l] == s[r]:
                l += 1
                r -= 1
            else:
                return False
        return True

class Solution:
    def partition(self, s: str) -> List[List[str]]:

        res = []

        def isPalindrome(s):
            return s == s[::-1]

        def backtrack(s,start,comb):
            if start == len(s):
                res.append(list(comb))
                return
            if start > len(s):
                return
            left = start
            right = start + 1
            while right <= len(s):
                currWord = s[left:right]
                if isPalindrome(currWord):
                    comb.append(currWord)
                    backtrack(s,right,comb)
                    comb.pop()

                right += 1
        backtrack(s,0,[])
        return res

class Solution:
    def partition(self, s: str) -> List[List[str]]:
        ret = []
        self.helper(ret, [], s)
        return ret

    def helper(self, ret, curr, s):
        if s == "":
            ret.append(curr)

        for i in range(len(s)):
            if self.isPalin(s[:i + 1]):
                self.helper(ret, curr + [s[:i + 1]], s[i + 1:])

    def isPalin(self, s):
        for i in range(len(s) // 2):
            if s[i] != s[len(s) - 1 - i]:
                return False
        return True

