class Solution:
    def reorderList(self, head: Optional[ListNode]) -> None:
        if not head.next or not head.next.next:
            return

        # search for the middle
        slow, fast = head, head
        while fast.next and fast.next.next:
            slow = slow.next
            fast = fast.next.next

        tail, cur = None, slow.next
        slow.next = None # detach list on the middle

        # reverse right part
        while cur:
            cur.next, tail, cur = tail, cur, cur.next

		# rearrange nodes as asked
        headCur, headNext = head, head.next
        tailCur, tailNext = tail, tail.next
        while True:
            headCur.next, tailCur.next = tailCur, headNext

            if not tailNext:
                return

            tailCur, headCur = tailNext, headNext
            tailNext, headNext = tailNext.next, headNext.next

class Solution:
    def reorderList(self, head: ListNode) -> None:
        def reorder(node: ListNode, position: int, length: int) -> None:
            if (position < length / 2):
                next = reorder(node.next, position + 1, length)
                output = next.next
                next.next = node.next
                node.next = next
            else:
                next = node.next
                if (length % 2 == 1):
                    node.next = None
                    output = next
                else:
                    output = next.next
                    next.next = None
            return output
        node = head
        length = 0
        while (node):
            node = node.next
            length += 1
        length and reorder(head, 1, length)

class Solution:
    def cloneGraph(self, node: 'Node') -> 'Node':
        if not node: return node

        q, clones = deque([node]), {node.val: Node(node.val, [])}
        while q:
            cur = q.popleft() 
            cur_clone = clones[cur.val]            

            for ngbr in cur.neighbors:
                if ngbr.val not in clones:
                    clones[ngbr.val] = Node(ngbr.val, [])
                    q.append(ngbr)

                cur_clone.neighbors.append(clones[ngbr.val])

        return clones[node.val]

