class Solution:
    def cloneGraph(self, node: 'Node') -> 'Node':
        if node: 
            memo = {node: Node(node.val)} #original -> clone mapping
            stack = [node]
            while stack: 
                n = stack.pop()
                for nn in n.neighbors: 
                    if nn not in memo: 
