            nonlocal N
            if i == N: 
                sentences.append(sentence[1:])
                return
            for word in wordDict:
                index = i+len(word)
                if index <= N and s[i:index] == word and i not in visited:
                    visited.add(i)
                    backtrack(index, sentence+' '+word)
