        self.next = defaultdict(Trie)
        self.isEnd = False

    def add(self, word):
        cur = self
        for c in word:
            if c not in cur.next:
                cur.next[c] = Trie()
            cur = cur.next[c]

        cur.isEnd = True

class Solution:
