        words = Trie()

        for word in wordDict:
            words.add(word)

        @cache
        def recurse(index, trie):
            if index == len(s):
                return trie.isEnd

            if trie.isEnd:
                if recurse(index, words):
                    return True

            if s[index] in trie.next:
                return recurse(index + 1, trie.next[s[index]])

            return False

        return recurse(0, words)

