class Solution:
    def dp(self, i, j):
        if j == (self.n - 1) and i == (self.m - 1):
            return max(1, 1 - self.grid[i][j])
        if j == self.n or i == self.m :
            return 99999
        if self.ans[i][j] != -99999:
            return self.ans[i][j]
        anss = min(self.dp(i+1, j), self.dp(i, j+1)) - self.grid[i][j]
        if anss > 0 :
            self.ans[i][j] = anss
        else:
            self.ans[i][j] = 1
