                    if(buy):
                        profit = max(-prices[ind]+ dp[ind+1][0][cap] , 0 + dp[ind+1][1][cap])

                    else:
                        profit = max(prices[ind] + dp[ind+1][1][cap-1], 0 + dp[ind+1][0][cap])

