class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        if grid == None or len(grid) == 0: return 0

        r, c = len(grid), len(grid[0])
        dsu = DSU(r * c)

        # union an island with its adjacent islands
        for i in range(r):
            for j in range(c):
                if int(grid[i][j]) == 1:

                    # add this island first
                    dsu.numIsl += 1

                    # union 4 adjacent islands if exist
                    if i - 1 >= 0 and int(grid[i - 1][j]) == 1:
                        dsu.union((i - 1) * c + j, i * c + j)
                    if i + 1 < r and int(grid[i + 1][j]) == 1:
                        dsu.union(i * c + j, (i + 1) * c + j)
                    if j - 1 >= 0 and int(grid[i][j - 1]) == 1:
                        dsu.union(i * c + (j - 1), i * c + j)
                    if j + 1 < c and int(grid[i][j + 1]) == 1:
                        dsu.union(i * c + j, i * c + (j + 1))

        return dsu.numIsl

class DSU:
    def __init__(self, num):
        self.numIsl = 0
        self.par = list(range(num))
        self.rnk = [0] * num

    def find(self, x):
        if self.par[x] != x:
            self.par[x] = self.find(self.par[x])
        return self.par[x]

    def union(self, x, y):
        xr, yr = self.find(x), self.find(y)
        if xr == yr:
			return
        elif self.rnk[xr] < self.rnk[yr]:
            self.par[xr] = yr
        elif self.rnk[xr] > self.rnk[yr]:
            self.par[yr] = xr
        else:
            self.par[yr] = xr
            self.rnk[xr] += 1
        self.numIsl -= 1

class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        count = 0
        R, C = len(grid), len(grid[0])


        def dfs(r, c):
            grid[r][c] = '0'
            if r-1 >= 0 and grid[r-1][c] == '1':
                dfs(r-1, c)
            if r+1 < R and grid[r+1][c] == '1':
                dfs(r+1, c)
            if c+1 < C and grid[r][c+1] == '1':
                dfs(r, c+1)
            if c-1 >= 0 and grid[r][c-1] == '1':
                dfs(r, c-1)


        for row in range(0, len(grid)):
            for col in range(0, len(grid[0])):
                if grid[row][col] == '1':
                    count += 1
                    dfs(row, col)

        return count

# first we find the 1 valued element using two for loops and then we update their values to 0 so 
# that when we backtrack (like r-1) then it will not keep on running and when values of all of it's connected
# elements become 0, we come out of the dfs(). This keeps on happening as the 2 for loops continue finding the '1' valued element.

class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        if len(grid) == 0:
            return 0

        uf = {}
        N = len(grid)
        M = len(grid[0])

        for i in range(N):
            for j in range(M):
                if grid[i][j] == '1':
                    uf[(i,j)] = (i,j)

        for i in range(N):
            for j in range(M):
                if grid[i][j] == '0':
                    continue

                if i+1<N and grid[i+1][j] == '1':
                    union(uf, (i,j), (i+1,j))
                if j+1<M and grid[i][j+1] == '1':
                    union(uf, (i,j), (i,j+1))

        count = 0
        for k, v in uf.items():
            if v == k:
                count += 1
        return count

def union(uf, a, b) -> None:
    uf[root(uf, b)] = root(uf, a)

def root(uf, x) -> str:
    r = x
    while r != uf[r]:
        r = uf[r]
    return r

