        """sieve of Eratosthenes"""
        if n <= 2: return 0                # no primes less than 2
        primes = [False]*2 + [True]*(n-2)  # 0 &amp; 1 are not a prime
        for i in range(2, int(sqrt(n))+1): # only need to check up to sqrt(n)
