    def findOrder(self, numCourses: int, pr: List[List[int]]) -> List[int]:

        # Build adjacency list
        adj = defaultdict(list)
        for a, b in prerequisites:
            adj[b].append(a)

        # TopoSort
        topo = list()
        vis = set()
        processed = set()
        for node in range(numCourses):
            if node in vis:
                continue

            st = [node]
            while st:
                cur = st[-1]
                vis.add(cur)

                if cur in processed:
                    st.pop()
                    continue

				for ch in adj[cur]:
					if not ch in vis:
						st.append(ch)

                if cur == st[-1]:
                    topo.append(st.pop())
                    processed.add(cur)

        # Result
        res = []
        i = 0
        pos = dict()
        while topo:
            node = topo.pop()
            pos[node] = i
            i += 1
            res.append(node)

        # Check for cycles
        for parent, children in adj.items():
            for child in children:
                if pos[parent] > pos[child]:
                    return []

        return res

class Solution:
    def findOrder(self, numCourses: int, prerequisites):
        # DFS 用递归
        # 先找到 上了某门课以后可以解锁的全后置课，放入dict neighborNode 中
        # 再做一个 status dict, 用来记录查找的状态, 默认value 0 代表没访问过
        # dfs 更改 status, 0 代表没访问; 1 代表访问中; 2 代表访问过
        # 如果递归遇到1，表示已成环，则无法上完所有课，返回 false；否则递归更新上课顺序在 result 里

        from collections import deque
        result=deque([])
        neighborNodes = collections.defaultdict(list)
        status = collections.defaultdict(int)

        for nodeTo,nodeFrom in prerequisites:
            neighborNodes[nodeFrom].append(nodeTo)

        def dfs(node):
            if status[node]==1: 
                return False # 成环了，无法上完所有课
            if status[node]: 
                return #如果访问过了，退出

            status[node] = 1 #没访问过，递归，把顺序 appendleft 加入deque中
            for next_node in neighborNodes[node]:
                if dfs(next_node) == False:
                    return False
            status[node] = 2
            result.appendleft(node)

        for node in range(numCourses):
            if dfs(node) == False: 
                return []
        return result

class Solution:
    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:
        # BFS 用deque
        from collections import deque
        q = deque([])
        result = deque([])
        inDegree = [0]*numCourses
        neighborNodes = collections.defaultdict(list)

        # 计算每一门课的入度, 找到 每一门 course 可以解锁的课程
        for nodeTo, nodeFrom in prerequisites:
            inDegree[nodeTo] +=1
            neighborNodes[nodeFrom].append(nodeTo)

        # 将入度=0 的课程放入 deque 中，可以先上
        for node in range(numCourses):
            if not inDegree[node]:
                q.append(node)


        while q:
            node = q.pop()
            result.append(node)
            for next_node in neighborNodes[node]:
                inDegree[next_node] -=1
                if not inDegree[next_node]: q.append(next_node)

        # 如果有环，则 上过课的数量会小于 课程总数，返回[]
        if len(result) == numCourses: return result
        return []

class Solution:
    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:
        preq = defaultdict(list)
        for x in prerequisites:
            preq[x[0]] += [x[1]]

        order = []
        visited = {}
        def isCycleDFS(node):
            if node in visited:
                return visited[node]
            visited[node] = True
            for n in preq[node]:
                if isCycleDFS(n): return True
            visited[node] = False
            order.append(node)
            return False

        for i in range(numCourses):
            if isCycleDFS(i): return []

        return order

class Solution:
    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:
        if numCourses <= 0:
            return []
        inDegree = {}
        adjList = {}

        for i in range(numCourses):
            inDegree[i] = 0
            adjList[i] = []

        for child, parent in prerequisites:
            adjList[parent].append(child)
            inDegree[child] += 1

        q = deque()
        for i in range(numCourses):
            if inDegree[i] == 0:
                q.append(i)

        order = []
        visit = set()
        while len(q) > 0:
            cur = q.popleft()
            order.append(cur)
            visit.add(cur)

            for n in adjList[cur]:
                inDegree[n] -= 1
                if n not in visit and inDegree[n] == 0:
                    q.append(n)

        if len(order) == numCourses:
            return order
        return []

class Solution:
    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:

        graph = {i:[] for i in range(numCourses)}
        in_degree = {i: 0  for i in range(numCourses)}
        for dest, prev in prerequisites:
            graph[prev].append(dest)
            in_degree[dest] += 1
        course_chose, ans = 0, []
        queue = collections.deque()
        for node, value in in_degree.items():
            if value == 0:
                queue.append(node)
        while queue:
            curr_node = queue.popleft()
            course_chose += 1
            ans.append(curr_node)
            for dest in graph[curr_node]:
                in_degree[dest] -= 1
                if in_degree[dest] == 0:
                    queue.append(dest)
        if course_chose != numCourses: return []
        return ans

class Solution:
    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:
        cToP = {c: 0 for c in range(numCourses)} # Maps course to number of prerequisites
        pToC = {p: [] for p in range(numCourses)} # Maps prerequisite to list of courses
        for c, p in prerequisites:
            cToP[c] += 1
            pToC[p].append(c)

        # We should start with courses with no prerequisites and then continue (BFS)
        coursesToTake = [c for c, pS in cToP.items() if not pS]
        res = []
        while coursesToTake:
            res.extend(coursesToTake)
            nextCoursesToTake = []
            for p in coursesToTake:
                for c in pToC[p]:
                    cToP[c] -= 1
                    if not cToP[c]:
                        nextCoursesToTake.append(c)
            coursesToTake = nextCoursesToTake

        return res if not any(cToP.values()) else [] # Return result if all courses have 0 prerequisites else return an empty list

class Solution:
	def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:

		def dfs(node, seen):
			if node in seen:
				self.cycle = True
			else:
				if not self.visited[node]:
					self.visited[node] = True
					seen.add(node)
					if node in self.dict_:
						for pre_course in self.dict_[node]:
							if self.cycle:
								break
							dfs(pre_course, seen)
					self.final.append(node)
					seen.remove(node)

		self.visited = [False]*numCourses
		self.dict_ = dict()
		self.cycle = False
		self.final = []

		for course, pre_course in prerequisites:
			if course not in self.dict_:
				self.dict_[course] = [pre_course]
			else:
				self.dict_[course].append(pre_course)

		for course in range(numCourses):
			if self.cycle:
				return []
			dfs(course, set())
		return self.final

class Solution:
    def findWords(self, board: List[List[str]], words: List[str]) -> List[str]:
        m = len(board)
        n = len(board[0])
        res = []

        d = [[0, 1], [0, -1], [1, 0], [-1, 0]]

        ref = set()
        for i in range(m):
            for j in range(n-1):
                ref.add(board[i][j] + board[i][j+1])
        for j in range(n):
            for i in range(m-1):
                ref.add(board[i][j] + board[i+1][j])

        for word in words:
            f = True
            for i in range(len(word)-1):
                if word[i:i+2] not in ref and word[i+1] + word[i] not in ref:
                    f = False
                    break
            if not f:
                continue
            if self.findWord(word, m, n, board, d):
                res.append(word)
        return res

    def findWord(self, word, m, n, board, d) -> bool:
        if word[:4] == word[0] * 4:
            word = ''.join([c for c in reversed(word)])
        starts = []
        stack = []
        visited = set()
        for i in range(m):
            for j in range(n):
                if board[i][j] == word[0]:
                    if len(word) == 1:
                        return True
                    starts.append((i, j))
        for start in starts:
            stack.append(start)
            visited.add((start, ))
            l = 1
            while stack != [] and l < len(word):
                x, y = stack[-1]
                for dxy in d:
                    nx, ny = x + dxy[0], y + dxy[1]
                    if 0 <= nx < m and 0 <= ny < n:
                        if board[nx][ny] == word[l]:
                            if (nx, ny) not in stack and tuple(stack) + ((nx, ny),) not in visited:
                                stack.append((nx, ny))
                                visited.add(tuple(stack))
                                l += 1
                                if l == len(word):
                                    return True
                                break
                else:
                    stack.pop()
                    l -= 1
        else:
            return False

