                #remove all its prefixes to prevent duplicate searches in the board
                words.remove(w)
                for w_ in word2prefixes[w]:
                    prefix[w_]-=1
                    if prefix[w_]==0:
                        prefix.pop(w_)
                word2prefixes.pop(w)

            for nei in [(x+1,y),(x,y+1),(x-1,y),(x,y-1)]:
                nx,ny = nei

                if nei not in visited\
                and nx>=0 and nx<nrows\
