                    return
            directions = [[+1,0], [-1,0], [0,+1], [0,-1]]
            for direction in directions:
                x = i+direction[0]; y = j+direction[1]
                if inBounds(x,y,m,n) and visited[x][y] == 0:
                    char = board[x][y]
                    if char in node:
                        visited[x][y] = 1
                        record = node
                        node = node[char]
                        track.append(char)
                        backtracking(x, y, node, track, m, n, visited, board)
                        track.pop()
                        node = record
                        visited[x][y] = 0

        m = len(board)
        n = len(board[0])
        visited = [0 for _ in range(n)]
        visited = [list(visited) for _ in range(m)]
        track = []
        for i in range(m):
            for j in range(n):
                if board[i][j] in trie:
                    visited[i][j] = 1
                    node = trie[board[i][j]]
                    track.append(board[i][j])
                    backtracking(i, j, node, track, m, n, visited, board)
                    track.pop()
                    visited[i][j] = 0
        return list(res)

