    def shortestPalindrome(self, s: str) -> str:
        n = len(s)
        if n == 1:
            return s
        for pivot in range((n + 1) // 2, -1, -1):
            pre = s[:pivot]
            suf1 = s[pivot:pivot+pivot][::-1]
            suf2 = s[pivot-1:pivot+pivot-1][::-1]
            if pre == suf1:
                return s[pivot:][::-1] + s[pivot:]
