	def GenerateValid(self, options, currentIndex, k, n, score, comb, ans):

		if(score == n and k == 0):
			ans.append(comb[:])
			return

		if(currentIndex >= len(options) or (score != n and k <= 0)):
			return

		if(score + options[currentIndex] <= n and k > 0):
			comb.append(options[currentIndex])
			self.GenerateValid(options, currentIndex + 1, k - 1, n, score + options[currentIndex], comb, ans)
			comb.pop()

		self.GenerateValid(options, currentIndex + 1, k, n, score, comb, ans)

		return

