class Solution:

    def get_height(self, root):  # O(logN)
        height = -1
        node = root
        while node:
            height += 1
            node = node.left
        return height

    def countNodes_binarySearch(self, root: TreeNode):
        height = self.get_height(root)       # O(logN)
        if height <= 0: return height + 1

        def num2node(num, step = height):   # logN
            node = root
            mask = 1 << (step-1)
            for _ in range(step):
                node = node.right if num &amp; mask else node.left
                mask >>= 1
            return False if node is None else True

        # O(logN * logN)
        lo, hi = 0, (1 << height) - 1
        if num2node(hi):  
            lo = hi
        while lo + 1 < hi:
            mi = (lo + hi) >> 1
            if num2node(mi):
                lo = mi
            else:
                hi = mi
        return lo + (1 << height)

class Solution:

    def get_height(self, root): # O(logN)
        height = -1
        node = root
        while node:
            height += 1
            node = node.left
        return height


    def countNodes_recursion(self, root: TreeNode) -> int:    # O(logN * logN)
        height = self.get_height(root)      # O(logN)
        if height <= 0: return height + 1

        if self.get_height(root.right) == height - 1:     # O(logN)
            return (1 << height) + self.countNodes_recursion(root.right)
        else:
            return (1 << (height-1)) + self.countNodes_recursion(root.left)

class Solution:
    def countNodes(self, root: TreeNode) -> int:
        max_level = 0
        temp = root
        while temp:
            max_level += 1
            temp = temp.left
        num_missing = 0
        q = []
        cur_level = 1
        while q or root:
            while root:
                q.append([root, cur_level])
                root = root.right
                cur_level += 1
            # print([x.val for x, _ in q])
            root, cur_level = q.pop()
            if cur_level == max_level:
                return 2**(max_level) - 1 - num_missing
            else:
                if not root.right:
                    num_missing += 1
                if not root.left:
                    num_missing += 1
            root = root.left
            cur_level += 1
        return  0

class Solution:
    def computeArea(self, ax1: int, ay1: int, ax2: int, ay2: int, bx1: int, by1: int, bx2: int, by2: int) -> int:
        Sa = (ax2-ax1) * (ay2-ay1)
        Sb = (bx2-bx1) * (by2-by1)
        S = Sa + Sb

        w_ov = min(ax2, bx2) - max(ax1, bx1)
        if w_ov <= 0:
            return S

        h_ov = min(ay2, by2) - max(ay1, by1)
        if h_ov <= 0:
            return S

        S_ov = w_ov * h_ov

        return S - S_ov

class Solution:
    def computeArea(self, ax1: int, ay1: int, ax2: int, ay2: int, bx1: int, by1: int, bx2: int, by2: int) -> int:

        # Function to caculate area of rectangle (Length * width)
        def area(x1,y1,x2,y2):
            return (x2-x1)*(y2-y1)

        # Finding the overlap rectangle length and width
        overlapX = max(min(ax2,bx2)-max(ax1,bx1), 0)
        overlapY = max(min(ay2,by2)-max(ay1,by1), 0)

        # Area1 + Area2 - Overlap Rectangle Area
        return area(ax1,ay1,ax2,ay2) + area(bx1,by1,bx2,by2) - overlapX * overlapY

class Solution:
    def computeArea(self, ax1: int, ay1: int, ax2: int, ay2: int, bx1: int, by1: int, bx2: int, by2: int) -> int:

        def sendpotentialcoordinates(a1,a2,b1,b2):
            if b1>=a1 and b1<a2:
                if b2>=a2:
                    return (b1,a2) #a case
                else:
                    return (b1,b2) #c case
            if b1<a1 and b2>a1:
                if b2>=a2:
                    return (a1,a2) #d case
                else:
                    return (a1,b2) #b case
            return (None,None) #All other cases

        x1,x2=sendpotentialcoordinates(ax1,ax2,bx1,bx2)
        y1,y2=sendpotentialcoordinates(ay1,ay2,by1,by2)
        # print(x1,x2,y1,y2)
        if x1!=None and y1!=None:

            return  (abs(ax1-ax2)*abs(ay1-ay2))+(abs(bx1-bx2)*abs(by1-by2))-((abs(x1-x2)*abs(y1-y2)))
        else:
            return (abs(ax1-ax2)*abs(ay1-ay2))+(abs(bx1-bx2)*abs(by1-by2))

class Solution:
    def computeArea(self, ax1: int, ay1: int, ax2: int, ay2: int, bx1: int, by1: int, bx2: int, by2: int) -> int:
        area_first = abs(ax1 - ax2) * abs(ay1 - ay2)
        area_second = abs(bx1 - bx2) * abs(by1 - by2)
        x_distance = (min(ax2, bx2) -max(ax1, bx1))
        y_distance = (min(ay2, by2) -max(ay1, by1))
        Area = 0
        if x_distance > 0 and y_distance > 0:
            Area = x_distance * y_distance
        return (area_first + area_second - Area)

