                    curr_res = int(curr_res / num)

                # if the chracter is "+" or "-", we do not need to worry about
                # the priority so that we can add the curr_res to the eventual res
                if ch in ("+", "-"):
                    res += curr_res
                    curr_res = 0

                op = ch
                num = 0

        return res

