class Solution:
    import heapq
    def kthSmallest(self, root: Optional[TreeNode], k: int) -> int:

        heap = []
        def inorder(r):
            if r:
                inorder(r.left)
                heapq.heappush(heap,-(r.val))
                if len(heap) > k:
                    heapq.heappop(heap)
                inorder(r.right)
        inorder(root)

        return -heapq.heappop(heap)

