class Solution:
    def isAnagram(self, s: str, t: str) -> bool:
        frequencies = [0]*26
        count = 0
        for letter in s:
            index = ord(letter) - ord('a')
            frequencies[index] += 1
            count += 1

        for letter in t:
            index = ord(letter) - ord('a')
            if frequencies[index] == 0:
                return False
            frequencies[index] -= 1
            count -= 1
        return count == 0

