class Solution:
    def numSquares(self, n: int) -> int:
	    # Generate the squares, reverse to be in decreasing order for efficiency.
        sqrs = [i**2 for i in range(1, int(math.sqrt(n))+1)][::-1]
        mins = float('inf')

        def helper(t, nums, idx):
            nonlocal mins
            l = len(nums)
			# If the current nums we're using >= the min that lead to the target return.
			# If t < 0 or > n return.
            if l >= mins or t < 0 or t > n:
                return
			# If by this stage our t == 0 we store the l, this only gets update if l < mins.
            if t == 0:
                mins = l
                return
            else:
			    # Recursively work through the sqrs.
                for i in range(idx, len(sqrs)):
                    helper(t-sqrs[i], nums + [sqrs[i]], i)

        helper(n, [], 0)
        return mins if mins != float('inf') else -1

class Solution:
    def numSquares(self, n: int) -> int:
	    # Generate the squares.
        sqrs = [i**2 for i in range(0, int(math.sqrt(n))+1)][::-1]
        q = collections.deque([])
        q.append((n, 0))
        used = set()

        while q:
		    # Get total and steps from our deque.
            t, step = q.popleft()
            for i in sqrs:
			    # We have found the answer! 
                if t - i == 0:
                    return step + 1
				# If we need to deduct more from t
                if t - i > 0:
				    # If we haven't already added what the next result we'll push to the deque
                    if (t - i, step + 1) not in used:
					    # Add our new t and increment our step
                        q.append((t - i, step + 1))
                        used.add((t - i, step + 1))
        return -1

