class Solution:
    def addOperators(self, num: str, target: int) -> List[str]:
        ans = []
        def backtrack(cur, i):
            if i >= len(cur):
                # print(cur)
                if self.check(cur) and self.calculate(cur) == target:
                    ans.append(cur[:])
                return
            backtrack(cur[:i] + "*" + cur[i:], i+2)
            backtrack(cur[:i] + "+" + cur[i:], i+2)
            backtrack(cur[:i] + "-" + cur[i:], i+2)
            backtrack(cur, i+1)
        backtrack(num, 1)
        return ans

