        ans = []
        j = 0
        for i in range(len(cur_digits)):
            if cur_digits[i] in ["*", "+", "-"]:
                if i - j > 1 and cur_digits[j] == "0":
                    return False
                j = i + 1
        if len(cur_digits) - j > 1 and cur_digits[j] == "0":
            return False
        return True

