    def removeInvalidParentheses(self, s: str) -> List[str]:
        curStack = set([s])
        output = set()
        nextStack = set()
        if self.valid(s):
            return [s]
        while curStack:
            for node in curStack:
                for i in range(len(node)):
                    cur = node[:i] + node[i + 1:]
                    if self.valid(cur):
                        output.add(cur)
                    else:
                        nextStack.add(cur)
            curStack = nextStack
            nextStack = set()
            if len(output) > 0:
                break
        return list(output)
