        size = [0]
        output = set()
        right_left = s.count(")")
        dfs(s, output, size, right_left)
        return output


def dfs(s, output, size, right_left, idx=0, left=0, right=0, out=[]):
    if right > left:
        return
    if left-right > right_left:
        return
    if idx == len(s):
        if len(out) < size[-1]:
            return
        if left == right:
            if len(out) > size[-1]:
                output.clear()
                size[-1] = len(out)
            output.add("".join(out))
        return


    item = s[idx]

    if item == ")":
        right_left -= 1

    dfs(s, output, size, right_left, idx+1, left, right, out)

    if item == "(":
        left += 1
    elif item == ")":
        right += 1

    out.append(item)
    dfs(s, output, size, right_left, idx+1, left, right, out)
    out.pop()

