        for i in range(n):
            if indegree[i] == 1:
                queue.append(i)

        remainNodes = n
        while queue and remainNodes>2:
            for i in range(len(queue)):
                removed = queue.popleft()
                indegree[removed] -= 1
                remainNodes -= 1
                for child in adjMap[removed]:
                    indegree[child] -= 1
                    if indegree[child] == 1:
                        queue.append(child)            

