            while total_node>2:
                total_node -= len(queue)
                for i in range(len(queue)):
                    v = queue.popleft()
                    for child in graph[v]:
                        if child in degree:
                            degree[child]-=1
                            if degree[child] == 1:
                                queue.append(child)


