            """Sort nums via merge sort and populate ans."""
            if lo+1 >= hi: return 
            mid = lo + hi >> 1
            fn(aux, nums, lo, mid)
            fn(aux, nums, mid, hi)
            i, j = lo, mid 
            for k in range(lo, hi): 
                if j >= hi or i < mid and aux[i][1] <= aux[j][1]: 
                    nums[k] = aux[i]
