        n = len(A)
        _min = min(A) - 1 # padding value
        _max = max(A) - _min
        result = [0] * n
        bit = [0] * (_max+1)

        def count(a):
            c = 0;
            while a > 0:
                c += bit[a]
                a -= a &amp; -a
            return c

