                    while  st!=[] and st[-1][1] > ord(s[i]) and d[st[-1][0]] !=0:
                        st.pop() 
                    st.append([s[i],ord(s[i])]) 
                    d[s[i]] -= 1 
                elif st!=[] and st[-1][1] < ord(s[i]):
                    st.append([s[i],ord(s[i])]) 
                    d[s[i]] -= 1 
                else:
                    st.append([s[i],ord(s[i])]) 
                    d[s[i]] -= 1 
            i+=1 
