class Solution:
    def removeDuplicateLetters(self, s: str) -> str:
        charMaxIndex = {}
        for i in range(len(s)):
            charMaxIndex[s[i]] = i

        visited = set()
        stack = []

        for i in range(len(s)):
            if s[i] in visited:
                continue

            while stack and stack[-1] > s[i] and charMaxIndex[stack[-1]] > i:
                visited.remove(stack[-1])
                stack.pop()

            visited.add(s[i])
            stack.append(s[i])

        return ''.join(stack)

class Solution:
    def removeDuplicateLetters(self, s: str) -> str:
        count = Counter(s)
        stack = deque()
        result = set()
        for i in s:
            if i in result: 
                count[i] -= 1
                continue

            while(stack and stack[-1] > i and count[stack[-1]] > 1):
                count[stack[-1]] -= 1
                result.remove(stack[-1])
                stack.pop()

            stack.append(i)
            result.add(i)

        return "".join(stack)

class Solution:
    def removeDuplicateLetters(self, s: str) -> str:
        d={}
        for i in range(len(s)):
            d[s[i]]=i 
        stack=[]
        st=set()
        for i in range(len(s)):
            curr=s[i]
            if curr in st:
                continue
            if len(stack)!=0 and stack[-1]<curr:
                st.add(curr)
                stack.append(curr)
            else:
                while len(stack)!=0 and stack[-1]>curr and d[stack[-1]]>i:
                    a=stack.pop()
                    st.remove(a)
                if curr not in st:
                    st.add(curr)
                    stack.append(curr)
        return ''.join(stack)

