class Solution:
    def countRangeSum(self, nums: List[int], lower: int, upper: int) -> int:
        prefix = [0]
        for x in nums: prefix.append(prefix[-1] + x)

        def fn(lo, hi): 
            """Return count of range sum between prefix[lo:hi]."""
            if lo+1 >= hi: return 0 
            mid = lo + hi >> 1
            ans = fn(lo, mid) + fn(mid, hi)
            k = kk = mid 
            for i in range(lo, mid): 
                while k < hi and prefix[k] - prefix[i] < lower: k += 1
                while kk < hi and prefix[kk] - prefix[i] <= upper: kk += 1
                ans += kk - k 
            prefix[lo:hi] = sorted(prefix[lo:hi])
            return ans 

        return fn(0, len(prefix))

class Solution:
    def countRangeSum(self, nums: List[int], lower: int, upper: int) -> int:
        def find(l,r):
            if l > r:
                return 0
            m = (l+r)//2
            left = [0]
            s = 0
            for i in range(m-1,l-1,-1):
                s += nums[i]
                left.append(s)
            right = [0]
            s = 0
            for i in range(m+1,r+1):
                s += nums[i]
                right.append(s)
            right.sort()
            ans = 0
            for i in left:
                ans += (bisect.bisect_right(right,upper-i-nums[m]) - bisect.bisect_left(right,lower-i-nums[m]))
            return ans + find(l,m-1)+find(m+1,r)
        return find(0, len(nums)-1)

class Solution:
	def oddEvenList(self, head: Optional[ListNode]) -> Optional[ListNode]:
		if head is None or head.next is None:
			return head

		e,o = head,head.next
		odd_head = o
		while o!=None and o.next!=None:
			e.next = o.next
			e = e.next
			o.next = e.next
			o = o.next

		e.next = odd_head
		return head

class Solution:
    def oddEvenList(self, head: Optional[ListNode]) -> Optional[ListNode]:
        if not head or not head.next:
            return head

        headOdd, headEven = head, head.next
        tailOdd, tailEven = headOdd, headEven

        i = 3
        cur = headEven.next
        while cur:
            if i%2:
                tailOdd.next = cur
                tailOdd = cur
            else:
                tailEven.next = cur
                tailEven = cur

            cur = cur.next
            i += 1

        tailEven.next = None # prevent cycle
        tailOdd.next = headEven

        return headOdd

class Solution:
    def oddEvenList(self, head: ListNode) -> ListNode:
        if not head:
            return None
        odd = head
        evenHead = even = head.next
        while even and even.next:
            odd.next = even.next
            odd = odd.next
            even.next = odd.next
            even = even.next
        odd.next = evenHead
        return head

class Solution:
    def oddEvenList(self, head: Optional[ListNode]) -> Optional[ListNode]:
        even = None
        pre = None
        cur = head

        if not head:
            return None

        nxt = head.next
        index = 0

        while cur:
            if index == 1:
                even = cur

            nxt = cur.next
            if nxt == None:
                if index % 2 == 0:
                    cur.next = even
                else:
                    pre.next = even
            else:
                cur.next = nxt.next

            pre = cur
            cur = nxt
            index += 1

        return head

class Solution:
    def longestIncreasingPath(self, grid: List[List[int]]) -> int:
        m,n=len(grid),len(grid[0])
        directions = [0, 1, 0, -1, 0] # four directions 

        @lru_cache(maxsize=None) # using python cache lib for memoization
        def dfs(r,c):
            ans=1                  
			# iterating through all 4 directions
            for i in range(4): 
                new_row,new_col=r+directions[i], c+directions[i+1] # calculating the new cell
				# check if new cell is within the grid bounds and is an increasing sequence
                if 0<=new_row<m and 0<=new_col<n and grid[new_row][new_col]>grid[r][c]: 
                    ans = max(ans, dfs(new_row, new_col) + 1 )  # finding the max length of valid path from the current cell                                      
            return ans

        return max(dfs(r,c) for r in range(m) for c in range(n))

class Solution:
    def longestIncreasingPath(self, matrix: List[List[int]]) -> int:
        m, n = len(matrix), len(matrix[0]) # dimensions 

        @cache
        def fn(i, j): 
            """Return max increasing path starting from (i, j)."""
            ans = 1
            for ii, jj in (i-1, j), (i, j-1), (i, j+1), (i+1, j): 
                if 0 <= ii < m and 0 <= jj < n and matrix[i][j] < matrix[ii][jj]: 
                    ans = max(ans, 1 + fn(ii, jj))
            return ans 

        return max(fn(i, j) for i in range(m) for j in range(n))

class Solution:
    def longestIncreasingPath(self, matrix: List[List[int]]) -> int:
        m, n = len(matrix), len(matrix[0])
        indeg = [[0]*n for _ in range(m)]
        for i in range(m):
            for j in range(n): 
                for ii, jj in (i-1, j), (i, j-1), (i, j+1), (i+1, j): 
                    if 0 <= ii < m and 0 <= jj < n and matrix[i][j] < matrix[ii][jj]: 
                        indeg[ii][jj] += 1
        queue = deque([(i, j) for i in range(m) for j in range(n) if indeg[i][j] == 0])
        ans = 0
        while queue: 
            for _ in range(len(queue)): 
                i, j = queue.popleft()
                for ii, jj in (i-1, j), (i, j-1), (i, j+1), (i+1, j): 
                    if 0 <= ii < m and 0 <= jj < n and matrix[i][j] < matrix[ii][jj]: 
                        indeg[ii][jj] -= 1
                        if indeg[ii][jj] == 0: queue.append((ii, jj))
            ans += 1
        return ans

class Solution:
    def longestIncreasingPath(self, matrix: List[List[int]]) -> int:
        M, N = len(matrix), len(matrix[0])
        MOVES = [(1,0), (0,1), (-1,0), (0,-1)]

        @functools.cache
        def dfs(i, j):
            path_length = 0
            for di, dj in MOVES:
                ni, nj = i+di, j+dj
                if 0<=ni<M and 0<=nj<N and matrix[ni][nj] > matrix[i][j]:
                    path_length = max(path_length, dfs(ni, nj))
            return 1 + path_length

        res = 0
        for i in range(M):
            for j in range(N):
                res = max(res, dfs(i, j))

        return res

class Solution:
    def longestIncreasingPath(self, matrix: List[List[int]]) -> int:

        def isValid(r,c):
            return 0<=r<len(matrix) and 0<=c<len(matrix[0])

        directions=[(1,0),(0,1),(-1,0),(0,-1)]

        max_path=1
        dp= [ [0 for _ in range(len(matrix[0]))] for __ in range(len(matrix))]

        def helper(r,c):
            if dp[r][c]:
                return dp[r][c]
            res=dp[r][c]
            for nr,nc in directions:
                nr,nc=r+nr,c+nc
                if isValid(nr,nc) and matrix[nr][nc]>matrix[r][c]:
                    res=max( helper(nr,nc) + 1 , res )

            dp[r][c]=res
            return dp[r][c]


        for r in range(len(matrix)):
            for c in range(len(matrix[0])):
                max_path=max(helper(r,c)+1,max_path)

        return max_path

