class Solution:
    def isValidSerialization(self, preorder: str) -> bool:
        if preorder == '#':
            return True

        preorder = preorder.split(',')

        stack = []

        for i in range(len(preorder)):
            c = preorder[i]
            if i > 0 and not stack:
                return False

            if c.isdigit():
                stack.append(2)

            elif c == '#':
                if not stack:
                    return False

                stack[-1] -= 1

            while stack and stack[-1] == 0:
                stack.pop()
                if stack:
                    stack[-1] -= 1

        return not stack

