class Solution:
    def dfs(self, graph, airport):
        terminalTrip = []
        result = []

        while graph[airport]:
            dest = heapq.heappop(graph[airport])
            trip = self.dfs(graph, dest)

            if airport in trip:
                result += trip
            else:
                terminalTrip = trip

        return [airport] + result + terminalTrip

