class Solution:
    def integerBreak(self, n: int) -> int:
        if n == 2 or n == 3:
            return n - 1                # must break into 1 &amp; (n-1)

        num_3 = n // 3                  # break the number into (3+3+3+...) + remainder

        if n%3 == 0:                    
            return 3**num_3             # (3+3+3+...)
        if n%3 == 2:
            return (3**num_3) * 2       # (3+3+3+...) + 2     
        if n%3 == 1:
            return 3**(num_3-1) * 4     # (3+3+3+...) + 1 --> (3+3+...) + 3 + 1 -- > (3+3+...) + 4

class Solution:
    def integerBreak(self, n: int) -> int:
        memo = {}
        def intBreak(n):
            if n in memo:
                return memo[n]
            if n<2:
                memo[n] = 0
                return 0
            if n==2:
                memo[2] = 2
                return 1
            maxval = 0
            for i in range(1,n//2+1):
                maxval = max(maxval,i*intBreak(n-i),i*(n-i))
            memo[n] = maxval
            return maxval
        ans = intBreak(n)
        return ans

