    def binarySearch(self, array, target):
        left = 0
        right = len(array) - 1

        while left <= right:
            mid = left + (right - left)//2
            if array[mid] == target:
                return mid
            elif array[mid] > target:
                right = mid - 1
            else:
                left = mid + 1
        return left

