    def binarySearchOptimal(self, num):
        if not num:return False

        left, right = 0, num + 1

        while left <= right:
            mid = (left + right) // 2
            square = mid * mid # mid** 2 # pow(mid, 2)
            if square == num:
                return True
            elif square > num:
                right = mid - 1
            else:
                left = mid + 1

