        l,h = 1,n
        mid = (l + h)//2
        while True:
            if guess(mid) < 0:
                h = mid-1
                mid = (l + h)//2
            elif guess(mid) > 0:
                l = mid+1
                mid = (l + h)//2
            else:
                return mid

class Solution:
    def guessNumber(self, n: int) -> int:
        low = 0
        high = n

        while low<=high:

            mid = low+(high-low)//2
            num = guess(mid)

            if num == 0:
                return mid
            elif num == -1:
                high = mid-1
            else:
                low = mid+1

