class Solution:
    def guessNumber(self, n: int) -> int:
        l = 1
        r = n
        while l<=r:
            mid = l + (r-l)//2
            result = guess(mid)
            if result == 0:
                return mid
            elif result == -1:
                r = mid -1
            elif result == 1:
                l = mid + 1
        return mid

class Solution:
    def guessNumber(self, n):
        l, r = 1, n
        while True:
            m = (l+r)//2
            match guess(m):
                case  0: return m
                case  1: l = m+1
                case -1: r = m-1

class Solution:
    def guessNumber(self, n: int) -> int:
        lo, hi = 1, n
