class Solution:
    def getMoneyAmount(self, n: int) -> int:

        @lru_cache(None)
        def fn(lo, hi): 
            """The cost of guessing a number where lo <= x <= hi."""
            if lo >= hi: return 0 # no need to guess 
            ans = inf
            for mid in range(lo, hi+1): 
                ans = min(ans, mid + max(fn(lo, mid-1), fn(mid+1, hi)))
            return ans 

        return fn(1, n)

