class Solution:
    def combinationSum4(self, nums: List[int], target: int) -> int:
        waysToAdd = [0 for x in range(target+1)]
        waysToAdd[0] = 1

        for i in range(min(nums), target+1):
            waysToAdd[i] = sum(waysToAdd[i-num] for num in nums if i-num >= 0)

        return waysToAdd[-1]

class Solution:
    def combinationSum4(self, nums: List[int], target: int) -> int:

        dp = defaultdict(int)

        return self.rec(nums, target, dp)

    def rec(self, nums, target, dp):

        if target == 0:
            return 1

        if target < 0:
            return 0

        if target in dp:
            return dp[target]

        for num in nums:
            dp[target] += self.rec(nums, target-num, dp)

        return dp[target]

class Solution:
    def combinationSum4(self, nums: List[int], target: int) -> int:
        '''
            Here we are doing bottom up DP and the base case would be =>
            when target is zero how many way can we achieve that: 1 way
        '''
        dp = { 0 : 1 } # base case 
        for total in range(1,target+1):
            dp[total] = 0
            for n in nums:
                dp[total] += dp.get(total-n,0)
        return dp[target]


    # /////// Solution 1 ///////
    def combinations(self, nums, target, combination, lookup):
        if target == 0:
            return 1
        if target < 0:
            return 0
        if target not in lookup:
            ans = 0
            for num in nums:
                ans += self.combinations(nums, target-num, combination+[num], lookup)
            lookup[target] = ans
        return lookup[target]

    def combinationSum4(self, nums: List[int], target: int) -> int:
        nums.sort()
        return self.combinations(nums, target, [], {})

class Solution:
    def combinationSum4(self, nums: List[int], target: int) -> int:
        dp = {}
        def solve(nums, target,  asf):
            if asf in dp:
                return dp[asf]
            if asf<0:
                return 0
            if asf == 0:
                return 1
            ans = 0
            for i in nums:
                ans += solve(nums, target, asf-i)
            dp[asf] = ans

            return ans
        return solve(nums,target,target)

