class Solution:
    def kthSmallest(self, matrix: List[List[int]], k: int) -> int:
        n = len(matrix)
        hp = [(matrix[i][0], i, 0) for i in range(n)] # heap 
        heapify(hp)
        for _ in range(k): 
            v, i, j = heappop(hp)
            if j+1 < n: heappush(hp, (matrix[i][j+1], i, j+1))
        return v

