    def lastRemaining1(self, n: int) -> int:
        """"
        removing from left to right [1 2 3 4 5 6 7 8 9]==[2 4 6 8]==2*[1 2 3 4]
        """
        def helper(n,is_left):
            if n == 1: return 1
            if is_left: return 2*helper(n//2,False)
            if n%2==1: return 2*helper(n//2,True)
            return 2*helper(n//2,2)-1
        return helper(n,True)

    def lastRemaining2(self, n: int) -> int:
        if n==0: return
        st1,st2,left=list(range(1,n+1)),[],True
        while len(st1)>1:
            if not left:
                st1=st1[::-1]
            for i in range(1,len(st1),2):
                st2.append(st1[i])
            st1=list(st2) if left else list(st2[::-1])
            st2=[]
            left = not left
        return st1[0]

class Solution:
    def isRectangleCover(self, rectangles: List[List[int]]) -> bool:

        area = 0
        corners = set()
        a = lambda: (Y-y) * (X-x)

        for x, y, X, Y in rectangles:
            area += a()
            corners ^= {(x,y), (x,Y), (X,y), (X,Y)}

        if len(corners) != 4: return False
        x, y = min(corners, key=lambda x: x[0] + x[1])
        X, Y = max(corners, key=lambda x: x[0] + x[1])
        return a() == area

class Solution:
    def isRectangleCover(self, rectangles: List[List[int]]) -> bool:
        xs=[]
        ys=[]

        for sx,sy,ex,ey in rectangles:
            xs.append(sx)
            xs.append(ex)

            ys.append(sy)
            ys.append(ey)

        xlookup={x:i for i,x in enumerate(sorted(set(xs)))}
        ylookup={y:i for i,y in enumerate(sorted(set(ys)))}

        N=len(xlookup)-1
        M=len(ylookup)-1
        grid=[[0]*M for _ in range(N)]

        for sx,sy,ex,ey in rectangles:
            for cx in range(xlookup[sx],xlookup[ex]):
                for cy in range(ylookup[sy],ylookup[ey]):
                    grid[cx][cy]+=1

        for row in grid:
            for cell in row:
                if cell!=1:
                    return False

        return True

