class Solution:
    def longestSubstring(self, s: str, k: int) -> int:
        #sliding window and hashmap O(n) or Divide and conquer(O(n*n))
        n=len(s)
        ans=0     
        freq= Counter(s)
        max_nums=len(freq)
        for num in range(1,max_nums+1):
