class Solution:
    def longestSubstring(self, s, k):

        def dfs(s, l , r, k):
            cnt = [0] * 26
            for i in range(l, r + 1):
                cnt[ord(s[i]) - 97] += 1
            split = 0
            for i in range(26):
                if cnt[i] > 0 and cnt[i] < k:
                    split = chr(i + 97)
                    break
            if split == 0:
                return r - l + 1
            i = l
            ret = 0
            while i <= r:
                while i <= r and s[i] == split:
                    i += 1
                if i > r:
                    break
                start = i
                while i <= r and s[i] != split:
                    i += 1

                length = dfs(s, start, i - 1, k)
                ret = max(ret, length)
            return ret

        n = len(s)
        return dfs(s, 0, n - 1, k)

