class Solution:
    def integerReplacement(self, n: int) -> int:
        def helper(n, memo):
            if n in memo:
                return memo[n]
            elif n%2:
                memo[n] = 1 + min(helper(n-1,memo), helper(n+1,memo))
                return memo[n]
            else:
                memo[n] = 1 + helper(n//2, memo)
                return memo[n]

        memo = {1:0}
        return helper(n, memo)

