class Solution:
    def calcEquation(self, equations: List[List[str]], values: List[float], queries: List[List[str]]) -> List[float]:
        # key is node name; value is [root_name, node/root]
        nodes = {}

        def find(a, b):
            if a not in nodes:
                nodes[a] = (a, 1)
            if b not in nodes:
                nodes[b] = (b, 1)
            return nodes[a][0] == nodes[b][0]

        def union(a, b, v):
            if find(a, b):
                return
            # move group a into b
            (a_root, va), (b_root, vb) = nodes[a], nodes[b]
            for x in nodes:
                if nodes[x][0] == a_root:
                    nodes[x] = (b_root, nodes[x][1] / va * v * vb)

        for (a, b), v in zip(equations, values):
            union(a, b, v)
        return [nodes[a][1]/nodes[b][1] if (a in nodes and b in nodes and nodes[a][0] == nodes[b][0]) else -1 for a, b in queries]

class Solution:
    def findNthDigit(self, n: int) -> int:
        digit = base = 1 # starting from 1 digit
        while n > 9*base*digit: # upper limit of d digits 
            n -= 9*base*digit
            digit += 1
            base *= 10 
        q, r = divmod(n-1, digit)
        return int(str(base + q)[r])

class Solution:
    def findNthDigit(self, n: int) -> int:

        # integer digit, 1~9 integer digits is 1, 10~19 integer digits is 2
        d = 1

        # total digits at a integer level, base = 9*10**(d-1)*d
        base = 0

        while n > 9*10**(d-1)*d + base:

            base += 9*10**(d-1)*d
            d+=1

        # closest number for nth digits
        number = (10**(d-1) - 1) + (n-base)//d
        number = int(number)
        # remainder
        rmd = (n-base)%d

        if rmd == 0:
            return int(str(number)[-1])
        else:
            return int(str(number+1)[rmd-1])

class Solution:
    def findNthDigit(self, n: int) -> int:
        if len(str(n))==1:
            return n
        c=1
        while n>=9*(10**(c-1))*c:
            n-=9*(10**(c-1))*c
            c+=1
        if n==0:
            return 9
        a=10**(c-1)-1
        a+=n//c
        if n%c!=0:
            a+=1
        if n%c==0:
            return int(str(a)[-1])
        else:
            return int(str(a)[(n%c)-1])

