class Solution:
    def readBinaryWatch(self, turnedOn: int) -> List[str]:
        # for example:
        # 2 1 (3 min) - two leds on, bin: 11 
        # 2   (2 min) - one led on, bin: 10
        #   1 (1 min) - one led on, bin:  1

