    def updateThreeMax(self, threeLargest, num):
        if threeLargest[2] is None or threeLargest[2] < num:
            self.shiftUp(threeLargest, num, 2)
        elif threeLargest[1] is None or threeLargest[1] < num:
            self.shiftUp(threeLargest, num, 1)
        elif threeLargest[0] is None or threeLargest[0] < num:
            self.shiftUp(threeLargest, num, 0)


    def shiftUp(self, threeLargest, num, idx):
        for i in range(idx + 1):
