            for ii, jj in (i-1, j), (i, j-1), (i, j+1), (i+1, j): 
                if 0 <= ii < m and 0 <= jj < n and board[ii][jj] == "X": dfs(ii, jj)

        ans = 0
        for i in range(m):
            for j in range(n):
                if board[i][j] == "X": 
                    ans += 1
                    dfs(i, j)
        return ans

class Solution:
