            ans <<= 1
            prefix = {num >> i for num in nums}
            ans += any(ans^1^p in prefix for p in prefix)
        return ans

class Solution:
    def originalDigits(self, s: str) -> str:
        # (z)ero, one, t(w)o, three, fo(u)r, five, si(x), seven, ei(g)ht, nine
        from collections import Counter
        sc = Counter(s)
        digits = {0: Counter("zero"), 1: Counter("one"), 2:Counter("two"), 3:Counter("three"), 4:Counter("four"), 5:Counter("five"), 6:Counter("six"), 7: Counter("seven"), 8: Counter("eight"), 9: Counter("nine")}
        counts = [0]*10

        for i in [0, 2, 4, 6, 8, 3, 1, 7, 5, 9]:
            digit = digits[i]
            while digit <= sc:
                sc -= digit
                counts[i] += 1

        return "".join([str(i)*c for i, c in enumerate(counts)])

class Solution:
    def originalDigits(self, s: str) -> str:
        freq = Counter(s)
        res = {}
        res["0"] = freq["z"]
        res["2"] = freq["w"]
        res["4"] = freq["u"]
        res["6"] = freq["x"]
        res["8"] = freq["g"]
        res["3"] = freq["h"] - res["8"]
        res["5"] = freq["f"] - res["4"]
        res["7"] = freq["s"] - res["6"]
        res["9"] = freq["i"] - res["5"] - res["6"] - res["8"]
        res["1"] = freq["n"] - res["7"] - (2 * res["9"])
        num = ""
        for i in res:
            if res[i] != 0:
                num += i * res[i]
        return ''.join(sorted(num))

