class Solution:
    def construct(self, grid: List[List[int]]) -> 'Node':

        def fn(x0, x1, y0, y1): 
            """Return QuadTree subtree."""
            val = {grid[i][j] for i, j in product(range(x0, x1), range(y0, y1))}
            if len(val) == 1: return Node(val.pop(), True, None, None, None, None)
            tl = fn(x0, (x0+x1)//2, y0, (y0+y1)//2)
            tr = fn(x0, (x0+x1)//2, (y0+y1)//2, y1)
            bl = fn((x0+x1)//2, x1, y0, (y0+y1)//2)
            br = fn((x0+x1)//2, x1, (y0+y1)//2, y1)
            return Node(None, False, tl, tr, bl, br)

        n = len(grid)
        return fn(0, n, 0, n)

class Solution:
    def construct(self, grid: List[List[int]]) -> 'Node':
        bits = {1:0,0:0}
        for row in grid:
            for i in row:
                bits[i] += 1
        total_bits = len(grid) ** 2
        if bits[1] == total_bits: return Node(1, True, None, None, None, None)
        if bits[0] == total_bits: return Node(0, True, None, None, None, None)
        mid = len(grid)//2
        return Node(1, False, 
        self.construct(list(map(lambda bits: bits[:mid], grid[:mid]))),  
        self.construct(list(map(lambda bits: bits[mid:], grid[:mid]))),
        self.construct(list(map(lambda bits: bits[:mid], grid[mid:]))),
        self.construct(list(map(lambda bits: bits[mid:], grid[mid:]))))

class Solution:
    def construct(self, grid: List[List[int]]) -> 'Node':
        def helper(left, right, down, up):
            if left == right and up == down:
                return Node(grid[up][left], 1, None, None, None, None)

            midlr = (left + right) // 2
            midud = (down + up) // 2

            bl = helper(left, midlr, midud + 1, up)
            br = helper(midlr + 1, right, midud + 1, up)
            tl = helper(left, midlr, down, midud)
            tr = helper(midlr + 1, right, down, midud)

            if tl.val == tr.val == bl.val == br.val and tl.isLeaf and tr.isLeaf and bl.isLeaf and br.isLeaf:
                return Node(tl.val, 1, None, None, None, None)

            return Node(1, 0, tl, tr, bl, br)

        return helper(0, len(grid) - 1, 0, len(grid) - 1)

