    def deleteHelper(self, node: Optional[TreeNode], parent: TreeNode, key: int):
		# if key does not exist within the BST
        if not node:
            return
        if node.val == key:
            nodeToMakeChild = None
            if node.right:
                # add the left subtree of the node to be deleted to the minimum node of the right subtree
                minRight = self.findMin(node.right)
                minRight.left = node.left
