class Solution:
    def canIWin(self, maxChoosableInteger: int, desiredTotal: int) -> bool:
        if desiredTotal == 0: return True # edge case 1
        if maxChoosableInteger * (maxChoosableInteger+1)//2 < desiredTotal: return False # edge case 2

        @lru_cache(None)
        def fn(mask, total): 
            """Return True if there is a winning strategy given mask &amp; total."""
            if total <= 0: return False # already lost 
            for i in range(maxChoosableInteger): 
                if mask &amp; (1 << i): # integer i+1 is not used yet 
                    if not fn(mask ^ (1 << i), total - (i + 1)): return True 
            return False 

        return fn(int("1"*maxChoosableInteger, 2), desiredTotal)

class Solution:
    def canIWin(self, maxChoosableInteger: int, desiredTotal: int) -> bool:
        return desiredTotal == 0 or desiredTotal % (maxChoosableInteger + 1)

class Solution:
    def canIWin(self, maxChoosableInteger: int, desiredTotal: int) -> bool:
        # 1,2,3,4,5 -> player 1
        # 2,3,4,5 -> player 2, choose any of them, cannot win
        # Then 1 win
        candidate = [i for i in range(1, maxChoosableInteger + 1)]

        if sum(candidate) < desiredTotal:
            return False

        memo = dict()
        def dfs(candidate, remain):
            if candidate[-1] >= remain:
                return True

            if tuple(candidate) in memo:
                return memo[tuple(candidate)]

            for i in range(len(candidate)):
                if not dfs(candidate[:i] + candidate[i + 1:], remain - candidate[i]):
                    memo[tuple(candidate)] = True
                    return True

            memo[tuple(candidate)] = False
            return False

        return dfs(candidate, desiredTotal)

class Solution:
    def canIWin(self, maxChoosableInteger: int, desiredTotal: int) -> bool:
        remainder = [i+1 for i in range(maxChoosableInteger)] # numbers
        @cache
        def can_win(total, remainder):
            if total >= desiredTotal:
                return False # total is already exceed the desiredTotal. Opponent won. 

            for num in remainder:
                if can_win(total + num, tuple([n for n in remainder if n != num])) == False: # if opponent lose, I win(return True)
                    return True
            return False 

        if desiredTotal == 0: 
            return True 
        if sum(remainder) < desiredTotal: # Both of two cannot win.
            return False 
        return can_win(0, tuple(remainder))

class Solution:
    def canIWin(self, maxChoosableInteger: int, desiredTotal: int) -> bool:

        @lru_cache(maxsize=None)
        def can_win(choices, remainder):
            if choices[-1] >= remainder: return True

            for index in range(len(choices)):
                if not can_win(choices[:index] + choices[index + 1:], remainder - choices[index]): return True

            return False

        summed_choices =  maxChoosableInteger * (maxChoosableInteger + 1) / 2
        if summed_choices < desiredTotal: return False
        if summed_choices == desiredTotal: return maxChoosableInteger % 2

        return can_win(tuple(range(1, maxChoosableInteger + 1)), desiredTotal)

class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        cnt = idx = 0 
        count = []
        index = []
        for i in range(n1): 
            for ch in s1: 
                if ch == s2[idx]: 
                    idx += 1
                    if idx == len(s2): 
                        cnt += 1
                        idx = 0 
            count.append(cnt)
            index.append(idx)
            for ii in range(i): 
                if index[ii] == idx: 
                    prev = count[ii]
                    repeat = (cnt - prev) * ((n1-1-ii) // (i - ii))
                    post = count[ii + (n1-1-ii) % (i-ii)] - count[ii]
                    return (prev + repeat + post) // n2
        return count[-1]//n2

class Solution:
    def findSubstringInWraproundString(self, p: str) -> int:
        consecutive = 1

        # stores the maximum length of a substring ending at a character 
        maxSubstr = defaultdict(int)
        maxSubstr[p[0]] = 1

        ans = 0
        for x in range(1, len(p)):
            if ord(p[x]) - ord(p[x - 1]) == 1 or p[x] == 'a' and p[x - 1] == 'z':
                consecutive += 1
            else:
                consecutive = 1
            maxSubstr[p[x]] = max(maxSubstr[p[x]], consecutive)

        return sum(maxSubstr.values())

class Solution:
    def findSubstringInWraproundString(self, p: str) -> int:
        ans = cnt = 0
        seen = {} # longest string ending at char 
        for i in range(len(p)): 
            if 0 < i and (ord(p[i]) - ord(p[i-1])) % 26 != 1: cnt = 0 # reset counter 
            cnt += 1
            if cnt > seen.get(p[i], 0): # duplicate of seen.get(p[i], 0) 
                ans += cnt - seen.get(p[i], 0) # non-duplicate 
                seen[p[i]] = cnt
        return ans

class Solution:
