        for i in range(len(p)): 
            if 0 < i and (ord(p[i]) - ord(p[i-1])) % 26 != 1: cnt = 0 # reset counter 
            cnt += 1
            seen[p[i]] = max(seen.get(p[i], 0), cnt)
        return sum(seen.values())

class Solution:
    def findSubstringInWraproundString(self, p: str) -> int:
        dp=[0 for i in range(26)]
        if p=="":
            return 0
        count=1
        pre=ord(p[0])-ord('a')
        dp[pre]=1
        for i in p[1:]:
            cur=ord(i)-ord('a')
            if (pre+1)%26==cur:
                count+=1
                dp[cur]=max(dp[cur],count)
            else:
                count=1
                dp[cur]=max(dp[cur],count)
            pre=cur
        return sum(dp)

