class Solution:
    def validIPAddress(self, queryIP: str) -> str:

        # IPv4 checks

        def ipv4_is_inrange(addr):
            return addr.isdigit() and int(addr)>=0 and int(addr)<=255

        def ipv4_no_leading_zeros(addr):
            return addr.isdigit() and ((len(addr) > 1 and addr[0] != "0") or len(addr) == 1)

        def ipv4_valid_total_len(ip):
            return len(ip) == 4

        def valid_ipv4(arr):
            return ipv4_valid_total_len(arr) and all([ipv4_is_inrange(addr) and ipv4_no_leading_zeros(addr) for addr in arr])

        # IPv6 checks

        def ipv6_valid_len(addr):
            addr = addr.strip()
            return len(addr) >= 1 and len(addr) <= 4

        def ipv6_valid_hexdecimal(addr):
            valid_alpha_set = set("abcdefABCDEF")
            for c in addr:
                if (
                    (not c.isdigit() and not c.isalpha()) or 
                    (c.isalpha() and c not in valid_alpha_set)
                ):
                    return False
            return True

        def ipv6_valid_total_len(ip):
            return len(ip) == 8

        def valid_ipv6(arr):            
            return ipv6_valid_total_len(arr) and all([ipv6_valid_len(addr) and ipv6_valid_hexdecimal(addr) for addr in arr])

        # Main IP format checker

        def checker(queryIP):
            if valid_ipv4(queryIP.split(".")):
                return "IPv4"
            elif valid_ipv6(queryIP.split(":")):
                return "IPv6"        
            else:
                return "Neither"  

        return checker(queryIP)

