class Solution:
    def validate_ipv4(self,IP:str)->str:
        for x in IP.split("."):
            if len(x)==0 or len(x)>3: return "Neither"
            if not x.isdigit() or not 0<=int(x)<=255 or (x[0]=="0" and len(x)!=1): return "Neither"
        return "IPv4"

    def validate_ipv6(self,IP:str)->str:
        hex_digits="0123456789abcdefABCDEF"
        for x in IP.split(":"):
            if len(x)==0 or len(x)>4 or not all(c in hex_digits for c in x): return "Neither"
        return "IPv6" 

    def validIPAddress(self, IP: str) -> str:
        """
        O(n) time complexity
        O(1) space complexity
        """
        if "." in IP and IP.count(".")==3:
            return self.validate_ipv4(IP)
        elif ":" in IP and IP.count(":")==7:
            return self.validate_ipv6(IP)
        else:
            return "Neither"

class Solution:
    def findAllConcatenatedWordsInADict(self, words: List[str]) -> List[str]:
        ddic = lambda: defaultdict(ddic)
        trie = ddic()

        for word in words:
            cur = trie
            for char in word:
                cur = cur[char]

            cur['end'] = True

        def isConcat(word, start):
            cur = trie
            for i in range(start, len(word)):
                char = word[i]
                if char not in cur:
                    return False
                cur = cur[char]

                if 'end' in cur:
                    if i + 1 == len(word):
                        # tricky part that helps us distinguish simple word from concat word
                        return start != 0

                    if isConcat(word, i + 1):
                        return True

            return False

        return [word for word in words if isConcat(word, 0)]

class Solution:
    def findAllConcatenatedWordsInADict(self, words: List[str]) -> List[str]:
        s = set(words)

        memo = {}
        def isConcatenatedWord(w):
            if w in memo: return memo[w]

            for i in range(1, len(w)):
                if w[:i] not in s: continue

                r = w[i:]
                if r in s or isConcatenatedWord(r):
                    memo[w] = True
                    return True

            memo[w] = False
            return False

        return filter(isConcatenatedWord, words)

class Solution:
    def findAllConcatenatedWordsInADict(self, words: List[str]) -> List[str]:
        s, m = set(words), {}
        dp = lambda w: m[w] if w in m else any(w[:i] in s and (w[i:] in s or dp(w[i:])) for i in range(1, len(w)))
        return filter(dp, words)

class Solution:
    def findAllConcatenatedWordsInADict(self, words: List[str]) -> List[str]:
        seen = set(words)

        @cache
        def fn(word):
            """Return True if input is a concatenated word."""
            for i in range(1, len(word)): 
                prefix = word[:i]
                suffix = word[i:]
                if prefix in seen and (suffix in seen or fn(suffix)): return True 
            return False 

        ans = []
        for word in words: 
            if fn(word): ans.append(word)
        return ans

class Solution:
    def findAllConcatenatedWordsInADict(self, words: List[str]) -> List[str]:
        wordSet = set(words)
        res = []
        # for each word, remove it from the set and call dp and add it back for next iteration
        for word in words:
            wordSet.remove(word)
            if self.dp(wordSet, word, {}):
                res.append(word)
            wordSet.add(word)
        return res

    def dp(self, wordSet: List[str], word: str, m: dict) -> bool:
        # base case: return True if a string can be found,
        # originally I was thinking of base case being len(word) == 0, but it is not true because my subproblem is if the substring in word can be concatenated using wordSet. So base case should be what is the smallest substring that is in the wordSet
        if word in wordSet:
            return True

        # memoization would be a dict of all the substring and whether is true of not
        if word in m:
            return m[word]

        # go from the end of string to index 1(1 so that smallest string is the first index)
        for i in range(len(word) - 1, 0, -1):
            if word[i:] in wordSet and self.dp(wordSet, word[:i], m):
                m[word] = True
                return True
        m[word] = False
        return False

class Solution:
    def findAllConcatenatedWordsInADict(self, words: List[str]) -> List[str]:
        trie = dict()
        mem = set(words)

        for w in words:
            cur = trie
            for c in w:
                if c not in cur:
                    cur[c] = dict()
                cur = cur[c]

            cur["*"] = w

        def helper(w, level):
            cur = trie
            for i, c in enumerate(w):
                if c not in cur:
                    return False 

                cur = cur[c]

                if "*" in cur:
                    if i == len(w) - 1:
                        return level > 1
                    else:
                        if w[i + 1:] in mem or helper(w[i + 1:], level + 1):
                            return True

            return False


        ans = list()
        for w in words:
            if helper(w, 1):
                ans.append(w)

        return ans

class Solution:
	def findAllConcatenatedWordsInADict(self, words: List[str]) -> List[str]:
		wordSet = set(words)
		res = set()

		def dfs(s):
			if not s: 
				return True

			for i in range(len(s)):
				if s[:i + 1] in wordSet:           
					if dfs(s[i + 1:]): 
						return True

			return False

		for word in wordSet:
			wordSet.remove(word)                        # We need to not match the word with itself

			if dfs(word): 
				res.add(word)

			wordSet.add(word)

		return res

