class Solution:
    def goodWord(self, word, wordSet):
        dpMap = {}

        if word in dpMap:
            return dpMap[word]

        dpMap[word] = False

        for i in range(1, len(word)):
            prefix = word[:i]
            suffix = word[i:]

            if (prefix in wordSet) and (suffix in wordSet or self.goodWord(suffix, wordSet)):
                dpMap[word] = True
                break

        return dpMap[word]


    def findAllConcatenatedWordsInADict(self, words: List[str]) -> List[str]:
        concatenatedWords = []

        wordSet = set(words)

        for word in words:
            if self.goodWord(word, wordSet):
                concatenatedWords.append(word)

        return concatenatedWords

class Solution:
    def findAllConcatenatedWordsInADict(self, words: List[str]) -> List[str]:
