class Solution:
    def makesquare(self, nums: List[int]) -> bool:

        k = 4 

        s = sum(nums)
        if s % k != 0:
            return False

        target = s // k 
        n = len(nums)

        def dfs(m):

            stack = [(m, 0, {m}, nums[m])]
            while stack:
                #print(stack)
                node, cnt, path, sums = stack.pop()


                if sums == target:
                    if cnt == k-1:
                        return True
                    for i in range(0, n):
                        if i not in path:
                            stack.append((i, cnt+1, path | {i}, nums[i]))

                elif sums < target:
                    for i in range(node+1, n):
                        if i not in path:
                            stack.append((i, cnt, path | {i}, sums + nums[i]))
                else: # sums > target
                    pass
            return False
        return dfs(0)

class Solution:
    def makesquare(self, matchsticks: List[int]) -> bool:
        matchsticks=sorted(matchsticks)
        tot=sum(matchsticks)
        if tot%4!=0 or len(matchsticks)<4 or matchsticks[-1]>tot/4:
            return False
        l=len(matchsticks)
        length=tot//4
        size = 1<<l
        subset = [-1] * size
        subset[0]=0
        for i in range(size):
            if subset[i]==-1:
                continue
            for j in range(l):
                cur=1<<j
                if cur &amp; i !=0:
                    continue
                cur1=i|cur 
                if subset[cur1]==0:
                    continue
                subtotal = subset[i]+matchsticks[j]                                        
                if subtotal==length:
                    subset[cur1]=0
                elif subtotal<length:                        
                    subset[cur1]=subtotal
                if subset[size-1]==0:
                    return True
        if subset[size-1]==0:
            return True  
        else:
            return False

class Solution:
    def makesquare(self, matchsticks: List[int]) -> bool:
        circumference = sum(matchsticks)
        sidewidth = circumference // 4

        # rectangle requires all sides to have equal length
        if circumference % 4 != 0:
            return False

        # speeds it up in practice by taking the longest sticks first
        matchsticks.sort(reverse=True)

        # recursion with memoisation
        @cache
        def rec(sides, k):
            if k == len(matchsticks) and sum(sides) == circumference:
                return True
            else:
                for i in range(4):
                    if sides[i] + matchsticks[k] <= sidewidth:
                        sides = list(sides)
                        sides[i] += matchsticks[k]
                        ret = rec(tuple(sides), k+1) # we need to use tuple to make it hashable (enable cache)
                        if ret:
                            return True
                        sides[i] -= matchsticks[k]
            return False

        return rec(tuple([0]*4), 0)

class Solution:
    def backtrack(self, i, matchsticks, side, sideLen):
        if i == len(matchsticks):
            return True

        for j in range(4):
            if side[j] + matchsticks[i] <= sideLen:
                side[j] += matchsticks[i]
                if self.backtrack(i + 1, matchsticks, side, sideLen):
                    return True
                side[j] -= matchsticks[i]
            if i == 0:
                return False
        return False

