        n = len(matchsticks)
        sideLen = sum(matchsticks)//4

        side = [0]*4

        if sum(matchsticks) % 4 != 0:
            return False

        matchsticks.sort(reverse = True)

        return self.backtrack(0, matchsticks, side, sideLen)

