class Solution:
    def medianSlidingWindow(self, nums: List[int], k: int) -> List[float]:
        odd, mid = k % 2, k // 2

        def current_median():
            nonlocal odd, mid, window
            if odd:
                return window[mid]
            return (window[mid - 1] + window[mid]) / 2

        n, medians = len(nums), []
        window = sorted(nums[:k - 1])

        for i in range(k - 1, n):
            bisect.insort(window, nums[i])
            medians.append(current_median())
            first = bisect.bisect_left(window, nums[i - k + 1])
            del window[first]

        return medians

