    def licenseKeyFormatting(self, S: str, K: int) -> str:

        # Eliminate all dashes
        S = S.replace('-', '')

        head = len(S) % K

        grouping = []

        # Special handle for first group
        if head:
            grouping.append( S[:head] )

        # General case:
