    def licenseKeyFormatting(self, s: str, k: int) -> str:
        s=''.join(s.split('-')).upper()[::-1]
        q,r=divmod(len(s),k)
        if r==0:
            return '-'.join([s[k*i:k*(i+1)] for i in range(q)])[::-1]
        else:
            return '-'.join([s[k*i:k*(i+1)] for i in range(q)]+[s[-r:]])[::-1]

class Solution:
    def licenseKeyFormatting(self, s: str, k: int) -> str:
        s = s.upper().replace('-', '')[::-1]
        slots = math.ceil(len(s) / k)
        start = 0 
        end = k
        res = ''
        for i in range(1, slots+1):
            if i == slots:
                res += s[start:end]
            else:
                res += f'{s[start:end]}-'
                start = end
                end = start + k
        return res[::-1]

