        def helper(i, j, a, b, turn):
            if i == j:
                if turn:
                    return a + nums[i] >= b
                else:
                    return a >= b + nums[i]

            if turn:
                if helper(i + 1, j, a + nums[i], b, False):
                    return True

                if helper(i, j - 1, a + nums[j], b, False):
                    return True

                return False
            else:
