class Solution:
    def constructRectangle(self, area: int) -> list[int]:
        sqrt = area ** 0.5 
        if sqrt % 1 == 0: 
            return [int(sqrt)] * 2 
        factors = [[area // i, i] for i in range(2, int(sqrt) + 1) if area % i == 0] 
        return [area, 1] if not factors else factors[-1]

