class Solution:
    def reversePairs(self, nums: List[int]) -> int:

        def fn(nums, aux, lo, hi): 
            """Return number of reverse pairs in nums[lo:hi]."""
            if lo + 1 == hi: return 0 
            mid = lo + hi >> 1
            left = fn(aux, nums, lo, mid)
            right = fn(aux, nums, mid, hi)
            split = 0 
            i, j = lo, mid
            for _ in range(lo, hi): 
                if i == mid or j < hi and aux[i] > 2*aux[j]: 
                    split += mid - i 
                    j += 1
                else: i += 1
            i, j = lo, mid
            for k in range(lo, hi): 
                if j == hi or i < mid and aux[i] < aux[j]: 
                    nums[k] = aux[i]
                    i += 1
                else: 
                    nums[k] = aux[j]
                    j += 1
            return left + split + right 

        return fn(nums, nums.copy(), 0, len(nums))

class Solution:
    def merge(self, left, right):
        i, j = 0, 0
        m, n = len(left), len(right)
        while i < m:
            while j < n and left[i] > 2*right[j]:
                j += 1
            self.ans += j
            i += 1

        i, j = 0, 0
        temp = []
        while i < m and j < n:
            if left[i] < right[j]:
                temp.append(left[i])
                i += 1
            else:
                temp.append(right[j])
                j += 1

        while i < m:
            temp.append(left[i])
            i += 1
        while j < n:
            temp.append(right[j])
            j += 1

        return temp

    def mergesort(self, nums):
        if len(nums) <= 1:
            return nums
        mid = len(nums) // 2
        left, right = self.mergesort(nums[:mid]), self.mergesort(nums[mid:])
        return self.merge(left, right)

    def reversePairs(self, nums: List[int]) -> int:
        self.ans = 0
        _ = self.mergesort(nums)
        return self.ans

