class Solution:
    def reversePairs(self, nums: List[int]) -> int:

        def dc(nums):
            if len(nums) < 2:
                return 0
            if len(nums) == 2:
                return 1 if nums[0] > 2*nums[1] else 0

            m = len(nums) // 2
            left = nums[:m]
            right = nums[m:]

            count = 0
            count += dc(left)
            count += dc(right)

            right.sort()
            left.sort()

            l, r = len(left) - 1, len(right) - 1
            while l >= 0 and r >= 0:
                if left[l] > 2*right[r]:
                    count += r + 1
                    l -= 1
                else:
                    r -= 1

            return count

        return dc(nums)

class Solution(object):
    def reversePairs(self, nums):
        """
        :type nums: List[int]
        :rtype: int
        """
        def merge(array,start,mid,end):
            leftArray=array[start:mid+1]
            rightArray=array[mid+1:end+1]
            i,j=0,0
            m,n=len(leftArray),len(rightArray)
            for k in range(start,end+1):
                if j>=n or (i<m and leftArray[i]<rightArray[j]):
                    array[k]=leftArray[i]
                    i+=1
                else:
                    array[k]=rightArray[j]
                    j+=1
        def merge_sort(array,start,end):
            pairs=0
            if start<end:
                mid=start+(end-start)//2
                pairs+=merge_sort(array,start,mid)
                pairs+=merge_sort(array,mid+1,end)
                j=mid+1
                for i in range(start,mid+1):
                    while j<=end and array[i]>array[j]*2:
                        j+=1
                    pairs+=j-mid-1
                merge(array,start,mid,end)
            return pairs
        pairs=merge_sort(nums,0,len(nums)-1)
        return pairs

class Solution:    
    def findTargetSumWays(self, nums: List[int], target: int) -> int:     
        dic = defaultdict(int)

        def dfs(index=0, total=0):          
            key = (index, total)

            if key not in dic:
                if index == len(nums):                    
                    return 1 if total == target else 0
                else:
                    dic[key] = dfs(index+1, total + nums[index]) + dfs(index+1, total - nums[index])                    

            return dic[key]                                                             

        return dfs()

class Solution:
    def findTargetSumWays(self, nums: List[int], target: int) -> int:
        sumOfNums = sum(nums)
        n = len(nums)

        if target > sumOfNums:
            return 0

        if (target + sumOfNums) % 2 != 0:
            return 0

        s1 = (sumOfNums + target) // 2

        # DP Table
        t = [[0] * (s1 + 1) for i in range(n + 1)]

        t[0][0] = 1

        for i in range(1, n + 1):
            for j in range(s1 + 1):

                if nums[i - 1] <= j:
                    t[i][j] = t[i - 1][j] + t[i - 1][j - nums[i - 1]]

                else:
                    t[i][j] = t[i-1][j]

        return t[n][s1]

class Solution:
    def findTargetSumWays(self, nums: List[int], S: int) -> int:
        nums = [0]+nums
        @lru_cache(None)
        def dp(i, total):
            if i == 0: return total == 0
            return dp(i-1, total - nums[i]) + dp(i-1, total + nums[i])

        return dp(len(nums)-1, S)

class Solution:
    def findTargetSumWays(self, nums: List[int], target: int) -> int:

        # Global memorization to save time
        dic = defaultdict(int)
        l = len(nums)

        # DFS Tree with memorization
        def dfs(i, tol):
            # End condtion for recursive function
            if i == l:
                return 1 if tol == target else 0
            # Addition step to save time 
            # Get the memorization from previous DFS path
            if (i, tol) in dic:
                return dic[(i, tol)]
            # No memorization calulate path after equal to target recursively
            else:
                dic[(i,tol)] = dfs(i+1, tol + nums[i]) + dfs(i+1, tol - nums[i])
                return dic[(i,tol)]

        return dfs(0,0)

class Solution:
    def findTargetSumWays(self, nums: List[int], S: int) -> int:
        if S > sum(nums):
            return 0;
        if (S+sum(nums))%2!=0 :
            return 0;

        c=0
        for i in nums:
            if i==0:
                c+=1

        s= (S+sum(nums))//2
        n=len(nums)

        k=[[0 for i in range (s+1)] for j in range(n+1)]
        for i in range(n+1):
            k[i][0]=1
        for i in range(1,s+1):
            k[0][i]=0


        for i in range(1,n+1):
            for j in range(1,s+1):
                if nums[i-1]==0:
                    k[i][j] = k[i-1][j];
                elif nums[i-1]> j:
                    k[i][j]= k[i-1][j]
                else:
                    k[i][j]= k[i-1][j-nums[i-1]] + k[i-1][j]

        return 2**c * k[n][s]

class Solution:
    def findTargetSumWays(self, nums: List[int], S: int) -> int:
        if not nums: return 0
        dp = {}
        dp[nums[0]] = 1
        dp[-nums[0]] = 1 if nums[0]!= 0 else 2
        for i in range(1,len(nums)):
            temp = {}
            for sum in dp:
                temp[sum+nums[i]]=temp.get(sum+nums[i],0)+dp.get(sum,0)
                temp[sum-nums[i]]=temp.get(sum-nums[i],0)+dp.get(sum,0)
            dp= temp
        if S in dp: return dp[S]
        return 0

class Solution:
    def findTargetSumWays(self, nums: List[int], target: int) -> int:
        n = len(nums)
        cache = {}

        def dp(i, curr):
            if (i, curr) in cache:
                return cache[(i, curr)]
            if i == n:
                return int(curr == target)

            cache[(i,curr)] = dp(i+1, curr + nums[i]) + dp(i+1, curr - nums[i])
            return cache[(i, curr)]

        return dp(0, 0)

class Solution:
    def findTargetSumWays(self, nums: List[int], target: int) -> int:
        mp = {0:1}
        for n in nums:
            temp = {}
            for s in mp.keys():
                temp[s+n] = temp[s+n] + mp[s] if s+n in temp else mp[s]
                temp[s-n] = temp[s-n] + mp[s] if s-n in temp else mp[s]
            mp = temp
        return mp[target] if target in mp else 0

class Solution:
    def findTargetSumWays(self, nums: List[int], target: int) -> int:
        if len(nums) == 1:
            if target != nums[0] and target != -nums[0]: 
                return 0
            else: return 1
        temp = target + sum(nums)
        if temp % 2 != 0: return 0
        targetSum = temp // 2 
        prev = [0] * (targetSum + 1)
        prev[0] = 1

        for i in range(len(nums)):
            current = [0] * (targetSum + 1)
            for s in range(targetSum + 1):
                if s < nums[i]:
                    current[s] = prev[s]
                else:
                    current[s] = prev[s - nums[i]] + prev[s]
            prev = current.copy()

        return current[targetSum]

class Solution(object):
    def findPoisonedDuration(self, timeSeries, duration):
        repeat = 0
        for i in range(len(timeSeries)-1):
            diff = timeSeries[i+1] - timeSeries[i]
            if diff < duration:
                repeat += duration - diff
        return len(timeSeries)*duration - repeat

