class Solution:
    def nextGreaterElement(self, nums1: List[int], nums2: List[int]) -> List[int]:
        # build a hashmap for nums1: O(|nums1|)
        # Then iterate nums2, maintaining a stack: O(|nums2|)

        n1_index = {v: i for i, v in enumerate(nums1)}
        ans = [-1] * len(nums1)
        stack = []  # Stack of numbers from nums1, maintained with smallest number at end/top
        for v in nums2:
            # maintain stack
            while stack and stack[-1] < v:
                x = stack.pop()
				# mark in ans the next greater element
                ans[n1_index[x]] = v
            # maybe add to stack
            if v in n1_index:
                stack.append(v)
        return ans

class Solution:
    def nextGreaterElement(self, nums1: List[int], nums2: List[int]) -> List[int]:

        #nums1 is a subset of nums2
        n2 = len(nums2)
        arr = []
        answer = []
        for i in nums1:
            for j in range(0, n2):
                if i == nums2[j]:
                    arr.append(j)

        #arr contains j values : 2, 0 , 3, which is the index at which elements of nums1 are present in nums2
        #now, traverse from (j+1) till n2 and check, as soon as any element is > than this, break
        for i in arr:
            for j in range(i+1, n2):
                if nums2[j] > nums2[i]:
                    answer.append(nums2[j])
                    break
            else:
                answer.append(-1)
        return answer

