class Solution:
    def findDiagonalOrder(self, mat: List[List[int]]) -> List[int]:
        M,N = len(mat), len(mat[0])
        diagonals = []

        # traverse first column
        for i in range(len(mat)):
            idx_i = i
            idx_j = 0
            diagonals.append([])
            while idx_i >= 0 and idx_j < N:
                diagonals[-1].append(mat[idx_i][idx_j])
                idx_i -= 1
                idx_j += 1

        # traverse last row
        for i in range(1, len(mat[-1])):
            idx_i = M-1
            idx_j = i
            diagonals.append([])
            while idx_j < N and idx_i>=0:
                diagonals[-1].append(mat[idx_i][idx_j])
                idx_i -= 1
                idx_j += 1

        # combine everything to answer
        answer = []
        for i, d in enumerate(diagonals):
            if i % 2 == 0:
                answer += d
            else:
                answer += d[::-1]
        return answer

class Solution:
    def findDiagonalOrder(self, mat: List[List[int]]) -> List[int]:
       flip=0
        res=[]
        R=len(mat)
        C=len(mat[0])
        def checker(r,c):
            if r<0 or c<0 or r>=R or c>=C:
                return False
            return True
        def runner(r,c):
            temp=[]
            while checker(r,c):
                temp.append(mat[r][c])
                r-=1
                c+=1
            if flip:
                temp.reverse()
            res.extend(temp)
        for i in range(R):
            runner(i,0)
            flip=not flip
        for i in range(1,C):
            runner(R-1,i)
            flip=not flip

        return res

