    def convertToBase7(self, num: int) -> str:
        ans, sign = deque(), ""
        if num == 0: return "0"
        if num  < 0: num, sign = abs(num), "-"

        while num:
            ans.appendleft(num%7)
            num //= 7

        return sign + reduce(add, map(str, ans))

