class Solution:
    def largestValues(self, root: Optional[TreeNode]) -> List[int]:
        res = []

        if root == None:
            return res

        queue = collections.deque([root])

        while queue:
            cur_max = -float('inf')
            next_lvl = collections.deque([])
            while queue:
                node = queue.popleft()
                cur_max = max(cur_max, node.val)

                if node.left:
                    next_lvl.append(node.left)
                if node.right:
                    next_lvl.append(node.right)

            res.append(cur_max)
            queue = next_lvl

        return res

