        self.nums = m * n

        self.tail = self.nums - 1
        self.indexes = {}


    def flip(self) -> List[int]:
        ind = random.randint(0, self.tail)
        rc = self.indexes.get(ind, ind)
        self.indexes[ind] = self.indexes.get(self.tail, self.tail)
        self.tail -= 1

        return [rc // self.cols, rc % self.cols]


    def reset(self) -> None:
        self.tail = self.nums - 1
        self.indexes = {}

