            """Return number of beautiful arrangements."""
            if k == N: return 1 # boundary condition
            ans = 0
            for kk in range(k, N):
                if nums[kk] % (k+1) == 0 or (k+1) % nums[kk] == 0: 
                    nums[k], nums[kk] = nums[kk], nums[k]
                    ans += fn(k+1)
                    nums[k], nums[kk] = nums[kk], nums[k]
            return ans 

