class Solution:
    def countArrangement(self, n: int) -> int:
        res = []
        self.backtrack(n, [], res)
        return len(res)
    def backtrack(self, n, curr, res):
        if len(curr) == n:
            res.append(curr[:])
        for i in range(1, n+1):
            leng = len(curr)+1
            if i in curr: continue
            if len(curr)> 0 and (leng % i != 0) and (i % leng != 0): continue
            curr.append(i)
            self.backtrack(n, curr, res)
            curr.pop()

class Solution:
    def countArrangement(self, n: int) -> int:

        # Work out which digits can go in which positions and store in options
        options = {}
        for i in range(1,n+1):
            options[i] = []
            for j in range(1,n+1):
                if i % j == 0 or j % i == 0:
                    options[i].append(j)


        # Recursively add digits to the array from options provided they have not already been used
        def add_digit(curr, i, n, options):
            if i > n:
                return 1
            count = 0
            for d in options[i]:
                if d not in curr:
                    new = curr.copy()
                    new.append(d)
                    count += add_digit(new, i+1, n, options)
            return count

        return add_digit([], 1, n, options)

