    def convertBST(self, root: Optional[TreeNode], passdown=0) -> Optional[TreeNode]:
        if not root: 
            return None
        root.val = self.getNewVal(root, passdown)
        root.left = self.convertBST(root.left, root.val)
        if passdown: 
