class Solution:
    def reverseStr(self, s: str, k: int) -> str:

        if k >= len(s):
            return s[::-1]

        i = 0
        s = list(s)
        while i < len(s):
            l = i
            h = (i + k - 1) if (i + k - 1) < len(s) else len(s) - 1
            while l < len(s) and l < h:
                s[l], s[h] = s[h], s[l]
                l += 1
                h -= 1
            i += (2 * k)
        return "".join(s)

class Solution:
    def reverseStr(self, s: str, k: int) -> str:
        def reverse1(s, k):
            if len(s)<k:
                return s[::-1]
            if len(s)>=k and len(s)<=2*k:
                s1 = s[:k]; s2 = s[k:]
                s1 = list(s1)
                i = 0; j = len(s1)-1
                while(i<j):
                    temp = s1[i]; s1[i] = s1[j]; s1[j] = temp
                    i+=1; j-=1
                s1 = ''.join(s1)
                return s1+s2
            else:
                return reverse1(s[:(2*k)], k) + reverse1(s[(2*k):], k)
        s = reverse1(s, k)
        return s

class Solution:
	def updateMatrix(self, mat: List[List[int]]) -> List[List[int]]:
		row, col = len(mat), len(mat[0])
		queue = deque([])

		for x in range(row):
			for y in range(col):
				if mat[x][y] == 0:
					queue.append((x, y, 1))


		return self.bfs(row, col, queue, mat)

	def bfs(self, row, col, queue, grid):
		visited = set()
		while queue:
			x, y, steps = queue.popleft()

			for nx, ny in [[x+1,y], [x-1,y], [x,y+1], [x,y-1]]:
				if 0<=nx<row and 0<=ny<col and (nx,ny) not in visited:
					if grid[nx][ny] == 1:
						visited.add((nx,ny))
						grid[nx][ny] = steps
						queue.append((nx, ny, steps+1))

		return grid

class Solution:
    def updateMatrix(self, mat: List[List[int]]) -> List[List[int]]:
