class Solution:
    def updateMatrix(self, matrix: List[List[int]]) -> List[List[int]]:
        m, n = len(matrix), len(matrix[0])
        front = set((i, j) for i in range(m) for j in range(n) if not matrix[i][j]) # frontier 
        seen = front.copy() # visited cell 

        k = 0
        while front: # bfs by frontier
            newf = set() # new frontier 
            for i, j in front: 
                matrix[i][j] = k
                for ii, jj in (i-1, j), (i, j-1), (i, j+1), (i+1, j):
                    if 0 <= ii < m and 0 <= jj < n and (ii, jj) not in seen: newf.add((ii, jj))
            front = newf
            seen |= newf
            k += 1
        return matrix

class Solution:
