class Solution:
    def updateMatrix(self, mat: List[List[int]]) -> List[List[int]]:
        mat = mat
        n = len(mat)
        m = len(mat[0])
        # init with +inf
        ans = [[float('inf')]*m for _ in range(n)]

        # from top left to bottom right, as we usually do
        for i in range(n):
            for j in range(m):
                if mat[i][j]: # if non-zero value
					# we actually only consider the top and the left neighbour
					# why? those are the ones we've already seen, and are thus optimized
                    if j > 0: ans[i][j] = min(ans[i][j], ans[i][j-1]+1)
                    if i > 0: ans[i][j] = min(ans[i][j], ans[i-1][j]+1)
                else: # if zero, that is the answer
                    ans[i][j] = 0

        # this time both ranges are reversed
        for i in reversed(range(n)):
            for j in reversed(range(m)):
                if mat[i][j]:
                    if j+1 < m: ans[i][j] = min(ans[i][j], ans[i][j+1]+1)
                    if i+1 < n: ans[i][j] = min(ans[i][j], ans[i+1][j]+1)
                else:
                    ans[i][j] = 0
        return ans

class Solution:
    def diameterOfBinaryTree(self, root: TreeNode) -> int:
        def height(root):
            nonlocal diameter
            if not root:
                return 0

            left = height(root.left)
            right = height(root.right)
            diameter = max(diameter, left + right)
            return max(left, right) + 1

        diameter = 0
        height(root)
        return diameter

class Solution:
    def maxPathSum(self, root: TreeNode) -> int:
        def maxPath(root):
            nonlocal maxSum
            if not root:
                return 0

            left = maxPath(root.left)
            right = maxPath(root.right)
            maxSum = max(maxSum, left + right + root.val)
            return max(left + root.val, right + root.val, 0)

        maxSum = -math.inf  
        maxPath(root)
        return maxSum

class Solution:
    def diameterOfBinaryTree(self, root: TreeNode) -> int:

        def fn(node):
            """Return length+1 and diameter rooted at node"""
            if not node: return (0, 0)
            l1, d1 = fn(node.left)
            l2, d2 = fn(node.right)
            return 1 + max(l1, l2), max(d1, d2, l1+l2)

        return fn(root)[1]

class Solution:
    def diameterOfBinaryTree(self, root: Optional[TreeNode]) -> int:
