        self.findDiameter(root, result)
        return result[0]

    def findDiameter(self, root, result):
        if not root:
            return 0

        left = self.findDiameter(root.left, result)
        right = self.findDiameter(root.right, result)

        result[0] = max(result[0], left + right)

        return max(left, right) + 1

class Solution:
    def diameterOfBinaryTree(self, root: Optional[TreeNode]) -> int:
        return self.findDiameter(root)[1]

    def findDiameter(self, root):
        if not root:
            return (0, 0)

        left = self.findDiameter(root.left)
        right = self.findDiameter(root.right)

        currentDiameter = left[0] + right[0]
        maxDiameter = max(left[1], right[1], currentDiameter)

        return (max(left[0], right[0]) + 1, maxDiameter)

class Solution:
    def diameterOfBinaryTree(self, root: TreeNode) -> int:
        ans = 0
        hm = {}
        stack = [(root, False)]

        while stack:
            node, visited = stack.pop()
            if node:
                if visited:
                    lh = 0 if node.left is None else hm.pop(node.left)
                    rh = 0 if node.right is None else hm.pop(node.right)
                    ans = max(ans, lh + rh)
                    hm[node] = max(lh, rh) + 1
                else:
                    stack.append((node, True))
                    stack.append((node.left, False))
                    stack.append((node.right, False))
        return ans

class Solution:
    def removeBoxes(self, boxes: List[int]) -> int:

        @cache
        def fn(lo, hi, k): 
            """Return max score of removing boxes from lo to hi with k to the left."""
            if lo == hi: return 0 
            while lo+1 < hi and boxes[lo] == boxes[lo+1]: lo, k = lo+1, k+1
            ans = (k+1)*(k+1) + fn(lo+1, hi, 0)
            for mid in range(lo+2, hi): 
                if boxes[lo] == boxes[mid]: 
                    ans = max(ans, fn(lo+1, mid, 0) + fn(mid, hi, k+1))
            return ans 

        return fn(0, len(boxes), 0)

class Solution:
    def removeBoxes(self, boxes: List[int]) -> int:

        @cache
        def dp(l, r, count = 0):
            if l > r: return 0
            // Initial count for the letter at boxes[l]
            count += 1
            ptr = l + 1
            while ptr <= r and boxes[l] == boxes[ptr]:
                ptr += 1
                count += 1
            points = (count ** 2) + dp(ptr, r)
            for i in range(ptr + 1, r + 1):
                if boxes[l] == boxes[i]:
                    points = max(points, dp(i, r, count) + dp(ptr, i - 1))
            return points

        return dp(0, len(boxes) - 1)

class Solution:
    def findCircleNum(self, M: List[List[int]]) -> int:
        dsu = DSU(len(M))
        for i, r in enumerate(M):
            for j, v in enumerate(r):
                if j > i - 1: break
                if v == 1:
                    dsu.union(i, j)
        return dsu.numFrdCir

class DSU:
    def __init__(self, num):
        self.numFrdCir = num
        self.par = list(range(num))
        self.rnk = [0] * num

    def find(self, x):
        if self.par[x] != x:
            self.par[x] = self.find(self.par[x])
        return self.par[x]

    def union(self, x, y):
        xr, yr = self.find(x), self.find(y)
        if xr == yr:
			return
        elif self.rnk[xr] < self.rnk[yr]:
            self.par[xr] = yr
        elif self.rnk[xr] > self.rnk[yr]:
            self.par[yr] = xr
        else:
            self.par[yr] = xr
            self.rnk[xr] += 1
        self.numFrdCir -= 1

class Solution:
    def findCircleNum(self, isConnected: List[List[int]]) -> int:
        n = len(isConnected)
        visited = [False]*n
        def trev(u):
            if not visited[u]:
                visited[u] = True
                for i in range(n):
                    if isConnected[i][u]: #treveses all the conneted nodes
                        trev(i)
        ans = 0
        for i in range(n):
            if not visited[i]: #only traverses untravesed nodes
                trev(i)
                ans+=1
        return ans

class Solution:
	"""
	Time:   O(n^2)
	Memory: O(n)
	"""

	def findCircleNum(self, isConnected: List[List[int]]) -> int:
		n = len(isConnected)
		dsu = DSU(n)

		for i in range(n):
			for j in range(n):
				if isConnected[i][j]:
					dsu.union(i, j)

		return len({dsu.find(i) for i in range(n)})

class Solution:
    def findCircleNum(self, isConnected: List[List[int]]) -> int:
#  set all parents value to 1 that is node is a parent of itself
        par=[i for i in range(len(isConnected))]
#  rank is the length of the particular component at that index, initially all are disjoint components so default to 1
        rank=[1]*(len(isConnected))

        def find(n):
            p=n
            while p!=par[p]:
                par[p]=par[par[p]]
                p=par[p]
            return p

        def union(n1,n2):
            p1,p2=find(n1),find(n2)
            if p1==p2:
                return 0
#  if parent of p1 is greater than the parent of p2 , then set p2's parent as p1 and increment the rank of p1
            if par[p1]>par[p2]:
                par[p2]=p1
                rank[p1]+=rank[p2]
            else:
#  if parent of p2 is greater than the parent of p1 , then set p1's parent as p2 and increment the rank of p2
                par[p1]=p2
                rank[p2]+=rank[p1]
            return 1
# keep track of the total count (i.e initially we consider all components are disjoint so count is nothing but a length of the array itself )
        count=len(isConnected)
        for i in range(len(isConnected)):
            for j in range(len(isConnected[i])):
# traverse through array and if we find the connection between node i and j that is represented as 1 in the question, then it means that our connected component is decreasing by return value of union function so count-=union(i,j)
                if isConnected[i][j]==1:
                    count-=union(i,j)
        return count

class Solution:
    def findCircleNum(self, isConnected: List[List[int]]) -> int:
        class UnionFind:
            # Constructor of Union-find. The size is the length of the root array.
            def __init__(self, size):
                self.root = [i for i in range(size)]
                self.rank = [1]*size
                self.province = size

            # find the root with path compression
            def find(self, x):
                if self.root[x] == x:
                    return x
                # recursively find the root and compress
                self.root[x] = self.find(self.root[x])  

                return self.root[x]

            # union by rank
            def union(self, x, y):
                rootX = self.find(x)
                rootY = self.find(y)
                if rootX != rootY:
                    if self.rank[rootX] > self.rank[rootY]:
                        self.root[rootY] = rootX
                    elif self.rank[rootX] < self.rank[rootY]:
                        self.root[rootX] = rootY
                    else:
                        self.root[rootY] = rootX
                        self.rank[rootX] += 1
                    self.province -= 1

        size =len(isConnected)

        disjoint_set = UnionFind(size)

        for i in range(size):
            for j in range(i+1,size):
                if isConnected[i][j]:
                    disjoint_set.union(i,j)

        return disjoint_set.province

class Solution:
    def findCircleNum(self, isConnected: List[List[int]]) -> int:
        n = len(isConnected)
        nb_provinces = 0

        def dfs(city_a: int) -> None:
            for city_b in range(n):
                if isConnected[city_a][city_b] == 1:
                    isConnected[city_a][city_b] = 0
                    isConnected[city_b][city_a] = 0
                    dfs(city_b)

        for city in range(n):
            if isConnected[city][city]==1:
                dfs(city)
                nb_provinces += 1

        return nb_provinces

class Solution:
    def findCircleNum(self, isConnected: List[List[int]]) -> int:
        n = len(isConnected)
        parent = [i for i in range(0, n)]
        rank = [0] * n

        # Initially there are n components
        components = n

        # Only traversing half of 2d array, since edges are bidirectional
        for i in range(0, len(isConnected)):
            for j in range(i+1, len(isConnected)):
                if(isConnected[i][j] == 1):
                    merge_components = self.union(i, j, parent, rank)
                    if(merge_components):
                        components -= 1
        return components


    def union(self, x, y, parent, rank):
        fx = self.find(x, parent)
        fy = self.find(y, parent)

        if(fx == fy):
            return False

        rankx = rank[fx]
        ranky = rank[fy]

        if(rankx > ranky):
            parent[fy] = fx
        elif(rankx < ranky):
            parent[fx] = fy
        else:
            parent[fy] = fx
            rank[fx] += 1
        return True


    def find(self, x, parent):
        if(parent[x] != x):
            parent[x] = self.find(parent[x], parent)
        return parent[x]

