    def findCircleNum(self, isConnected: List[List[int]]) -> int:

        def dfsHelper(v,visited,isConnected):
            # dfs search for all the connected components
            visited[v]=True
            for neigh in range(len(isConnected[v])):
                if visited[neigh]==False and isConnected[v][neigh]==1:
                    dfsHelper(neigh,visited,isConnected)

        visited = [False for i in range(len(isConnected))]
        # no. of provinces = cnt
        cnt = 0
        for i in range(len(isConnected)):
            # we only call the ones which are not yet visited, which results in provinces
            if visited[i]==False:
                dfsHelper(i,visited,isConnected)
                cnt+=1

        return cnt

