class Solution:
    def isSubtree(self, root: Optional[TreeNode], subRoot: Optional[TreeNode]) -> bool:

        def fn(x, y): 
            """Return True if a match is found."""
            if not x or not y: return x is y
            return x.val == y.val and fn(x.left, y.left) and fn(x.right, y.right)

        stack = [root]
        while stack: 
            node = stack.pop()
            if fn(node, subRoot): return True 
            if node.right: stack.append(node.right)
            if node.left: stack.append(node.left)
        return False

class Solution:
    #--------------traversal-------------#
    def isSubtree(self, root: Optional[TreeNode], subRoot: Optional[TreeNode]) -> bool:
        root_list = []
        subroot_list = []
        self.pre_order(root, root_list)
        self.pre_order(subRoot, subroot_list)
        return "".join(subroot_list) in "".join(root_list)

    def pre_order(self, node, pre_order_list):
        if not node:
            pre_order_list.append("$")  # prevent the back of a left tree concatenated with the front of a right tree is the whole subtree
            return 

        pre_order_list.append('-' + str(node.val) + '|')  # prevent '2' in '12' == True or '1' in '12' == True

        self.pre_order(node.left, pre_order_list)
        self.pre_order(node.right, pre_order_list)

