    def findPaths(self, m: int, n: int, maxMove: int, startRow: int, startColumn: int) -> int:
        # grid = [[0] * n] * m
        q = collections.deque()
        q.append((startRow, startColumn))
        res = 0
        while q:
            if maxMove == 0:
                break
            for _ in range(len(q)):
                r, c = q.popleft()

                if r != m-1:
                    q.append((r+1,c))
                else:
                    res += 1

                if r != 0:
                    q.append((r-1,c))
                else:
                    res += 1

                if c != n-1:
                    q.append((r,c+1)) 
                else:
                    res += 1

                if c != 0:
                    q.append((r,c-1)) 
                else:
                    res += 1

            maxMove -= 1

        return res % ((10 ** 9) + 7)

