class Solution:
    def outerTrees(self, points: List[List[int]]) -> List[List[int]]:
        """
        Use Monotone Chain algorithm.
        """
        def is_clockwise(
                p0: List[int], p1: List[int], p2: List[int]) -> bool:

            return (p1[1] - p0[1]) * (p2[0] - p0[0]) > (p2[1] - p0[1]) * (p1[0] - p0[0])

        sortedPoints = sorted(points)

        hull = []
        for p in sortedPoints:
            while len(hull) > 1 and is_clockwise(hull[-2], hull[-1], p):
                hull.pop()

            hull.append(p)

        if len(hull) == len(points):
            return hull

        hull.pop()
        for p in reversed(sortedPoints):
            while len(hull) > 1 and is_clockwise(hull[-2], hull[-1], p):
                hull.pop()

            hull.append(p)

        hull.pop()

        return hull

