class Rational:
    # We represent a rational number as a pair (a, b) such that
    # a is an integer, b is a natural number and gcd(a, b) = 1.
    def __init__ (self, a: int, b: int):
        assert b != 0

        aa = abs(a)
        bb = abs(b)
        d = gcd(aa, bb)

        if (a < 0 and b > 0) or (a > 0 and b < 0):
            self.a = -1 * (aa // d)
        else:
            self.a = aa // d

        self.b = bb // d

    def __str__(self):
        return f"{self.a}/{self.b}"

    def __add__ (self, r):
        return Rational(self.a*r.b + self.b*r.a, self.b*r.b)

    def __sub__ (self, r):
        return Rational(self.a*r.b - self.b*r.a, self.b*r.b)

    def __eq__ (self, r):
        return self.a == r.a and self.b == r.b
    def __ne__ (self, r):
        return self.a != r.a or self.b != r.b

    def gcd(self, c, d):
        if d == 0:
            return c

        return gcd(d, c % d)

