class Solution:
    def leastInterval(self, tasks: [str], n: int) -> int:
        from collections import Counter
        import heapq
        jobq = [-v for v in Counter(tasks).values()]
        waitingq = []
        heapq.heapify(jobq)
        ret = 0
        while jobq or waitingq:
            while waitingq and ret - n > waitingq[0][0]:
                _, priority = waitingq.pop(0)
                heapq.heappush(jobq, priority)
            if jobq:
                priority = heapq.heappop(jobq)
                if priority < -1:
                    waitingq.append((ret, priority + 1))
            ret += 1
        return ret

