    def kInversePairs(self, n: int, k: int) -> int:

        @cache
        def fn(n, k):
            """Return number of ways for n numbers with k inverse pairs."""
            if k == 0: return 1 
            if n <= 0 or k < 0: return 0 
            return fn(n-1, k) + fn(n, k-1) - fn(n-1, k-n)

        return fn(n, k) % 1_000_000_007

class Solution:
    def kInversePairs(self, n: int, k: int) -> int:
        memo = [0 for i in range(k+1)]
        memo[0] = 1
        for i in range(2,n+1):
            tmp = [0 for i in range(k+1)]
            tmp[0] = 1
            for j in range(1,k+1):
                tmp[j] = tmp[j-1] + memo[j] - (memo[j-i] if j-i>=0 else 0)
            memo = tmp
        return memo[k] % (10**9+7)

class Solution:
    def kInversePairs(self, n: int, k: int) -> int:
        curr = [0 for _ in range(k+1)]
        prev = [0 for _ in range(k+1)]
        for i in range(1,n+1):
            value = 0
            for j in range(k+1):
                if j == 0:
                    curr[j] = 1
                    value += prev[j]
                else:
                    if j >= i:
                        value-=prev[j-i]
                    value+=prev[j]
                    curr[j] = value
            curr,prev = prev,curr
        return prev[-1] % (10**9+7)

