        stime = 0
        for d, e in courses:
            heappush(heap, -d)               # push the duration in heap
            stime += d                       # sum of durations (total time taken to read) => D
            while stime > e:                 # check D > end 
                stime += heappop(heap)       # removing the largest duration from heap
        return len(heap)

