class Solution:
    def replaceWords(self, dictionary: List[str], sentence: str) -> str:
        root = defaultdict(dict)
        output = ''

        for word in dictionary:
            word += '.'
            current = root

            for c in word:
                if c not in current:
                    current[c] = defaultdict(dict)

                current = current[c]

        words = sentence.split()

        for i, word in enumerate(words):
            current = root
            s = ''

            for c in word:
                if c not in current:
                    break

                if '.' in current:
                    break

                current = current[c]
                s += c

            if '.' in current:
                output += s
            else:
                output += word

            if i < len(words) - 1:
                output += ' '

        return output

class Solution:
    def predictPartyVictory(self, senate: str) -> str:
        radiant, dire = deque(), deque()
        for i, x in enumerate(senate): 
            if x == "R": radiant.append(i)
            else: dire.append(i)
        while radiant and dire: 
            if radiant[0] < dire[0]: 
                radiant.append(radiant.popleft()+len(senate))
                dire.popleft()
            else: 
                radiant.popleft()
                dire.append(dire.popleft()+len(senate))
        return "Radiant" if radiant else "Dire"

class Solution:
    def predictPartyVictory(self, senate: str) -> str:
        R_idx = deque([i for i in range(len(senate)) if senate[i]=='R'])
        D_idx = deque([j for j in range(len(senate)) if senate[j]=='D'])
        n = len(senate)
        while R_idx and D_idx:
            r = R_idx.popleft()
            d = D_idx.popleft()
            if r < d:
                R_idx.append(n + r)
            else:
                D_idx.append(n + d)
        return 'Radiant' if R_idx else 'Dire'

class Solution:
    # O(n) time,
    # O(n) space,
    # Approach: greedy, hashset
    def predictPartyVictory(self, senate: str) -> str:
        n = len(senate)
        count = Counter(senate)

        skip_r = 0
        skip_d = 0
        removed_r = set()
        removed_d = set()
        while count['D'] > 0 and count['R'] > 0:
            for i in range(n):
                s = senate[i]
                if s == 'R':
                    if skip_r <= 0 and i not in removed_r:
                        count['D'] -=1
                        skip_d +=1
                    else:
                        if i not in removed_r:
                            skip_r -=1
                            removed_r.add(i)
                else:
                    if skip_d <= 0 and i not in removed_d:
                        count['R'] -=1
                        skip_r +=1
                    else:
                        if i not in removed_d:
                            skip_d -=1
                            removed_d.add(i)

        if count['D'] > 0:
            return 'Dire'
        else:
            return 'Radiant'

class Solution:
    def predictPartyVictory(self, senate: str) -> str:
        d, r = senate.count("D"), senate.count("R")
        killedR, killedD = 0, 0
        deleted = set()
        while d and r:
            for idx,letter in enumerate(senate):
                if idx in deleted: continue
                if letter == "R" and killedR == 0:
                    killedD += 1
                    d -= 1
                elif letter == "D" and killedD == 0:
                    killedR += 1
                    r -= 1
                elif letter == "R" and killedR > 0:
                    deleted.add(idx)
                    killedR -= 1
                else:
                    deleted.add(idx)
                    killedD -= 1
        return "Dire" if d else "Radiant"

class Solution:
    def minSteps(self, n: int) -> int:

        dp = [float('inf')] * (n+1)	
		## Intialize a dp array to store the solutions of sub problems i.e. number of steps needed

        dp[1] = 0
		## Intially first element of dp array with 0 as 'A' is already present and we haven't consumed any steps yet. 
		## As the value of n is from [1,3000] and initally 'A' is already present so we don't need to bother about the dp[0]

        divisors = []
		## This is to store the divisors of N

        for i in range(1, n//2 + 1):
            if n % i == 0:
                divisors.append(i)
		## We have stored all the divisors. For n = 10, divisors = [1,2,5]

        for j in divisors:
            dp[j] += 1
			##To copy the current number of A's, we add one step

            for i in range(j+1, n+1):
                if i % j == 0:
				## We can only form the string length which is divisible by j 
                    dp[i] = min(dp[i], dp[i-j] + 1)
					## Compare with previous number of steps and update with the minimum
        return dp[-1]
		#Return last value of dp i.e. N

class Solution:
    def minSteps(self, n: int) -> int:
        cache = {}
        def helper(screen, clipboard):
            if (screen, clipboard) in cache: return cache[(screen, clipboard)]
            if screen == n: return 0
            if screen > n: return float("Inf")

            copy_paste = helper(screen+screen, screen) + 2
            paste = float("Inf")
            if clipboard:
                paste = helper(screen + clipboard, clipboard) + 1

            cache[(screen, clipboard)] = min(copy_paste, paste)    
            return cache[(screen, clipboard)]

        return helper(1, 0)

class Solution:
    def Util(self, cur, stored, n, mem):

        if cur > n or stored > n:
            return sys.maxsize

        if cur == n:
            return 0

        if (cur, stored) in mem:
            return mem[(cur, stored)]

        if stored == 0:
            return 1 + self.Util(cur, 1, n, mem)

        if cur != stored:
            ans = 1 + min(self.Util(cur + stored, stored, n, mem), self.Util(cur, cur, n, mem))

        else:      
            ans = 1 + self.Util(cur + stored, stored, n, mem)

        mem[(cur, stored)] = ans
        return ans

    def minSteps(self, n: int) -> int:
        if n == 0 or n == 1:
            return 0
        mem = dict()
        return self.Util(1, 0, n, mem) # initially, we have 1'A' and 0 number of 'A's copied

