    def findDuplicateSubtrees(self, root: TreeNode) -> List[TreeNode]:

        seen = collections.defaultdict(int)
        res = []

        def helper(node):
            if not node:
                return
            sub = tuple([helper(node.left), node.val, helper(node.right)])
            if sub in seen and seen[sub] == 1:
                res.append(node)
            seen[sub] += 1
            return sub

        helper(root)
