class Solution:
    def findTarget(self, root: Optional[TreeNode], k: int) -> bool:
	    # isReverse: traversing in descending order.
        def BSTsearch(node, isReverse):
            l, r = node.left, node.right
            if isReverse:
                l, r = node.right, node.left
            if l:
                yield from BSTsearch(l, isReverse)
            yield node.val
            if r:
                yield from BSTsearch(r, isReverse)

        # Generator in ascending order 
        leftGen = BSTsearch(root, False)
		# Generator in descending order.
        rightGen = BSTsearch(root, True)

        left = leftGen.__next__()
        right = rightGen.__next__()

        while left < right:
            if left + right == k:
                return True
            if left + right > k:
                right = rightGen.__next__()
            else:
                left = leftGen.__next__()
        return False

