class Solution:
    def findTarget(self, root: Optional[TreeNode], k: int) -> bool:
        if not root:
            return False
        l_obj = BSTiterator(root, False)
        r_obj = BSTiterator(root, True)

        l, r = 0, 0

        if l_obj.hasNext():
            l = l_obj.next()
        if r_obj.hasNext():
            r = r_obj.next()

        while l != r:
            if l + r == k:
                return True
            if l + r < k:
                l = l_obj.next()
            else:
                r = r_obj.next()
        return False

class BSTiterator:
    def __init__(self, root, reverse):
        self.st = []
        self.reverse = reverse
        if self.reverse:
            while root:
                self.st.append(root)
                root = root.right
        else:
            while root:
                self.st.append(root)
                root = root.left

    def next(self):
        temp = self.st.pop()
        if self.reverse:
            l = temp.left
            while(l):
                self.st.append(l)
                l = l.right
        else:
            r = temp.right
            while(r):
                self.st.append(r)
                r = r.left
        return temp.val

    def hasNext(self):
        return len(self.st) != 0

