        if len(nums) <= 2:
            return True
        for i in range(1,len(nums)-1):
            # 3 1 2 pattern. if it's 3 2 1 then it will fail at the final check
            # becomes 1 1 2 pattern
            if (nums[i] < nums[i-1] and nums[i-1] > nums[i+1]):
                nums[i-1] = nums[i]
