            # 2 1 3 pattern or 1 3 2 pattern -> 2 2 3 pattern or 1 1 2 pattern
            elif (nums[i] < nums[i-1] and nums[i+1] > nums[i-1]) or (nums[i] > nums[i-1] and nums[i] > nums[i+1] and nums[i+1] > nums[i-1]):
