class Solution:
	def trimBST(self, root: Optional[TreeNode], low: int, high: int) -> Optional[TreeNode]:
		def recur(root):
			if root is None:
				return None

			#if root is larger than boundary, then we must return the next child that's within the boundary
			#in this case, only children to the left have a chance of working.
			if root.val > high:
				return recur(root.left)

			#if root is smaller than boundary, then we must return the next child that's within the boundary
			#in this case, only children to the right have a chance of working.
			elif root.val < low:
				return recur(root.right)

			#if the root falls within the boundary, assign their pointers to the next children that work.
			else:
				root.left = recur(root.left)
				root.right = recur(root.right)

			#if the root fell in the boundary, then return for previous recursive call to use.
			return root

		return recur(root)

