        while idx < len(s) and q:
            if int(s[idx]) < q[0]:
                res = [x for x in s]
                res[idx], res[iss[str(q[0])]] = res[iss[str(q[0])]], res[idx]
                return int(''.join([x for x in res]))
            elif int(s[idx]) == heap[0]:
                q.popleft()
            idx += 1
        return num

class Solution:
    def maximumSwap(self, num: int) -> int:
        # O(N), O(N)
        """
        2736 -> 7236
        9973 -> 9973
        9978 -> 9987

        # { 2 : 0, 7 : 1, 3 : 2, 6 : 3}
        # { 9 : 1, 7 : 2, 8 : 3}
        """
        # this num will convert into list [2, 7, 3, 6]
        num = list(map(int, str(num)))
        hashmap = {val : index for index, val in enumerate(num)}

        for index, val in enumerate(num):
            for searchval in range(9, val, -1):
                if searchval in hashmap and hashmap[searchval] > index:
                    # swap
                    num[index], num[hashmap[searchval]] = num[hashmap[searchval]], num[index]
                    return int("".join(map(str, num)))
        return int("".join(map(str, num)))

class Solution:
    def maximumSwap(self, num: int) -> int:
        num_arr = list(str(num)) # array with the number elements: 2736 -> ['2','7','3','6']

        hashmap = {} # dictionary to store the elements of num and their indices
        for index, number in enumerate(num_arr): # O(N)
            hashmap[number] = index

        for i in range(0, len(num_arr)): # rotate over all elements of num_arr
            max_number = max(num_arr[i:]) # maximum number of num_arr starting at index i
            index_max_number = hashmap[max_number] # index of the maximum number
            if num_arr[i] < num_arr[index_max_number]:
                num_arr[i], num_arr[index_max_number] =  num_arr[index_max_number], num_arr[i]
                break

        return int("".join(num_arr))

class Solution:
    def maximumSwap(self, num: int) -> int:
        pre, after, maxs, string = -1, -1, 0, str(num)[::-1]
        for index, char in enumerate(string):
            if int(char) > int(string[maxs]):
                maxs = index
            if int(char) < int(string[maxs]):
                pre, after = maxs, index
        return int(string[::-1]) if pre < 0 else int((string[:pre]+string[after]+string[pre+1:after]+string[pre]+string[after+1:])[::-1])

class Solution:
