class Solution:
    # Operations: O(flip odds), E(flip evens), A(flip all), T(flip 3k + 1), N(flip nothing)
    states = {
        'N': 0b000,
        'A': 0b111,
        'O': 0b101,
        'E': 0b010,
        'T': 0b001,
        'AT': 0b111 ^ 0b001,
        'OT': 0b101 ^ 0b001,
        'ET': 0b010 ^ 0b001,
    }
    steps = {
        0: ['N'],
        1: ['A', 'O', 'E', 'T'],
        2: ['N', 'A', 'O', 'E', 'AT', 'OT', 'ET'],
        3: states.keys(),
    }
    def flipLights(self, n: int, m: int) -> int:
        n, m = min(n, 3), min(m, 3)
        mask = (1 << n) - 1
        ans = set()
        for s in self.steps[m]:
            ans.add((0b111 ^ self.states[s]) &amp; mask)
        return len(ans)

class Solution:
    def findNumberOfLIS(self, nums):
        n = len(nums)

        dp, cnt, max_val = [1]*n, [1]*n, 1

        for i in range(1,n):
            for j in range(i):
                if nums[i] > nums[j]:
                    if dp[j] + 1 > dp[i]:
                        dp[i], cnt[i] = 1 + dp[j], cnt[j]
                    elif dp[j] + 1 == dp[i]:
                        cnt[i] += cnt[j]

            max_val = max(max_val,dp[i])

        return sum([j for i,j in zip(dp,cnt) if i == max_val])

class Solution:
    def findNumberOfLIS(self, nums: List[int]) -> int:

        longestDict = {}

        max_len = 1
        max_cnt = 1
        total_cnt = 0
        for i in range(len(nums)):
            # length of LIS and count of LIS
            longestDict[i] = [1, 1]

        for i in range(len(nums)-1,-1,-1):
            for j in range(i+1, len(nums)):
                if nums[i] < nums[j]:

                    # found another instance of present LIS length
                    if longestDict[i][0] == longestDict[j][0] + 1:
                        # increase the LIS count at i's position
                        longestDict[i][1] += longestDict[j][1]

                    # check if length of LIS could be more than current
                    elif longestDict[i][0] < longestDict[j][0] + 1:
                        # update length
                        longestDict[i][0] = longestDict[j][0] + 1
                        # since length increased update count to j's count
                        longestDict[i][1] = longestDict[j][1]

                        max_len = max(longestDict[i][0], max_len)

        for LIS_size, LIS_count in longestDict.values():
            if LIS_size == max_len:
                total_cnt += LIS_count

        return total_cnt

class Solution:
    def findNumberOfLIS(self, nums: List[int]) -> int:
        n = len(nums)
        dp = [1 for _ in range(n)]
        freq = [1 for _ in range(n)]
        for i in range(n):
            for j in range(i):
                if nums[j] < nums[i] and 1 + dp[j] >= dp[i]:
                    if dp[i] == 1 + dp[j]:
                        freq[i] += freq[j]
                    else:
                        freq[i] = freq[j]
                    dp[i] = 1 + dp[j]

        maximal = max(dp)
        res = 0
        for idx, num in enumerate(dp):
            if num == maximal:
                res += freq[idx]

        return res

class Solution:
    def findNumberOfLIS(self, nums: List[int]) -> int:
        if not nums: return 0
        n = len(nums)
        m, dp, cnt = 0, [1] * n, [1] * n
        for i in range(n):
            for j in range(i):
                if nums[j] < nums[i]:
                    if dp[i] < dp[j]+1: dp[i], cnt[i] = dp[j]+1, cnt[j]
                    elif dp[i] == dp[j]+1: cnt[i] += cnt[j]
            m = max(m, dp[i])                        
        return sum(c for l, c in zip(dp, cnt) if l == m)

