class Solution:
    def cutOffTree(self, forest: List[List[int]]) -> int:
        forest.append([0] * len(forest[0]))
        for row in forest: row.append(0)
        def bfs(end, start):
            if end == start: return 0
            visited, queue = set(), {start}
            visited.add(start)
            step = 0
            while queue:
                s = set()
                step += 1
                for p in queue:                    
                    for dr, dc in ((-1, 0), (1, 0), (0, 1), (0, -1)):
                        r, c = p[0] + dr, p[1] + dc
                        if not forest[r][c] or (r, c) in visited: continue
                        if (r, c) == end: return step
                        visited.add((r, c))
                        s.add((r, c))
                queue = s

        trees = [(height, r, c) for r, row in enumerate(forest) for c, height in enumerate(row) if forest[r][c] > 1]
        # check
        queue = [(0, 0)]
        reached = set()
        reached.add((0, 0))
        while queue:
            r, c = queue.pop()
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                row, col = r + dr, c + dc
                if forest[row][col] and (row, col) not in reached:
                    queue.append((row, col))
                    reached.add((row,col))
        if not all([(i, j) in reached for (height, i, j) in trees]): return -1
        trees.sort()
        return sum([bfs((I,J),(i,j)) for (_, i, j), (_, I, J) in zip([(0, 0, 0)] + trees, trees)])

class Solution:
    def cutOffTree(self, forest: List[List[int]]) -> int:
        forest.append([0] * len(forest[0]))
        for row in forest: row.append(0)
        # distance
        def distance(i, j, I, J):
            manhattan = abs(i - I) + abs(j - J)
            detour = 0
            good, bad = [(i, j)], []
            visited = set()
            while True:
                if not good:
                    good, bad = bad, []
                    detour += 1
                i, j = good.pop()
                if i == I and j == J: return manhattan + detour * 2
                if (i, j) in visited: continue
                visited.add((i, j))
                for i, j, closer in ((i-1, j, i > I), (i+1, j, i < I), (i, j+1, j < J), (i, j-1, j > J)):
                    if forest[i][j]:
                        (good if closer else bad).append((i, j))

        trees = [(height, r, c) for r, row in enumerate(forest) for c, height in enumerate(row) if forest[r][c] > 1]
        # check
        queue = [(0, 0)]
        reached = set()
        reached.add((0, 0))
        while queue:
            r, c = queue.pop()
            for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                row, col = r + dr, c + dc
                if forest[row][col] and (row, col) not in reached:
                    queue.append((row, col))
                    reached.add((row,col))
        if not all([(i, j) in reached for (height, i, j) in trees]): return -1
        trees.sort()
        return sum([distance(i, j, I, J) for (_, i, j), (_, I, J) in zip([(0, 0, 0)] + trees, trees)])

class Solution:
    def cutOffTree(self, forest: List[List[int]]) -> int:
        Valid_target=sorted([(val,r,c)for r,row in enumerate(forest) for c,val in enumerate(row) if val>1],key=lambda x:x[0])
        sc=sr=ans=0

        for x in Valid_target:
            _,tr,tc=x
            d=self.dist_bfs(forest,sr,sc,tr,tc)
            if d<0:return -1
            ans+=d
            sr,sc=tr,tc
        return ans

    def dist_bfs(self,forest,sr,sc,tr,tc):
        R,C=len(forest),len(forest[0])
        Queue=collections.deque([(sr,sc,0)])
        seen={(sr,sc)}

        while Queue:
            r,c,d=Queue.popleft()

            if tr==r and tc==c: return d

            for nr,nc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
                if 0<=nr<R and 0<=nc<C and (nr,nc) not in seen and forest[nr][nc]:
                    seen.add((nr,nc))
                    Queue.append((nr,nc,d+1))
        return -1

class Solution:
    def cutOffTree(self, forest: List[List[int]]) -> int:
        Valid_target=sorted([(val,r,c)for r,row in enumerate(forest) for c,val in enumerate(row) if val>1],key=lambda x:x[0])
        sc=sr=ans=0

        for x in Valid_target:
            _,tr,tc=x
            d=self.dist_Astar(forest,sr,sc,tr,tc)
            if d<0:return -1
            ans+=d
            sr,sc=tr,tc
        return ans

    def dist_Astar(self,forest,sr,sc,tr,tc):
        R,C=len(forest),len(forest[0])
        heap=[(0,0,sr,sc)]
        cost={(sr,sc):0}

        while heap:
            f,g,r,c=heapq.heappop(heap)

            if tr==r and tc==c: return g

            for nr,nc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
                if 0<=nr<R and 0<=nc<C and forest[nr][nc]:
                    New_cost=g+1+abs(nr-tr)+abs(nc-tr)
                    if New_cost<cost.get((nr,nc),99999):
                        cost[(nr,nc)]=New_cost
                        heapq.heappush(heap,(New_cost,g+1,nr,nc))
        return -1

class Solution:
    def cutOffTree(self, forest: List[List[int]]) -> int:
        m, n = len(forest), len(forest[0])

        def fn(start, end): 
            """Return min steps to move from start to end."""
            ans = 0 
            seen = {start}
            queue = deque([start])
            while queue: 
                for _ in range(len(queue)): 
                    i, j = queue.popleft()
                    if (i, j) == end: return ans
                    for ii, jj in (i-1, j), (i, j-1), (i, j+1), (i+1, j): 
                        if 0 <= ii < m and 0 <= jj < n and forest[ii][jj] != 0 and (ii, jj) not in seen: 
                            seen.add((ii, jj))
                            queue.append((ii, jj))
                ans += 1
            return -1 

        ans = 0 
        start = (0, 0)
        for _, i, j in sorted((forest[i][j], i, j) for i in range(m) for j in range(n) if forest[i][j] > 1): 
            val = fn(start, (i, j))
            if val == -1: return -1 
            ans += val 
            start = (i, j)
        return ans

class Solution:
    def cutOffTree(self, forest: List[List[int]]) -> int:
        a = []
        n = len(forest)
        m = len(forest[0])
        for i in range(n):
            for j in range(m):
                if forest[i][j] > 1:
                    a.append(forest[i][j])
        a.sort()

        s = 0
        ux = 0
        uy = 0
        for h in a:
            if forest[ux][uy] == h:
                continue        
            dist = [[None] * m for i in range(n)]
            q = deque()
            q.append((ux, uy))
            dist[ux][uy] = 0
            found = False
            while q and not found:
                ux, uy = q.popleft()
                d = [(-1, 0), (0, 1), (1, 0), (0, -1)]
                for dx, dy in d:
                    vx = ux + dx
                    vy = uy + dy
                    if vx < 0 or vx >= n or vy < 0 or vy >= m:
                        continue
                    if forest[vx][vy] == 0:
                        continue
                    if dist[vx][vy] is None:
                        dist[vx][vy] = dist[ux][uy] + 1
						# It's important to stop here! Otherwise there will be TLE
                        if forest[vx][vy] == h:
                            s += dist[vx][vy]
                            ux = vx
                            uy = vy
                            found = True
                            break
                        q.append((vx, vy))
            if not found:
                return -1
        return s

class Solution:
    def checkValidString(self, s: str) -> bool:

        # store the indices of '('
        stk = []

        # store the indices of '*'
        star = []


        for idx, char in enumerate(s):

            if char == '(':
                stk.append( idx )

            elif char == ')':

                if stk:
                    stk.pop()
                elif star:
                    star.pop()
                else:
                    return False

            else:
                star.append( idx )


        # cancel ( and * with valid positions, i.e., '(' must be on the left hand side of '*'
        while stk and star:
            if stk[-1] > star[-1]:
                return False

            stk.pop()
            star.pop()


        # Accept when stack is empty, which means all braces are paired
        # Reject, otherwise.
        return len(stk) == 0

class Solution:
    def checkValidString(self, s: str) -> bool:
        leftmin = leftmax = 0
        for c in s:
            if c == "(":
                leftmax += 1
                leftmin += 1
            if c == ")":
                leftmax -= 1
                leftmin = max(0, leftmin-1)
            if c == "*":
                leftmax +=1
                leftmin = max(0, leftmin-1)
            if leftmax < 0:
                return False
        if leftmin == 0:
            return True

class Solution:
    def checkValidString(self, s: str) -> bool:
        left_par_stack = []     # store the index of "("
        star_stack = []         # store the index of "*"

        for i in range(len(s)):
            if s[i] == "(":                 # When encounter "(" or "*", we store it separately as "money" for future use.
                left_par_stack.append(i)
            elif s[i] == "*":
                star_stack.append(i)
            elif s[i] == ")":               # When encounter ")", it's time we need to pay,
                if left_par_stack:          # we give priority to pay with "(", so the right-most "(" will be consumed.
                    left_par_stack.pop()
                elif star_stack:            # Otherwise, we pay with "*".
                    star_stack.pop()
                else:
                    return False            # We don't have enough money to pay, game over.

        while left_par_stack:               # In situ that some "(" haven't been consumed.
            if not star_stack:
                break
            elif star_stack[-1] > left_par_stack[-1]: # Only when the idx of "*" is greater than idx of "(" that can we apply "*" as ")"
                star_stack.pop()
