    def checkValidString(self, s: str) -> bool:
        weight = {'(': 1, ')': -1}

        @lru_cache(None)
        def is_valid(i, w):
            # weight should be zero, means all chars have pairs
            if i >= len(s):
                return w == 0

            # any left parenthesis '(' must have a corresponding right parenthesis ')' or
            # any right parenthesis ')' must have a corresponding left parenthesis '('
            if (s[i] == '(' and w < 0) or (s[i] == ')' and w <= 0):
                return False

            # '*' could be treated as a single right parenthesis ')' or 
            # a single left parenthesis '(' or an empty string ""
            if s[i] == '*':
                return is_valid(i + 1, w + 1) or is_valid(i + 1, w - 1) or is_valid(i + 1, w)

            return is_valid(i + 1, weight[s[i]] + w)

        return is_valid(0, 0)

