        def recur(indx, num_open):
            # print(indx, num_open)
            if indx == n:
                if num_open == 0:
                    return True
                else:
                    return False

            curr_chr = s[indx]

            if curr_chr == ')':
                if num_open > 0:
                    return recur(indx+1, num_open-1)
                else:
                    return False
            elif curr_chr == '(':
                return recur(indx+1, num_open+1)
            else:
                # treat as '('
                open_bracket_bool = recur(indx+1, num_open+1)
                if open_bracket_bool:
                    return True

                # treat as ')'
                if num_open > 0:
                    closed_bracket_bool = recur(indx+1, num_open-1)
                    if closed_bracket_bool:
                        return True

                # treat as ''
                empty_str_bool = recur(indx+1, num_open)
                if empty_str_bool:
                    return True
            return False

        return recur(0, 0)

