            # kmp failure function
            m = len(pattern)
            f = [0] * m
            i = 1
            j = 0
            while i < m:
                if pattern[j] == pattern[i]:
                    f[i] = j+1
                    i += 1
                    j += 1
                elif j > 0:
                    j = f[j-1]
                else:
