    def longestUnivaluePath(self, root: TreeNode) -> int:

        def dfs(node): 
            """Return longest univalue branch and longest univalue path (post-order traversal)."""
            if not node: return 0, 0
            (lx, llup), (rx, rlup) = dfs(node.left), dfs(node.right) 
