                if c not in tf:
                    tf[c]=0
                tf[c]+=1
            w2f={}
            for word in stickers:
                w2f[word]={}
                for c in word:
                    if c in tf:
                        if c not in w2f[word]:
                            w2f[word][c]=0
                        w2f[word][c]+=1
            res=float('inf')
