            def dominate(a,b):
                for c in w2f[b]:
                    if c in w2f[a] and w2f[a][c]>=w2f[b][c]:
                        continue
                    else:
                        return False
                return True
            for w in stickers:
                if w not in w2f:continue
                for w2 in stickers:
                    if w2!=w and w2 in w2f and dominate(w2,w):
                        del w2f[w]
                        break

            def helper(ct, charhas, i):
                nonlocal res
                if ct>=res: return
                if i==len(target):
                    res=min(res,ct)
                    return 
                ch=target[i]
                if charhas[ch]>0:
                    charhas[ch]-=1
                    helper(ct,charhas,i+1)
