    def canPartitionKSubsets(self, nums: List[int], k: int) -> bool:
        n, expected_sum = len(nums), sum(nums) / k
        nums.sort(reverse=True)
        if expected_sum != int(expected_sum) or nums[0] > expected_sum:
            return False

        def btrack(pos, target, done):
            if done == k-1: return True
            if pos == n: return False
            num = nums[pos]
            if num > target:
                return btrack(pos + 1, target, done)
            nums[pos] = expected_sum + 1
            if num == target:
                return btrack(0, expected_sum, done + 1)
            if btrack(pos + 1, target - num, done): return True
            nums[pos] = num
            return btrack(pos + 1, target, done)

        return btrack(0, expected_sum, 0)

