        total = sum(nums)
        if total%k != 0:
            return False
        target = total//k
        n = len(nums)
        buckets = [0 for _ in range(k)]
        nums.sort(reverse=True)
        def backtrack(buckets, index, t):
            if index == n:
                for i in buckets:
                    if i != t:
                        return False
                return True
            for idx in range(len(buckets)):
                if buckets[idx]+nums[index] > target:
                    continue
                buckets[idx] += nums[index]
                if backtrack(buckets, index+1, t):
