                    continue
                if used[j] or tot + nums[j] > target:
                    continue
                used[j] = True
                if backtrack(j + 1, k, tot + nums[j]):
                    return True
                used[j] = False
				# Pruning2: 
				# since we sort nums in reverse order, tot == 0 means skipping the first element, if it cannot work, the rest of the elements cannot work either, we can just break the loop and return False.
				# tot + nums[j] == target:
                if tot == 0 or tot + nums[j] == target:
                    break
					# return False
            return False
        return backtrack(0, k, 0)

class Solution:
    def canPartitionKSubsets(self, nums: List[int], k: int) -> bool:
        total = sum(nums)
        n = len(nums)
        if total%k != 0:
            return False
        nums.sort(reverse=True)
        target = total // k
        used = [False] * n
        memo = {} # Record the current state of used array when a bucket is full

        def backtracking(start_index, k_left, cur_sum):
            """
            start_index: the start index of balls
            k_left: remaining buskets to fill
            cur_sum: the sum of balls in current bucket
            """
            if k_left==0:
                return True

            if tuple(used) in memo:
                return memo[tuple(used)]

            if cur_sum==target:
                tmp = backtracking(0, k_left-1, 0)
                memo[tuple(used)] = tmp
                return tmp

            for i in range(start_index, n):
                if nums[i]>target or cur_sum+nums[i]>target or used[i]:
                    continue

                used[i] = True
                cur_sum += nums[i]
                if backtracking(i+1, k_left, cur_sum):
                    return True
                used[i] = False
                cur_sum -= nums[i]
            return False

