            for holding in range(2):
                do_nothing = dp[i+1][holding]
                if holding:
                    # sell stock
                    do_something = prices[i]-fee+dp[i+1][0]
                else:
                    do_something = -prices[i] + dp[i+1][1]
                dp[i][holding] = max(do_nothing, do_something)
        return dp[0][0]

