class Solution:
    def pivotIndex(self, nums: List[int]) -> int:
        return self.findPivotIndexOptimal(nums)

#     O(n) || O(1)
# runtime: 153ms 90.08%
    def findPivotIndexOptimal(self, nums):
        if not nums:
            return nums

        leftSum = 0
        totalSum = sum(nums)

        for i in range(len(nums)):
            diff = totalSum - nums[i] - leftSum

            if diff == leftSum:
                return i

            leftSum += nums[i]

        return -1

    # O(n^3) or O(n^4) || O(1) : TLE 
    def findPivotBruteForce(self, array):
        if not array: return array

        for i in range(len(array)): # O(n)
            for j in range(i + 1, len(array)): #O(n)
                if sum(array[:i]) == sum(array[i + 1:]): #sum is O(n) operation O(n^2)
                    return i
        return -1

class Solution:
    def splitListToParts(self, head: ListNode, k: int) -> List[ListNode]:
        size = self.get_size(head)
        min_len, one_more = divmod(size, k)
        res = []
        current = ListNode()
        current.next = head
        for i in range(k):
            ans = current
            for _ in range(min_len + int(i < one_more)):
                current = current.next
            res.append(ans.next)
            ans.next = None
        return res

    def get_size(self, head: ListNode) -> int:
        size = 0
        while head is not None:
            size += 1
            head = head.next
        return size

class Solution:
    def splitListToParts(self, head: Optional[ListNode], k: int) -> List[Optional[ListNode]]:

        def gen():
            nonlocal k
            length, cur = 0, head
            while cur:
                length += 1
                cur = cur.next
            prev, cur, q, r = None, head, *divmod(length, k)
            for _ in range(k):
                # yield head of current partition
                yield cur
                # move to the next part
                for _ in range(q + (r > 0)):
                    prev = cur
                    if cur:
                        cur = cur.next
                # split from previous part
                if prev:
                    prev.next = None
                r -= 1

        return list(gen())

class Solution:
    def splitListToParts(self, head: Optional[ListNode], k: int) -> List[Optional[ListNode]]:
        arr = []
        cur, n = head, 0
        prev = None

        while cur:
            n += 1
            cur = cur.next
        cur = head        
        part = n // k
        extra = n % k

        for _ in range(k):
            arr.append(cur)
            for _ in range(part):
                prev = cur
                cur = cur.next
            if extra and cur:
                extra -= 1
                prev = cur
                cur = cur.next
            if prev:
                prev.next = None
        return arr

