class Solution:
    def countPalindromicSubsequences(self, s:str) -> int:

        @cache
        def fn(ch, i, j):
            if i > j:
                return 0

            if i == j and s[i] == ch:
                return 1

            if s[i] == s[j] == ch:
                return 2 + fn('a', i+1, j-1) + fn('b', i+1, j-1) + fn('c', i+1, j-1) + fn('d', i+1, j-1)
            elif s[i] != ch:
                return fn(ch, i+1, j)
            elif s[j] != ch:
                return fn(ch, i, j-1)


        n = len(s)
        return (fn('a', 0, n-1) + fn('b', 0, n-1) + fn('c', 0, n-1) + fn('d', 0, n-1)) % (10**9+7)

class Solution:
    def countPalindromicSubsequences(self, S: str) -> int:
        n = len(S)
        pos = dict()
        nexts = [n]*n
        prev = [-1]*n
        for i, c in enumerate(S):
            if c in pos: prev[i] = pos[c]
            pos[c] = i
        pos = dict()
        for j in range(n-1, -1, -1):
            if S[j] in pos: nexts[j] = pos[S[j]]
            pos[S[j]] = j
        dp = [[0]*n for _ in range(n)]
        for i in range(n):
            dp[i][i] = 1
        for D in range(1, n):
            for i in range(n-D):
                j = i + D
                if S[i] != S[j]:
                    dp[i][j] = dp[i+1][j] + dp[i][j-1] - dp[i+1][j-1]
                else:
                    if nexts[i] > prev[j]: # a...a
                        dp[i][j] = dp[i+1][j-1] * 2 + 2
                    elif nexts[i] == prev[j]: # a..a...a
                        dp[i][j] = dp[i+1][j-1] * 2 + 1
                    else: # a...a....a....a
                        dp[i][j] = dp[i+1][j-1] * 2 - dp[nexts[i]+1][prev[j]-1]
        return dp[0][n-1] % (10**9+7)

class Solution:
    def countPalindromicSubsequences(self, s: str) -> int:
        n, MOD = len(s), 10 ** 9 + 7
        s = [ord(c) - ord('a') for c in s]
        charcnt, first, last = [[0] * n for _ in range(n)], [-1] * 4, [-1] * 4
        for i in range(n):
            if first[s[i]] == -1: first[s[i]] = i
            last[s[i]] = i
            cs = set()
            for j in range(i, n):
                cs.add(s[j])
                charcnt[i][j] = len(cs)
        left, right = [[-1] * 4 for _ in range(n)], [[-1] * 4 for _ in range(n)]
        for i in range(1, n):
            left[i] = left[i - 1][:]
            left[i][s[i - 1]] = i - 1
        for i in range(n - 2, -1, -1):
            right[i] = right[i + 1][:]
            right[i][s[i + 1]] = i + 1
        ans, dp = charcnt[0][n - 1], [[0] * n for _ in range(n)]
        for l, r in zip(first, last): dp[l][r] = 1
        for step in range(1, n):
            for l in range(step):
                r = l + n - step
                if not dp[l][r]: continue
                for nk in range(4):
                    nl, nr = right[l][nk], left[r][nk]
                    if nr < r and nl > l and nl < nr:
                        dp[nl][nr] = (dp[nl][nr] + dp[l][r]) % MOD
                ans = (ans + dp[l][r] * (1 + charcnt[l + 1][r - 1])) % MOD
        return ans

class Solution:
    def countPalindromicSubsequences(self, s: str) -> int:
        locs = defaultdict(list)
        for i, ch in enumerate(s): locs[ch].append(i)

        @cache
        def fn(lo, hi):
            """Return count of palindromic subsequences in s[lo:hi]."""
            if lo == hi: return 0
            ans = 0 
            for ch in "abcd": 
                i = bisect_left(locs[ch], lo)
                j = bisect_left(locs[ch], hi) - 1
                if i <= j < len(locs[ch]) and lo <= locs[ch][i] <= locs[ch][j] < hi: 
                    ans += 1
                    if i < j: ans += 1 + fn(locs[ch][i]+1, locs[ch][j])
            return ans % 1_000_000_007

        return fn(0, len(s))

class Solution:
    def countPalindromicSubsequences(self, s: str) -> int:
        n = len(s)
        t = [[0 for _ in range(n)] for _ in range(n)]

        for g in range(n):
            i = 0
            for j in range(g, n):
                if g == 0:
                    t[i][j] = 1
                elif g == 1:
                    t[i][j] = 2
                else:
                    if s[i] != s[j]:
                        t[i][j] = t[i][j-1] + t[i+1][j] - t[i+1][j-1]
                    else:
                        if s[i:j+1].count(s[i]) == 2:
                            t[i][j] = 2*t[i+1][j-1] + 2
                        elif s[i:j+1].count(s[i]) == 3:
                            t[i][j] = 2*t[i+1][j-1] + 1
                        else:
                            temp = s[i+1:j]
                            x = i + temp.index(s[i]) + 2
                            y = j - temp[::-1].index(s[i]) - 2
                            t[i][j] = 2*t[i+1][j-1] - t[x][y]
                i = i+1

        return t[0][n-1]% (10**9 + 7)

