                point.append(i)
        if len(point)==0 or point[-1] != N:
            point.append(N)

        earning,prev = 0,0
        for indx in point:
            dp = [-10**20,-10**20]
            for i,n in enumerate(newList[prev:indx]):
                if i == 0:
                    dp[0] = max(dp[0], dic[n])
                    continue
                if i == 1:
                    dp[1] = max(dp[1], dic[n])
                    continue
                temp = dp[1]
                dp[1] = max(dic[n], dp[0]+dic[n],dp[1])
                dp[0] = max(temp,dp[0])
            earning += max(dp)
            prev = indx

