class Solution:
    def openLock(self, deadends: List[str], target: str) -> int:
        if '0000' in deadends:
            return -1
        if '0000' == target:
            return 0

        queue = collections.deque()
        queue.append(('0000', 0))
        visited = set('0000')

        while queue:
            node, dist = queue.popleft()

            if node in deadends:
                continue
            if node == target:
                return dist

            for i in range(len(node)):
                num = int(node[i])
				# For wrap round we consider both forward and reverse directions.
                for dx in [-1, 1]:
                    nodeUpdated = node[:i] + str((num + dx) % 10) + node[i+1:]
                    if nodeUpdated not in visited:
                        queue.append((nodeUpdated, dist + 1))
                        visited.add(nodeUpdated)
        return -1

class Solution:
    def openLock(self, deadends: List[str], target: str) -> int:

        deadends = set(deadends)

        def update_lock(state, slot, direction):

            curr = int(state[slot])

            if curr + direction < 0:

                new = '9'

            else:

                new = str((curr + direction) % 9)

            new_state = state[:slot] + new + state[slot+1:]

            return(new_state)

        def bfs(target):

            queue = [(0, '0000')]

            seen = set([0])

            min_steps = float('inf')

            while queue:

                steps, curr_state = queue.pop(0)

                if curr_state == target:

                    min_steps = min(min_steps, steps)

                    continue

                else:

                    for i in range(4):

                        for dx in {-1, 1}:

                            new_state = update_lock(curr_state, i, dx)

                            if new_state not in seen and new_state not in deadends:

                                seen.add(new_state)

                                queue.append((steps + 1, new_state))

                            else:

                                continue

            return(min_steps if min_steps < float('inf') else -1)

        if '0000' in deadends:

                return(-1)

        else:

            return(bfs(target))

class Solution:
    def openLock(self, deadends: List[str], target: str) -> int:
        q = []
        visited = set()
        step = 0
        deads = set()
        q.append("0000")
        visited.add("0000")
        for deadend in deadends:
            deads.add(deadend)

        while (len(q) > 0):
            size = len(q)
            for i in range(size):
                curr = q.pop(0)

                # skip if encountering a deadend
                if (curr in deads):
                    continue
                if (curr == target):
                    return step

                for j in range(4):
                    up = self.plusOne(curr, j)
                    if (up not in visited):
                        visited.add(up)
                        q.append(up)

                    down = self.minusOne(curr, j)
                    if (down not in visited):
                        visited.add(down)
                        q.append(down)
            step += 1
        return -1

    def plusOne(self, s, j):
        listStr = list(s)
        if (listStr[j] == '9'):
            listStr[j] = '0'
        else:
            listStr[j] = str(int(listStr[j]) + 1)
        return ''.join(listStr)

    def minusOne(self, s, j):
        listStr = list(s)
        if (listStr[j] == '0'):
            listStr[j] = '9'
        else:
            listStr[j] = str(int(listStr[j]) - 1)
        return ''.join(listStr)

class Solution:
    def crackSafe(self, n: int, k: int) -> str:
        def dfs(path, visitedCombinations, targetNumVisited, combos):
            # Base Case. We've visited all possible combinations
            if len(visitedCombinations) == targetNumVisited:
                combos.append(''.join([str(x) for x in path]))
                return True
            # This if/else is necessary to prevent Python from picking up the first element if n = 1
            if n > 1:
                lastDigits = ''.join([str(x) for x in path[-(n-1):]])
            else:
                lastDigits = ''
            for i in range(k):
                path.append(i)
                newPwd = f'{lastDigits}{i}'
                # We have not reached the minimum pwd length. Continue recursion
                if len(newPwd) != n: 
                    if dfs(path, visitedCombinations, targetNumVisited, combos):
                        return True
                if len(newPwd) == n and newPwd not in visitedCombinations:
                    visitedCombinations[newPwd] = 1
                    if dfs(path, visitedCombinations, targetNumVisited, combos):
                        return True
                    del visitedCombinations[newPwd]
                path.pop()
            return False


        # Empty visited Combinations hash set
        visitedCombinations = {}
        combos = []
        dfs([], visitedCombinations, k**n, combos)
        return combos[0]

class Solution:
    def crackSafe(self, n: int, k: int) -> str:

        total = k**n-1
        start = '0' * n
        visited = set()
        visited.add('0' * n)
        self.ans = '0' * n

        def dfs(total,start):
            if total == 0: 
                return True
            for i in range(k):
                last = start[1:n]
                #print(last+str(i))
                end = last+str(i)
                if end not in visited:
                    visited.add(end)
                    total = total-1
                    self.ans = self.ans+str(i)
                    if dfs(total, end):
                        return True
                    else:
                        visited.remove(end)
                        total = total+1
                        self.ans = self.ans[:-1]
                        #print("l")
            return False

        dfs(total,start)
        return self.ans

