class Solution:
    def reorganizeString(self, S: str) -> str:
        if not S: return ''
        heap, last, ans = [], None, ''
        counts = collections.Counter(S)
        for ch in counts:
            heapq.heappush(heap, (-counts[ch], ch))

        while heap:
            count, ch = heapq.heappop(heap)
            ans += ch
            if last:
                heapq.heappush(heap, last)
            last = (count+1, ch) if count != -1 else None
        return ans if not last else ''

class Solution:
    def reorganizeString(self, s: str) -> str:
        counter = {}
        for ch in s:
            if ch in counter:
                counter[ch] +=1
            else:
                counter[ch] = 1
        queue = []

        for elem in counter:
            heapq.heappush(queue, (-1*counter[elem], elem))

        result = []
        prev_char = None
        prev_freq = None
        while(queue):
            freq, elem  = heapq.heappop(queue)
            result.append(elem)
            if prev_freq:
                # it makes sure that character whihc is popped just now is not popped next, i.e. maintains non- adjacent condition
                heapq.heappush(queue, (prev_freq, prev_char))

            prev_char, prev_freq = elem, freq + 1 # +1 is equivalent to -1 as we used max_heap
        if len(result) == len(s):
            return "".join(result)
        return ""

class Solution:
    def reorganizeString(self, s: str) -> str:
        count = Counter(s) # O(N)
        most_common_c = max(count.items(), key=itemgetter(1))[0] # O(N)
        if count[most_common_c] > (len(s)+1)//2:
            return ""

        output = ['']*len(s)        
        i = 0
        for _ in range(count[most_common_c]):
            output[i] = most_common_c
            i += 2

