class Solution:
    def reorganizeString(self, s: str) -> str:
		# count the character in the string
        charMap = {}
        for i in range(len(s)):
            if s[i] in charMap:
                charMap[s[i]] += 1
            else:
                charMap[s[i]] = 1

		# sort the map by value - the character appears the most is at index 0
        charMap = {k: v for k, v in sorted(charMap.items(), key=lambda x: x[1], reverse=True)}

		firstMap = list(charMap.items())[0] # character appears the most

        if len(s) <= (firstMap[1]-1)*2:
            return ""
        else:
			# create a string contains of different "phrase"
			# each character will be distinct in each phrase
            newstr = [firstMap[0] for _ in range(firstMap[1])]  
			index = 0
            charMap.pop(firstMap[0]) # the initialize value already contains the most appeared character
            for k, v in charMap.items():
                for _ in range(v):
                    if index == len(newstr):
                        index = 0 # reset index counter
                    newstr[index] += str(k)
                    index += 1 
        return "".join(newstr)

class Solution:
    def reorganizeString(self, s: str) -> str:
        wc  = {}
        lenn = 0
        for letter in s:
            wc[letter] = wc.get(letter,0)+1
            lenn += 1
        if 2 * max(wc.values()) > sum(wc.values()) + 1:
            return ""
        else:
            # sorting the word counter based on frequency in decending order
            wc = dict(sorted(wc.items(),key=lambda x:x[1],reverse=True))
            bs = ["" for i in range(lenn)]
            # filling the odd places
            for i in range(0,lenn,2):
                for key in wc.keys():
                    if wc[key]:
                        bs[i] = key
                        wc[key] -= 1
                        break
            # filling the even places
            for i in range(1,lenn,2):
                for key in wc.keys():
                    if wc[key]:
                        bs[i] = key
                        wc[key] -= 1
                        break
            return "".join(bs)

