    def swimInWater(self, grid: List[List[int]]) -> int:
        visited = set()
        minheap = [[grid[0][0], [0, 0]]]

        ans = -float('inf')
        while len(minheap) > 0:
            h, [x, y] = heappop(minheap)
            ans = max(h, ans)
            if x == len(grid) - 1 and y == len(grid) - 1:
                break
            if (x, y) not in visited:
