class Solution:
    def swimInWater(self, grid: List[List[int]]) -> int:
        n = len(grid)
        t = max(grid[0][0], grid[n-1][n-1])

        def bfs():
            queue = deque([(0, 0)])
            visited = {(0, 0)}

            while queue:
                r, c = queue.popleft()
                if r == c == n-1: return True

                for r1, c1 in [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]:
                    if 0 <= r1 < n and 0 <= c1 < n and (r1, c1) not in visited and grid[r1][c1] <= t:
                        queue.append((r1, c1))
                        visited.add((r1, c1))

            return False

        while True:
            if bfs():
                return t
            t += 1

