class Solution:
    def kthGrammar(self, n: int, k: int) -> int:
        parent = 2
        return self.find_parent(n-1, k-1, 2)

    def find_parent(self, n, prev_index, parent) -> int:
        if n == 0:
            if prev_index%2 == 0:
                parent = 0
            else:
                parent = 1
            return parent

        next_index = prev_index // 2
        parent = self.find_parent(n-1, next_index, parent)

        if parent == 0:
            if prev_index%2 == 0:
                parent = 0
            else:
                parent = 1
            return parent
        elif parent == 1:
            if prev_index%2 == 0:
                parent = 1
            else:
                parent = 0
            return parent

        return parent

