    def kthGrammar(self, n: int, k: int) -> int:
        map = {('l','0') : '0', ('r','0') : '1', ('l','1') : '1', ('r','1') : '0'}
        self.q = []
        def recursive(n,k):
            if n == 1:
                return

            if int((k - 1) % 2) == 0:
                self.q.append('r')
                recursive(n-1,(k-1)/2)
            elif int(k % 2) == 0:
                self.q.append('l')
