class Solution:
    def minDiffInBST(self, root: Optional[TreeNode]) -> int:
        self.res = math.inf

        def helper(root):
            if root.left:
                # min value from left, max value from left
                low, left = helper(root.left)
                self.res = min(self.res, root.val - left)
            else:
                low = root.val

            if root.right:
                # min value from right, max value from right
                right, high = helper(root.right)
                self.res = min(self.res, right - root.val)
            else:
                high = root.val

            return low, high

        helper(root)
        return self.res

