class Solution:
    def minDiffInBST(self, root: TreeNode) -> int:
        left_diff = float('inf')
        right_diff = float('inf')

        if root.left:
            left_tree = root.left
            while left_tree.right:
                left_tree = left_tree.right

            left_diff = root.val - left_tree.val
            left_diff = min(left_diff, self.minDiffInBST(root.left))

        if root.right:
            right_tree = root.right
            while right_tree.left:
                right_tree = right_tree.left

            right_diff = right_tree.val - root.val
            right_diff = min(right_diff, self.minDiffInBST(root.right))

        return min(left_diff, right_diff)

