            return [""]

		# start recursion at root of tree
        self.funct("", S)
        return self.res


    def funct(self, base, remaining):
        # base case: we arrived to a leaf of the tree
        if len(remaining) == 1:
            if remaining.isdigit():
                self.res.append(base + remaining)
            else:
                self.res.append(base + remaining)
                self.res.append(base + remaining.swapcase())

        # average case:       
        else:   
            if remaining[0].isdigit():
                self.funct(base + remaining[0], remaining[1:])
            else:
                self.funct(base + remaining[0], remaining[1:])
                self.funct(base + remaining[0].swapcase(), remaining[1:])

