    def numSubarrayBoundedMax(self, nums: List[int], left: int, right: int) -> int:
        queue = deque()
        ans, ii = 0, -1
        for i in range(len(nums)+1): 
            if i == len(nums) or nums[i] > right: 
                while queue: 
                    k = queue.popleft()
                    ans += (k - ii) * (i - k)
                    ii = k
                ii = i 
