class Solution(object):
    def __init__(self):
        self.memo = {}
    def allPathsSourceTarget(self, graph):
        """
        :type graph: List[List[int]]
        :rtype: List[List[int]]
        """
        self.memo = {len(graph)-1:[[len(graph)-1]]}
        def calc(N):
            if N in self.memo:
                return self.memo[N]
            a = []
            for n in graph[N]:
                for path in calc(n):
                    a.append([N]+path)
            self.memo[N] = a
            return a
        return calc(0)

class Solution:
	def allPathsSourceTarget(self, graph: List[List[int]]) -> List[List[int]]:
		n = len(graph)
		stack = [[0]]
		paths = []
		while stack: 
			path = stack.pop()
			vertex = path[-1]
			if vertex == n-1:
				paths.append(path.copy())
			for nodes in graph[vertex]:
				stack.append( path.copy()+[nodes])
		return paths

class Solution:
    def allPathsSourceTarget(self, graph: List[List[int]]) -> List[List[int]]:

        def dfs(path: List[int]):
            if path[-1] == len(graph) - 1:
                yield path
            else:
                for v in graph[path[-1]]:
                    yield from dfs(path + [v])

        return list(dfs([0]))

