class Solution:
    def allPathsSourceTarget(self, graph: List[List[int]]) -> List[List[int]]:
        paths = []
        visited = [False]*len(graph)
        def DFS(graph, src, dest, path):
            visited[src] = True
            path.append(src)

            if src == dest:
                paths.append(path[:])
            else:
                for node in graph[src]:
                    if not visited[node]:
                        DFS(graph, node, dest, path)

            path.pop()
            visited[src] = False

        DFS(graph, 0, len(graph)-1, [])
        return paths

class Solution:
    def __init__(self):
        self.seen = None
        self.memo = None
        self.end = None


    def dfs(self, graph, node):
        self.seen[node] = True

        if node == self.end:
            self.memo[node].append([node])
        else:
            for nbor in graph[node]:
                if not self.seen[nbor]:
                    self.dfs(graph, nbor)

                if self.memo[nbor]:
                    for tail in self.memo[nbor]:
                        self.memo[node].append([node] + tail)


    def allPathsSourceTarget(self, graph: List[List[int]]) -> List[List[int]]:
        if not graph:
            return None

        self.seen = [False for _ in range(len(graph))]
        self.memo = [[] for _ in range(len(graph))]
        self.end = len(graph) - 1

        self.dfs(graph, 0)

        return self.memo[0]

