class Solution:
    def champagneTower(self, poured: int, r: int, c: int) -> float:
        dp = [[0] * i for i in range(1, 102)]
        dp[0][0] = poured

        for i in range(100):
            go_to_next_level = False #set a flag to judge if you go to next level or not
            for j in range(i + 1):
                if dp[i][j] > 1:
                    go_to_next_level = True
                    drip = dp[i][j] - 1
                    dp[i + 1][j] += drip / 2
                    dp[i + 1][j + 1] += drip / 2
            if not go_to_next_level: break

        return min(1, dp[r][c])

class Solution:
    def champagneTower(self, poured: int, query_row: int, query_glass: int) -> float:

        @lru_cache(None)
        def fn(i, j):
            """Return wine poured into glass (i, j)."""
            if i == j == 0: return poured # boundary condition
            if j < 0 or j > i: return 0 # boundary condition 
            return max(0, fn(i-1, j-1)-1)/2 + max(0, fn(i-1, j)-1)/2

        return min(1, fn(query_row, query_glass))

