class Solution:
    def eventualSafeNodes(self, graph: List[List[int]]) -> List[int]:
        g = collections.defaultdict(list)
        indegree = collections.defaultdict(int)

        for v, neigbs in enumerate(graph):
            for neigb in neigbs:
                g[neigb].append(v)
                indegree[v] += 1

        q = collections.deque()

        for v in range(len(graph)):
            if v not in indegree:
                q.append(v)

        res = [False] * len(graph)
        while q:
            node = q.popleft()

            res[node] = True

            for neigb in g[node]:
                indegree[neigb] -= 1

                if indegree[neigb] == 0:
                    q.append(neigb)

        return [idx for idx in range(len(res)) if res[idx]]

class Solution:
    def eventualSafeNodes(self, graph: List[List[int]]) -> List[int]:
        def check_cycle(node,graph,visited):
            if visited[node]==2:
                return True
            visited[node]=2
            for neighbour in graph[node]:
                if visited[neighbour]!=1:
                    if check_cycle(neighbour,graph,visited):
                        return True
            visited[node]=1
            return False

        n=len(graph)
        visited=[0]*(n)
        for i in range(n):
            if visited[i]==0:
                if check_cycle(i,graph,visited):
                    continue
        answer=[]
        for i in range(n):
            if visited[i]==1:
                answer.append(i)
        return answer

class Solution:
    def isCycle(self, graph, node, visit):
        if visit[node] == 2:
            return True
        visit[node] = 2
        for nei in graph[node]:
            if visit[nei] != 1:
                if self.isCycle(graph, nei, visit):
                    return True
        visit[node] = 1
        return False

    def eventualSafeNodes(self, graph: List[List[int]]) -> List[int]:
        n = len(graph)
        visit = [0 for _ in range(n)]
        for i in range(n):
            if visit[i] == 0:
                if self.isCycle(graph, i, visit):
                    continue
        ans = []
        for i in range(n):
            if visit[i] == 1:
                ans.append(i)
        return ans

class Solution:
    def eventualSafeNodes(self, graph: List[List[int]]) -> List[int]:
        ans, out, inn = [], [], [[] for _ in graph] # reversed graph 
        for i, x in enumerate(graph): 
            if not x: ans.append(i) # safe states 
            out.append(len(x)) # out degree 
            for xx in x: inn[xx].append(i) # in-nodes of xx

        for n in ans: 
            for nn in inn[n]: 
                out[nn] -= 1
                if not out[nn]: ans.append(nn)
        return sorted(ans)

