class Solution:
    def largestSumOfAverages(self, nums: List[int], k: int) -> float:
        pre_sum = [0]
        for num in nums: pre_sum.append(pre_sum[-1] + num)
        avg = lambda i, j: (pre_sum[i+1]-pre_sum[j+1])/(i-j)

        n = len(nums)
        dp = [[0] * k for _ in range(n)]
        for i in range(n): dp[i][0] = pre_sum[i+1] / (i+1)

        for i in range(1, n):
            for kk in range(1, k):
                for j in range(kk-1, i):
                    dp[i][kk] = max(dp[i][kk], dp[j][kk-1] + avg(i, j))
        return dp[n-1][k-1]

class Solution:
    def largestSumOfAverages(self, A: List[int], K: int) -> float:
        prefix = [0]
        for x in A: prefix.append(prefix[-1] + x) # prefix sum 

        @lru_cache(None)
        def fn(i, k): 
            """Return largest sum of average of A[lo:hi+1] with at most k groups."""
            if i == 1 or k == 1: return prefix[i]/i # boundary condition 
            if i <= k: return prefix[i] # shortcut 
            ans = fn(i, k-1)
            for ii in range(1, i):
                ans = max(ans, fn(i-ii, k-1) + (prefix[i] - prefix[i-ii])/ii)
            return ans 

        return fn(len(A), K)

