    def pruneTree(self, root: TreeNode) -> TreeNode:

        def fn(node):
            """Prune binary tree via post-order traversal."""
            if not node: return False 
            if not (left := fn(node.left)): node.left = None
            if not (right := fn(node.right)): node.right = None
            return left or right or node.val == 1

