class Solution:
    def numFriendRequests(self, ages: List[int]) -> int:
        deque = collections.deque()
        ages.sort(reverse=True)
        res = 0
        curSame = 0

        for i, age in enumerate(ages):
            if i and age >= 15 and age == ages[i-1]:
                curSame += 1
            else:
                curSame = 0

            while deque and age <= deque[0]:
                deque.popleft()

            res += len(deque) + curSame
            deque.append(0.5*age + 7)

        return res

class Solution:
    def numFriendRequests(self, ages: List[int]) -> int:
        prefixSum = collections.Counter(ages)
        for i in range(2, 121):
            prefixSum[i] += prefixSum[i-1]

        res = 0
        for age in ages:
            left = int(0.5*age + 7)
            if age > left:
                res += prefixSum[age] - prefixSum[left] - 1

        return res

class Solution:
	def numFriendRequests(self, ages: List[int]) -> int:
		count = 0
		ages = Counter(ages)
		for x in ages:
			xCount = ages[x]
			for y in ages:
				if not (y <= 0.5*x+7 or y > x):
					yCount = ages[y]
					if x != y:
						count += xCount*yCount
					else:
						count += xCount*(xCount-1)
		return count

class Solution:
    def numFriendRequests(self, ages: List[int]) -> int:
        ages.sort()
        ans = lo = hi = 0 
        for x in ages: 
            while hi < len(ages) and x == ages[hi]: hi += 1
            while lo+1 < hi and ages[lo] <= x//2 + 7: lo += 1
            ans += hi - lo - 1
        return ans

class Solution:
    def numFriendRequests(self, ages: List[int]) -> int:
        freq = {}
        for x in ages: freq[x] = 1 + freq.get(x, 0)

        ans = 0 
        for x in freq: 
            for y in freq: 
                if 0.5*x + 7 < y <= x: 
                    ans += freq[x] * freq[y]
                    if x == y: ans -= freq[x]
        return ans

class Solution:
    def numFriendRequests(self, ages: List[int]) -> int:
        if len(ages) == 1:
            return 0

        self.counts = collections.defaultdict(int)

        def binary_search(ages, idx):
            start, end = 0, idx-1
            result = -1

            while start <= end:
                mid = start + (end - start) // 2
                if 0.5 * ages[idx] + 7 >= ages[mid]: 
                    start = mid+1
                else:
                    end = mid-1
                    result = mid

            if result != -1:
                return (idx - result) + self.counts[ages[idx]]

            return 0

        ages.sort()
        requests = 0
        for i in range(len(ages)):
            requests += binary_search(ages, i)
            self.counts[ages[i]] += 1

        return requests

class Solution:
    def maxProfitAssignment(self, difficulty: List[int], profit: List[int], worker: List[int]) -> int:
        mp = {}
        mx = 0
        for x, y in sorted(zip(difficulty, profit)):
            mp[x] = max(mp.get(x, 0), mx := max(mx, y))
        arr = list(mp.keys()) # ordered since 3.6

        ans = 0 
        for x in worker: 
            i = bisect_right(arr, x) - 1
            if 0 <= i < len(arr): ans += mp[arr[i]]
        return ans

