class Solution:
    def maxProfitAssignment(self, difficulty: List[int], profit: List[int], worker: List[int]) -> int:

        res = 0
        hashmap_profit = defaultdict(int)

        for i in range(len(difficulty)):
            hashmap_profit[difficulty[i]] = max(hashmap_profit[difficulty[i]], profit[i])

        difficulty.sort()
        prev = 0
        for i in range(len(difficulty)):
            hashmap_profit[difficulty[i]] = max(hashmap_profit[difficulty[i]], prev)
            prev = hashmap_profit[difficulty[i]]

        for i in range(len(worker)):
            if worker[i] < difficulty[0]:
                continue
            left, right = 0, len(difficulty) - 1
            while left < right:
                mid = left + (right - left + 1) // 2
                if worker[i] >= difficulty[mid]:
                    left = mid
                else:
                    right = mid - 1
            res += hashmap_profit[difficulty[left]] 

        return res

class Solution:
    def maxProfitAssignment(self, difficulty: List[int], profit: List[int], worker: List[int]) -> int:
        d = defaultdict(int)
        for k,v in zip(difficulty,profit):
            d[k] = max(d[k],v)
        bucket = [0 for _ in range(max(worker)+1)]
        val = 0
        for i in range(len(bucket)):
            if i in d:
                val = max(val,d[i])
            bucket[i] = val
        return sum([bucket[w] for w in worker])

