class Solution:
    def largestIsland(self, grid: List[List[int]]) -> int:
        n = len(grid)
        directions = [-1, 0, 1, 0, -1]

        islands = list()
        visited = [[False for _ in range(n)] for _ in range(n)]

        def helper(i, j):
            visited[i][j] = True
            island = [(i, j)]

            q = [(i, j)]
            while q:
                x, y = q.pop(0)

                for k in range(4):
                    next_x, next_y = x + directions[k], y + directions[k + 1]

                    if 0 <= next_x < n and 0 <= next_y < n and not visited[next_x][next_y] and grid[next_x][next_y] == 1:
                        visited[next_x][next_y] = True
                        q.append((next_x, next_y))
                        island.append((next_x, next_y))

            islands.append(island[:])
            return

        for i in range(n):
            for j in range(n):
                if not visited[i][j] and grid[i][j] == 1:
                    helper(i, j)

        N = len(islands)
        if N == 0:
            return 1
        sizes = [len(x) for x in islands]
        boundaies = [set() for _ in range(N)]
        boundaies = dict()

        for i in range(N):
            visited = set()
            for x, y in islands[i]:
                for k in range(4):
                    next_x, next_y = x + directions[k], y + directions[k + 1]

                    if 0 <= next_x < n and 0 <= next_y < n and grid[next_x][next_y] == 0 and (next_x, next_y) not in visited:
                        boundaies[(next_x, next_y)] = boundaies.get((next_x, next_y), 0) + sizes[i]
                        visited.add((next_x, next_y))

        if not boundaies:
            return n ** 2

        ans = min(max(sizes) + 1, n ** 2)
        return max(ans, max(boundaies.values()) + 1)

class Solution:
    DIRECTIONS = (-1, 0), (1, 0), (0, -1), (0, 1)

    def neighbours(self, i, j):
        return ((i + di, j + dj) for di, dj in Solution.DIRECTIONS
                if 0 <= i + di < self.n and 0 <= j + dj < self.n)

    def largestIsland(self, grid: List[List[int]]) -> int:
        self.n = len(grid)
        area = collections.Counter()

        def dfs(i, j, groupNumber):
            if grid[i][j] != 1:
                return

            grid[i][j] = groupNumber
            area[groupNumber] += 1
            for ni, nj in self.neighbours(i, j):
                dfs(ni, nj, groupNumber)

        groupNumber = 2
        for i, row in enumerate(grid):
            for j, cell in enumerate(row):
                if cell != 1:
                    continue
                dfs(i, j, groupNumber)
                groupNumber += 1

        if not area:
            return 1
        res = max(area.values())

        for i, row in enumerate(grid):
            for j, cell in enumerate(row):
                if cell:
                    continue
                neighbourGroups = {grid[ni][nj] for ni, nj in self.neighbours(i, j)}
                res = max(res, 1 + sum(area[group] for group in neighbourGroups))

        return res

class Solution:
    def largestIsland(self, grid: List[List[int]]) -> int:

        # map to strore index of component along with number of nodes in that component
        map = {}
        index = 1

        for i in range(0, len(grid)):
            for j in range(0, len(grid[0])):
                if(grid[i][j] == 1):
                    index += 1
                    count = self.dfs(i, j, index, grid)
                    map[index] = count

        # Handling edge case where grid has only water
        if(len(map) == 0):
            return 1

        ans = 1
        water_found = False

        for i in range(0, len(grid)):
            for j in range(0, len(grid[0])):
                if(grid[i][j] == 0):
                    water_found = True
                    neighbor_components = set()
                    size = 1
                    for nx, ny in ((i+1, j), (i, j+1), (i-1, j), (i, j-1)):
                        if(nx >= 0 and ny >= 0 and nx < len(grid) and ny < len(grid[0]) and grid[nx][ny] > 1):
                            neighbor_components.add(grid[nx][ny])
                    # Add size of distinct components near water
                    for comp in neighbor_components:
                        size += map[comp]
                    ans = max(ans, size)

        # Edge Case: If no water then whole grid is one large component
        if not water_found:
            return len(grid) * len(grid[0])

        return ans

    # DFS on land 
    def dfs(self, i, j, index, grid):
        grid[i][j] = index
        count = 1
        for nx, ny in ((i+1, j), (i, j+1), (i-1, j), (i, j-1)):
            if(nx < 0 or ny < 0 or nx >= len(grid) or ny >= len(grid[0]) or grid[nx][ny] != 1):
                continue
            count += self.dfs(nx, ny, index, grid)
        return count

class Solution:
    def largestIsland(self, grid: List[List[int]]) -> int:
        n = len(grid)
        stack = []
        tag, area_dict = 2, {}

        for i in range(n):
            for j in range(n):
                if grid[i][j] == 1:
                    area = 0
                    stack.append((i, j))
                    grid[i][j] = tag
                    while stack:
                        x, y = stack.pop()
                        area += 1
                        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            xx, yy = x + dx, y + dy
                            if 0 <= xx < n and 0 <= yy < n and grid[xx][yy] == 1:
                                stack.append((xx, yy))
                                grid[xx][yy] = tag
                    area_dict[tag] = area
                    tag += 1

        if not area_dict:  # if no island
            return 1

        max_area = max(area_dict.values())  # if no ocean
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 0:
                    area = 1
                    islands = set()
                    for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        ii, jj = i + di, j + dj
                        if 0 <= ii < n and 0 <= jj < n and grid[ii][jj] != 0:
                            islands.add(grid[ii][jj])
                    for island in islands:
                        area += area_dict[island]
                    max_area = max(max_area, area)

        return max_area

