class Solution:
	def uniqueLetterString(self, s: str) -> int:
		prev = [-1] * len(s)
		nex = [len(s)] * len(s)

		index = {}
		for i, c in enumerate(s):
			if c in index:
				prev[i] = index[c]    
			index[c] = i

		index = {}
		for i in range(len(s) - 1, -1, -1):
			if s[i] in index:
				nex[i] = index[s[i]]
			index[s[i]] = i

		res = 0
		for i, c in enumerate(s):
			res += (nex[i] - i) * (i - prev[i])

		return res

class Solution:
    def uniqueLetterString(self, s: str) -> int:
        pre, ans, last_i, second_last_i = 0, 0, [-1] * 26, [-1] * 26
        for i in range(len(s)):
            order = ord(s[i]) - ord('A')
            pre += i - last_i[order] - (last_i[order] - second_last_i[order])
            ans += pre
            second_last_i[order], last_i[order] = last_i[order], i
        return ans

class Solution:
    def uniqueLetterString(self, s: str) -> int:
        last = {}
        ans = 0
        step_sum = 0
        for i, c in enumerate(s):
            if c not in last:
                last[c] = [-1, i]
            else:
                step_sum -= (last[c][1] - last[c][0])
                last[c] = [last[c][1], i]
            step_sum += last[c][1] - last[c][0]
            ans += step_sum
        return ans

