class Solution:
    def findReplaceString(self, S: str, indexes: List[int], sources: List[str], targets: List[str]) -> str:
        '''
        Keep S_idx, new string, and a map of indexes to source and target.

        Iterate over S. If S_idx is in the map, check if S[idx:idx+len(source)] == source.
        If so, add target to new string, and advance S_idx by len(source).
        If not, add S[S_idx] to new string and add 1 to S_idx. 
        '''
        S_idx = 0
        new_string = []
        d = {}
        for i in range(len(indexes)):
            idx, src, target = indexes[i], sources[i], targets[i]
            d[idx] = (src, target)

        while S_idx < len(S):
            if S_idx in d:

                source, target = d[S_idx]

                if S[S_idx:S_idx+len(source)] == source:
                    new_string.append(target)
                    S_idx += len(source)
                    continue

            new_string.append(S[S_idx])
            S_idx += 1

        return ''.join(new_string)

class Solution:
    def sumOfDistancesInTree(self, n: int, edges: List[List[int]]) -> List[int]:
        graph = {}
        for u, v in edges: 
            graph.setdefault(u, []).append(v)
            graph.setdefault(v, []).append(u)

        size = [0]*n

        def fn(x, par): 
            """Return size and sum of distances in sub-tree."""
            c = s = 0
            for xx in graph.get(x, []): 
                if xx != par: 
                    cc, ss = fn(xx, x)
                    c, s = c + cc, s + ss + cc
            size[x] = c + 1
            return c + 1, s

        ans = [0]*n
        ans[0] = fn(0, -1)[1]

        stack = [0]
        while stack: 
            x = stack.pop()
            for xx in graph.get(x, []): 
                if not ans[xx]: 
                    ans[xx] = ans[x] + n - 2*size[xx]
                    stack.append(xx)
        return ans

class Solution:
    def sumOfDistancesInTree(self, n: int, edges: List[List[int]]) -> List[int]:
        g = collections.defaultdict(list)
        for u, v in edges:
            g[u].append(v)
            g[v].append(u)

        res = [0]*n
        for i in range(n):
            q = [i]
            visit = set()
            visit.add(i)
            step, cnt = 1, 0
            while q:
                num = len(q)
                for j in range(num):
                    node = q.pop(0)
                    for nei in g[node]:
                        if nei not in visit:
                            cnt += step
                            visit.add(nei)
                            q.append(nei)
                if q:step+=1
            res[i] = cnt

        return res

class Solution:
    def sumOfDistancesInTree(self, n: int, edges: List[List[int]]) -> List[int]:
        g = collections.defaultdict(list)
        for u, v in edges:
            g[u].append(v)
            g[v].append(u)

        d = {i:[1, 0] for i in range(n)}

        def dfs(root, prev):
            for nei in g[root]:
                if nei != prev:
                    dfs(nei, root)
                    d[root][0] += d[nei][0]
                    d[root][1] += (d[nei][0] + d[nei][1])

        def dfs2(root, prev):
            for nei in g[root]:
                if nei != prev:
                    d[nei][1] = d[root][1] - d[nei][0] + (n-d[nei][0])
                    dfs2(nei, root)

        dfs(0, -1)
        dfs2(0, -1)
        res = []
        for key in d:
            res.append(d[key][1])
        return res

class Solution:
    def dfs1(self, v):
        self.visited.add(v)
        self.results[v] = [0, 0]
        for u in self.graph[v]:
            if u not in self.visited:
                self.dfs1(u)
                self.results[v][1] += self.results[u][1] + (self.results[u][0] + 1)
                self.results[v][0] += self.results[u][0] + 1

    def dfs2(self, v, parent):
        self.visited.add(v)
        if parent != -1:
            self.results[v][1] += self.results[parent][1] - (self.results[v][1] + self.results[v][0] + 1) + (
                self.results[parent][0] - (self.results[v][0] + 1) + 1)
            self.results[v][0] += self.results[parent][0] - (self.results[v][0] + 1) + 1
        for u in self.graph[v]:
            if u not in self.visited:
                self.dfs2(u, v)

    def sumOfDistancesInTree(self, n: int, edges: List[List[int]]) -> List[int]:
        self.results = defaultdict(int)
        self.graph = defaultdict(set)
        for v, u in edges:
            self.graph[v].add(u)
            self.graph[u].add(v)
        self.visited = set()
        self.dfs1(0)
        self.visited = set()
        self.dfs2(0, -1)
        return [self.results[k][1] for k in range(n)]

class Solution:
    def sumOfDistancesInTree(self, n: int, edges: List[List[int]]) -> List[int]:
        dp = [[float('inf') for _ in range(n)] for _ in range(n)]

        for s,e in edges:
            dp[s][e] = 1
            dp[e][s] = 1

        for i in range(n):
            dp[i][i] = 0

        for k in range(n):
            for j in range(n):
                for i in range(n):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j])    


        ans = []

        for i in range(n):
            s = 0 
            for j in range(n):
                s += dp[i][j] if dp[i][j] != float('inf') else 0

            ans.append(s)

        return ans

class Solution:
    def sumOfDistancesInTree(self, n: int, edges: List[List[int]]) -> List[int]:
        count = [1]*n
        res = [0]*n

        g = defaultdict(list)

        for s,e in edges:
            g[s].append(e)
            g[e].append(s)

        visited = set()

        def dfs_count_up_to_0(node):
            visited.add(node)

            for c in g[node]:
                if c not in visited:
                    count[node] += dfs_count_up_to_0(c)
                    res[node] += res[c] + count[c]
            return count[node]


        def dfs_fill_up_rest(node):
            visited.add(node)
            for c in g[node]:
                if c not in visited:
                    res[c] =  res[node] - count[c] + n - count[c]
                    dfs_fill_up_rest(c)

        dfs_count_up_to_0(0)

        visited.clear()

        dfs_fill_up_rest(0)

        return res

