class Solution:
    def numSimilarGroups(self, strs: List[str]) -> int:
        def isSimilar(x, y):
            if x == y:
                return True
            x = [i for i in x]
            y = [i for i in y]
            # Save the index where x[i] != y[i]
            idx = []
            for i in range(len(x)):
                if x[i] != y[i]:
                    idx.append(i)
            if len(idx) == 2:
                x[idx[0]], x[idx[1]] = x[idx[1]], x[idx[0]]

                if x == y:
                    return True
                else:
                    return False
            else:
                return False

        def addEdge(x, y, graph):
            graph[x].append(y)
            graph[y].append(x)

        # Create a graph and find the number of components, that's the answer
        graph = {i: [] for i in strs}
        visited = {i: False for i in strs}
		# Construction of graph
        for i in range(len(strs)):
            for j in range(i+1, len(strs)):
			# Check if two nodes are similar
                if isSimilar(strs[i], strs[j]):
                    addEdge(strs[i], strs[j], graph)  
		# Number of components to be stored in "ans" variable
        ans = 0
		# BFS over all the words in strs
        for node in graph.keys():
            if visited[node] == False:
                ans += 1
                queue = [node]
                while queue:
                    u = queue.pop(0)
                    visited[u] = True
                    for child in graph[u]:
                        if visited[child] == False:
                            visited[child] = True
                            queue.append(child)
        return ans

class Solution:
    def numSimilarGroups(self, strs: List[str]) -> int:

        def checksimilar(a, b):
            cnt = 0
            for a_, b_ in zip(a, b):
                if a_ != b_:
                    cnt += 1
            return cnt <= 2
        u = [i for i in range(len(strs))]

        def find_root(i):
            parent = u[i]
            if parent == i:
                return i
            else:
                root = find_root(parent)
                u[parent] = root
                return root

        for i in range(len(strs)):
            for j in range(i+1, len(strs)):
                a_root = find_root(i)
                b_root = find_root(j)
                if a_root != b_root:
                    if checksimilar(strs[i], strs[j]):
                        u[a_root] = b_root

        cnt = set()
        for i in range(len(strs)):
            cnt.add(find_root(i))
        return len(cnt)

