class Solution:

    digits = {1, 2, 3, 4, 5, 6, 7, 8, 9}

    @classmethod
    def magic_3_3(cls, square: List[List[int]]) -> bool:
        if set(sum(square, [])) != Solution.digits:
            return False
        sum_row0 = sum(square[0])
        for r in range(1, 3):
            if sum(square[r]) != sum_row0:
                return False
        if any(sum(col) != sum_row0 for col in zip(*square)):
            return False
