        if len(hand) % groupSize: return False
        count = Counter(hand)
        track = deque([])
        for i, v in sorted(count.items(), key =lambda k:k[0]):
            if track and track[-1][0] != i - 1:
                return False
            track.append([i, v])
            if len(track) == groupSize:
                cur_min = track[0][1]
                track.popleft()
                i = 0
                while i < len(track):
                    if i > 0 and track[i][1] < track[i - 1][1]:
