class Solution:
	def shortestPathLength(self, graph: List[List[int]]) -> int:

		length = len(graph)

		result = 0

		visited_node = []

		queue = []  

		for i in range(length):
			visited_node.append(set([1<<i]))
			queue.append([i,1<<i])

		while queue:

			result = result + 1

			new_queue = []

			for node, value in queue:

				for neigbour_node in graph[node]:

					mid_node = (1<<neigbour_node)|value

					if mid_node not in visited_node[neigbour_node]:

						if mid_node+1 == 1<<length:

							return result

						visited_node[neigbour_node].add(mid_node)

						new_queue.append([neigbour_node, mid_node])

			queue = new_queue

		return 0

class Solution:
    def shortestPathLength(self, graph: List[List[int]]) -> int:
        n = len(graph)
        dist = [[inf]*n for _ in range(n)]

        for i, x in enumerate(graph): 
            dist[i][i] = 0
            for ii in x: dist[i][ii] = 1

        # floyd-warshall 
        for k in range(n): 
            for i in range(n): 
                for j in range(n): 
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

        @cache 
        def fn(x, mask): 
            if mask == 0: return 0 
            ans = inf 
            for i in range(n): 
                if mask &amp; (1 << i): 
                    ans = min(ans, dist[x][i] + fn(i, mask ^ (1<<i)))
            return ans 

        return min(fn(x, (1 << n)-1) for x in range(n))

class Solution:
    def shortestPathLength(self, graph: List[List[int]]) -> int:
        queue = deque([(i, 1<<i) for i in range(len(graph))])
        seen = set(queue)
        ans = 0 
        while queue: 
            for _ in range(len(queue)): 
                u, m = queue.popleft()
                if m == (1<<len(graph)) - 1: return ans 
                for v in graph[u]: 
                    if (v, m | 1<<v) not in seen: 
                        queue.append((v, m | 1<<v))
                        seen.add((v, m | 1<<v))
            ans += 1

