class Solution:
    def loudAndRich(self, richer: List[List[int]], quiet: List[int]) -> List[int]:  
        N = len(quiet)
        graph = [[] for _ in range(N)]
        for i,j in richer:
            graph[j].append(i)
        answer = [None] * N
        def explore(node):
            if answer[node] is None:
                answer[node] = node
                for child in graph[node]:
                    cand = explore(child)
                    if quiet[cand] < quiet[answer[node]]:
                        answer[node]  = cand
            return answer[node]
        return map(explore, range(N))

