        # flip cols
        for c in range(cols):
            if ones[c] >= half:
                continue

            for r in range(rows):
                grid[r][c] = 1 if grid[r][c] == 0 else 0  # flip

        # calculate
        res = 0
        for r in range(rows):
            for c in range(cols):
                res += grid[r][c] * 2 ** (cols - c - 1)

