        for i in range(self.width):
            self.grid[row][i] = int(not self.grid[row][i])

    def flipCol(self, col):
        for i in range(self.height):
            self.grid[i][col] = int(not self.grid[i][col])

    def colSum(self, col):
        total = 0

        for i in range(self.height):
            total += self.grid[i][col]

        return total

