                    leaves.append(root.val)
                if root.left:
                    dfs(root.left, leaves)
                if root.right:
                    dfs(root.right, leaves)
                if root.left == None and root.right == None:
                    leaves.append(root.val)
            return leaves
        return dfs(root1, leaves1) == dfs(root2, leaves2)

class Solution:
