class Solution:
    def findAndReplacePattern(self, words: List[str], pattern: str) -> List[str]:

        def fn(word): 
            """Return True if word matches pattern."""
            mpw, mpp = {}, {}
            for i, (w, p) in enumerate(zip(word, pattern)): 
                if mpw.get(w) != mpp.get(p): return False 
                mpw[w] = mpp[p] = i
            return True 

        return [word for word in words if fn(word)]

class Solution:
    def sumSubseqWidths(self, nums: List[int]) -> int:
        nums.sort()
        ans = 0
        n = len(nums)

        for i in range(n):
            mx = (2**i)*nums[i]
            mn = (2**(n-1-i))*nums[i]
            ans += (mx-mn)

        return ans%(10**9+7)

class Solution:
    def sumSubseqWidths(self, nums: List[int]) -> int:
        MOD = 1_000_000_007
        ans = 0 
        for i, x in enumerate(sorted(nums)): 
            ans += x * (pow(2, i, MOD) - pow(2, len(nums)-i-1, MOD))
        return ans % MOD

