class Solution:
    def surfaceArea(self, grid: List[List[int]]) -> int:
        R = len(grid)
        C = len(grid[0])

        area_of_td = 0
        ''' area of top/down surface'''
        area_of_hr = 0
        ''' area of horizontal surface (row direction)'''
        area_of_vc = 0
        ''' area of vertical surface (column direction)'''

        def ga(pv, cv):
            return cv * 2 - min(pv, cv) * 2

        # Calculate area_of_hr &amp; area_of_td           
        for ri in range(R):
            pv = 0
            for ci in range(C):
                v = grid[ri][ci]
                if v > 0:
                    area_of_td += 2
                    area_of_hr += ga(pv, v)

                pv = v

        # Calculate area_of_vc
        for ct in zip(*grid):
            pv = 0
            for ri in range(R):
                v = ct[ri]
                if v > 0:
                    area_of_vc += ga(pv, v)

                pv = v

        return area_of_td + area_of_hr + area_of_vc

