    def allPossibleFBT(self, N: int) -> List[TreeNode]:

        @lru_cache(None)
        def fn(n):
            """Return all full binary trees of n nodes."""
            if n == 1: return [TreeNode()]
            ans = []
            for nn in range(1, n, 2): 
                for left in fn(nn):
                    for right in fn(n-1-nn): 
                        ans.append(TreeNode(left=left, right=right))
            return ans 

        return fn(N)

