class Solution:
    def allPossibleFBT(self, n: int) -> List[Optional[TreeNode]]:
        if n % 2 == 0:
            return []

        if n == 1:
            return [TreeNode(0)]

        ans = []

        # on left side, we have i nodes. on right side we have (n-i-1) nodes. the extra 1 subtraction is root node.
        # on the left and right side, we can have 1, 3, 5, 7 .... nodes
        for i in range(1, n, 2):
            leftNode = self.allPossibleFBT(i)
            # loop will go till n-2, so at last case, # of nodes in right side will be (n - n - 2 - 1) ==> 1
            rightNode = self.allPossibleFBT(n-1-i)
            for left in leftNode:
                for right in rightNode:
                    node = TreeNode(0, left, right)
                    ans.append(node)
        return ans

