        if not root or not root.left:
            return root

        def inorder_gen(n: TreeNode):
            if not n:
                return
            yield from inorder_gen(n.left)
            yield n
            yield from inorder_gen(n.right)

        node, prev, new_root = root, None, None
        for node in inorder_gen(root):
            node.left = None
            if prev:
                prev.right = node
            else:
                new_root = node
            prev, node = node, node.right

        return new_root

