class Solution:
    def threeSumMulti(self, arr: List[int], target: int) -> int:
        MOD = 10**9 + 7
        res = 0
        c = collections.Counter(arr)
        keys = sorted(c)

        for i, k in enumerate(keys):
            left, right = i, len(keys) - 1

            new_target = target - k
            while left <= right:
                left_v, right_v = keys[left], keys[right]

                if left_v + right_v < new_target:
                    left += 1
                elif left_v + right_v > new_target:
                    right -= 1
                else:
                    if i < left < right:
                        res += c[k] * c[left_v] * c[right_v]
                    elif i == left and left < right:
                        res += c[k] * (c[k] - 1) // 2 * c[right_v]
                    elif i < left and left == right:
                        res += c[k] * c[left_v] * (c[left_v] - 1) // 2
                    else:
                        res += c[k] * (c[k] - 1) * (c[k] - 2) // 6

                    left += 1
                    right -= 1

        return res % MOD

class Solution:
    def threeSumMulti(self, A, target):

        C      = Counter(A)
        keys   = sorted(C.keys())
        MOD    =  10**9 + 7
        self.n = 0

        def add(val):
            self.n = (self.n+val)%MOD

        nk = lambda n,k: factorial(n)//factorial(n-k)//factorial(k)

        for i,x in enumerate(keys):

            # check  x x x
            if (3*x)>target:
                break
            elif C[x]>=3 and (3*x)==target:
                add(nk(C[x],3))

            # check  x x y
            y = target-2*x
            if not (x<y):
                break
            elif C[x]>=2 and (y in C):
                add(nk(C[x],2)*C[y])

            for j in range(i+1,len(keys)):
                y = keys[j]

                # check x y y
                if (x+2*y)>target:
                    break
                elif C[y]>=2 and (x+y*2)==target:
                    add(C[x]*nk(C[y],2))

                # check x y z
                z = target-x-y
                if not (y<z):
                    break
                elif z in C:
                    add(C[x]*C[y]*C[z])

        return self.n

