        # checking if there are any remining characters in typed that we didn't check
        # if the last characters are not the same, then return false
        if typed[-1] != name[-1]:
            return False
        if typed_pointer < len(typed) and typed[typed_pointer:] != res[-1] * len(typed[typed_pointer:]):
            return False
        return res == name

class Solution:
    def isLongPressedName(self, name: str, typed: str) -> bool:
        i,j=0,0
        if name[0]!=typed[0]:
            return False
        if name[-1]!=typed[-1]:
            return False
        while i<len(name):
            if name[i]==typed[j]:
                i+=1
                j+=1
            else:
                if typed[j]==name[i-1]:
                    j+=1
                else:
                    return False
            if j==len(typed) and i<len(name):
                return False
        if j!=len(typed):
            if typed[j]==name[-1]:
                j+=1
            else:
                return False
        return True

class Solution:
