        j = 0
        name_len = len(name)
        if name[0] != typed[0]:
            return False
        for i in range(len(typed)):
            if j == 0 and name[j] == typed[i]:
                j = 1
            elif j < name_len and name[j] == typed[i]:
                j += 1
            elif j == name_len and typed[i] != name[name_len-1]:
                return False
            else:
                if j > 0 and name[j-1] == typed[i]:
                    continue
                else:
                    j = 0
        if j == name_len:
            return True
        else:
            return False

class Solution:
    def minFlipsMonoIncr(self, s: str) -> int:
        n = len(s)
        zero, one = [0] * n, [0] * n
        prefix = suffix = 0
        for i in range(n):
            if s[i] == '1':
                prefix += 1
            zero[i] = prefix       # flip '1' to '0'
            if s[n-1-i] == '0':
                suffix += 1
            one[n-1-i] = suffix    # flip '0' to '1' (from right to left)

        ans = sys.maxsize
        for i in range(n-1):
            ans = min(ans, zero[i] + one[i+1])  # `i` and its left are all '0', and '1's are on its right
        else:    
            ans = min(ans, zero[n-1], one[0])   # zero[n-1] -> all zeros, one[0] -> all ones
        return ans

class Solution:
    def minFlipsMonoIncr(self, S: str) -> int:

        n, prefix, total, res = len(S), 0, S.count('1'), sys.maxsize
        for i in range(n + 1):
            res = min(res, prefix + len(S) - i - total + prefix)
            if i < n: prefix += 1 if S[i] == '1' else 0
        return res

