        ans = one = zero = 0
        for i in range(len(S)): 
            if S[i] == "1": 
                if i and S[i-1] == "0": 
                    if one <= zero: 
                        ans += one # change 1s to 0s
                        one = zero = 0 # reset counters
                one += 1
            else: zero += 1
        return ans + min(zero, one)

