                  5:(),6:(0,1,7),7:(2,6),8:(1,3),9:(2,4)}
        dp = {}
        def recursion(size,cr):
            if size == 0:return 1
            if (size,cr) in dp:return dp[(size,cr)]
            ans = 0
            for x in can_go[cr]:
                ans += recursion(size-1,x)
            dp[(size,cr)] = ans
            return ans
