        return res%1000000007

class Solution:
    def knightDialer(self, n: int) -> int:
        if n == 1: return 10

        MOD = 10**9 + 7
        adj = {
            1: (6, 8),
            2: (9, 7),
            3: (4, 8),
            4: (0, 3, 9),
            5: (),
            6: (0, 1, 7),
            7: (2, 6),
            8: (1, 3),
            9: (2, 4),
            0: (4, 6)
        }

        @cache
        def recurs(start, n):
            if n == 1:
                return 1
            res = 0
            for next in adj[start]:
                res += recurs(next, n - 1)

            return res % MOD

        ans = 0
        for num in adj:
            ans += recurs(num, n)  

        return ans % MOD

