class Solution:
    def validMountainArray(self, arr: List[int]) -> bool:
        n = len(arr)
        if n < 3 or arr[0] >= arr[1]:
            # if size of arr < 3 or zeroth index has value greater than 1st index
            return False

        breakpoint = -1  # we need to find the breakpoint, where graph goes downards, if it exists, so initially set it to -1
        for i in range(n-1):
            # check whether current index has value greater than it's next index, if it is, set this as the breakpoint
            if arr[i] >= arr[i+1]:
                breakpoint = i
                break

        # We need to check the condition, where there is no breakpoint meaning graph is increasing in it's whole life
        if breakpoint == -1:
            return False

        # run the loop after the breakpoint, and check whether there exists any index i which has value greater than i-1
        # if there is, we know, graph is not strictly decreasing anymore, which is invalid
        for i in range(breakpoint+1, n):
            if arr[i] >= arr[i-1]:
                return False

        return True

class Solution:
    def validMountainArray(self, arr: List[int]) -> bool:

        # Guard clause for minimum 3 in a mountain
        if len(arr) < 3:
            return False

        # Guard clause for no repeat neighbors
        for i in range(len(arr)-1):
            if arr[i] == arr[i+1]:
                return False

        # Index of max value
        max_idx = arr.index(max(arr))

        # Check if max occurs at the ends
        if max_idx == 0 or max_idx == len(arr)-1:
            return False

        # Separate the mountain left / right
        increases = arr[0:max_idx]
        decreases = arr[max_idx:]

        # Check increases
        if increases != sorted(increases):
            return False

        # Check decreases
        if decreases != sorted(decreases, reverse=True):
            return False

        return True

