        C = len(strs[0])
        res = 0

        for col in range(C):
            unsorted_flag = False

            for si in range(1, len(strs)):
                if strs[si][col] < strs[si-1][col]:
                    unsorted_flag = True

            if unsorted_flag:
                res += 1 # this col is unsorted

        return res

class Solution:
    def minDeletionSize(self, strs: List[str]) -> int:
        length = len(strs[0])
        res= ''.join(strs)
        count =0
        for idx in range(length):
            index=idx
            while(index+length<len(res)):
                if(ord(res[index])>ord(res[index+length])):
                    count+=1
                    break
                index+=length
        return count

