class Solution:
    def minIncrementForUnique(self, nums: List[int]) -> int:
        nums.sort()
        new=nums[0]+1
        stk=set({nums[0]})
        ans=0
        for n in nums[1:]:
            if n not in stk:
                stk.add(n)
                new=n+1
            else:
                ans+=new-n
                stk.add(new)
                new+=1
        return ans

class Solution:
    def minIncrementForUnique(self, nums: List[int]) -> int:
        nums.sort()
        cnt = 0
        for idx in range(1, len(nums)):
            prev = nums[idx - 1]

            if prev >= nums[idx]:
                cnt += prev - nums[idx] + 1
                nums[idx] = prev + 1

        return cnt

class Solution:
    def minIncrementForUnique(self, A: List[int]) -> int:
        ans = cap = 0
        for x in sorted(A): 
            ans += max(0, cap - x)
            cap = max(cap, x) + 1
        return ans

class Solution:
    def minIncrementForUnique(self, A: List[int]) -> int:
        m, c, _ = -math.inf, 0, A.sort()
        for a in A:
            if a <= m:
                c += 1 + m - a
                m += 1
            else: m = a
        return c

class Solution:
    def minIncrementForUnique(self, A: List[int]) -> int:
        m, c, _ = -math.inf, 0, A.sort()
        for a in A: (c, m) = (c + (1 + m - a), m + 1) if a <= m else (c, a)
        return c


