class Solution:
    def removeStones(self, stones: List[List[int]]) -> int:
        xdict = {}
        ydict = {} 

        for x, y in stones:
            if x not in xdict:
                xdict[x] = [y]
            else:
                xdict[x].append(y)
            if y not in ydict:
                ydict[y] = [x]
            else:
                ydict[y].append(x)
        groups = 0
        while xdict:
            ys = set(xdict.popitem()[1])
            xs = set()
            while ys:
                while ys:
                    y = ys.pop()
                    if y not in ydict:
                        continue
                    for x in ydict.pop(y):
                        xs.add(x)

                while xs:
                    x = xs.pop()
                    if x not in xdict:
                        continue
                    for y in xdict.pop(x):
                        ys.add(y)
            groups += 1
        return len(stones) - groups

