    def removeStones(self, stones: List[List[int]]) -> int:
        p={}
        def find(m):
            if m!=p[m]:
                p[m]=find(p[m])

            return p[m]

        def union(x,y):
            p.setdefault(x,x)
            p.setdefault(y,y)

            r1=find(x)
            r2=find(y)
            if r1!=r2:
                p[r2]=r1

        for i,j in stones:
            union(i,~j)

        roots=set()

        for key in p:
            root=find(key)
            roots.add(root)

        return len(stones)-len(roots)

