class Solution:
    def removeStones(self, stones: List[List[int]]) -> int:
        n = len(stones)
        freq = defaultdict(int)
        visited = set()

        def connect(i,src,label):
            visited.add(i)
            freq[label]+=1

            for j in range(n):

                if j not in visited:
                    stone = stones[j]

                    #check if stone is in same row
                    if stone[0]==src[0]:
                        connect(j,stone,label)

                    #check if stone is in same col
                    elif stone[1]==src[1]:
                        connect(j,stone,label)


        #give lebel number to each component
        label = 0
        for i in range(n):
            if i not in visited:
                connect(i,stones[i],label)
                label+=1

        #we can remove all nodes except last node in a chain with more than1 nodes
        ans = 0
        for v in freq.values():
            if v>1:
                ans += v-1

        return ans

class Solution:
    def removeStones(self, stones: List[List[int]]) -> int:
        root = [i for i in range(len(stones))]
        rank = [1] * len(stones)
        rows = collections.defaultdict(list)
        cols = collections.defaultdict(list)

        def unify_stones():
            for i in range(len(stones)):
                r, c = stones[i]
                for point in rows[r]:
                    union(i, point)
                for point in cols[c]:
                    union(i, point)
                rows[r].append(i)
                cols[c].append(i)

            for i in range(len(root)):
                root[i] = find(i)

        def find(x):
            if x == root[x]:
                return x
            root[x] = find(root[x])
            return root[x]

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                if rank[rootX] < rank[rootY]:
                    root[rootX] = rootY
                elif rank[rootY] < rank[rootX]:
                    root[rootY] = rootX
                else:
                    root[rootY] = rootX
                    rank[rootX] += 1

        unify_stones()
        return len(stones) - len(set(root))

class Solution:
    def bagOfTokensScore(self, tokens: List[int], power: int) -> int:
        score=0
        tokens.sort()
        i=0
        j=len(tokens)-1
        mx=0
        while i<=j:
            if tokens[i]<=power:
                power-=tokens[i]
                score+=1
                i+=1
                mx=max(mx,score)
            elif score>0:
                score-=1
                power+=tokens[j]
                j-=1
            else:
                break
        return mx

