    def bagOfTokensScore(self, tokens: List[int], power: int) -> int:
        tokens.sort()
        score,ans=[0]*2
        left,right=0,len(tokens)-1
        while left<=right:
            if power>=tokens[left]:
                power-=tokens[left]
                score+=1
                left+=1
            elif score>0:
                power+=tokens[right]
                score-=1
                right-=1
