class Solution:
    def bagOfTokensScore(self, tokens: List[int], power: int) -> int:

        if tokens == []:
            return 0

        tokens.sort()
        score = 0

        # play the smallest token face up until power is about to drop below 1
        while len(tokens) > 0 and power - tokens[0] > 0:
            lo_token = tokens.pop(0)
            power -= lo_token
            score += 1
            # play the largest token face down to increase power when required
            if len(tokens) > 1 and power - tokens[0] <= 0:
                hi_token = tokens.pop()
                power += hi_token
                score -= 1

        if len(tokens) > 0 and tokens[0] == power:
            score += 1

        return score

class Solution:
    def largestTimeFromDigits(self, A: List[int]) -> str:
        hh = mm = -1
        for x in set(permutations(A, 4)): 
            h = 10*x[0] + x[1]
            m = 10*x[2] + x[3]
            if h < 24 and m < 60 and 60*h + m > 60*hh + mm: hh, mm = h, m
        return f"{hh:02}:{mm:02}" if hh >= 0 else ""

class Solution:
    def largestTimeFromDigits(self, A: List[int]) -> str:

        def permutations(i=0): 
            """Return all permutations via generator."""
            if i == len(A): yield A
            for ii in range(i, len(A)): 
                A[i], A[ii] = A[ii], A[i]
                yield from permutations(i+1)
                A[i], A[ii] = A[ii], A[i]

        hh = mm = -1
        for x in permutations(): 
            h = 10*x[0] + x[1]
            m = 10*x[2] + x[3]
            if h < 24 and m < 60 and 60*hh + mm < 60*h + m: hh, mm = h, m 
        return f"{hh:02}:{mm:02}" if hh >= 0 else ""

class Solution:
    def largestTimeFromDigits(self, arr: List[int]) -> str:

        def fn(i): 
            """Return unique permutations of arr."""
            if i == 4: yield arr
            else: 
                seen = set()
                for ii in range(i, 4):
                    if arr[ii] not in seen: 
                        seen.add(arr[ii])
                        arr[i], arr[ii] = arr[ii], arr[i]
                        yield from fn(i+1)
                        arr[i], arr[ii] = arr[ii], arr[i]

        hh = mm = -1
        for x in fn(0):
            h = 10*x[0] + x[1]
            m = 10*x[2] + x[3]
            if h < 24 and m < 60: hh, mm = max((hh, mm), (h, m))
        return f"{hh:02}:{mm:02}" if hh > -1 else ""

class Solution:
    def valid(self, time):
        if time[0] > 2 or time[0] < 0:
            return False
        if time[0] == 2 and time[1] > 3:
            return False
        if time[2] > 5 or time[0] < 0:
            return False
        return True

    def solve(self, arr):
        if len(arr) == 1:
            return [arr]
        res = []
        for i in range(len(arr)):
            val = arr[i]
            rem = self.solve(arr[:i]+arr[i+1:])
            for j in range(len(rem)):
                temp = [val]+rem[j]
                if len(temp) == 4:
                    if self.valid(temp):
                        res.append([val]+rem[j])
                else:
                    res.append([val]+rem[j])
        return res

    def largestTimeFromDigits(self, arr: List[int]) -> str:
        res = self.solve(arr)
        if not res:
            return ""
        res.sort()
        ans = res.pop()
        ans = [str(i) for i in ans]
        ans.insert(2, ":")
        return "".join(ans)

class Solution:
    def largestTimeFromDigits(self, arr: List[int]) -> str:
        def check(num):
            if num[0] > 2 : return False
            if num[0] == 2 and num[1] > 3: return False
            if num[2] > 5 : return False
            return True
        p = itertools.permutations(arr)
        ans = None
        for i in p:
            if check(i) == True:
                if ans == None or i > ans: ans = i
        if ans == None:return ""
        return str(ans[0])+str(ans[1])+':'+str(ans[2])+str(ans[3])

class Solution:
    def largestTimeFromDigits(self, arr: List[int]) -> str:

        if min(arr)>3:
            return ""

        arr.sort()

