class Solution:
    def largestTimeFromDigits(self, A: List[int]) -> str:        
        def get_new_a_without_n(A, n):
            a = []
            a.extend(A)
            a.remove(n)
            return a

        def build_time(result, digit=0, rest_numbers=A):
            if len(result) == 4:
                return result
            else:                
                if digit == 0:
                    # First digit between 2-0
                    for n in range(2, -1, -1):
                        if n in rest_numbers:
                            a = get_new_a_without_n(rest_numbers, n)
                            result.append(n)
                            if build_time(result, 1, a):
                                return result

                            del result[-1]
                elif digit == 1:
                    # Second digit:
                    #   If first digit is 2, then between 3-0
                    #   Else between 9-0
                    if result[-1] == 2:
                        nrange = range(3, -1, -1)
                    else:
                        nrange = range(9, -1, -1)

                    for n in nrange:
                        if n in rest_numbers:
                            a = get_new_a_without_n(rest_numbers, n)
                            result.append(n)
                            if build_time(result, 2, a):
                                return result

                            del result[-1]
                elif digit == 2:
                    # Third digit between 5-0                
                    for n in range(5, -1, -1):
                        if n in rest_numbers:
                            a = get_new_a_without_n(rest_numbers, n)
                            result.append(n)
                            if build_time(result, 3, a):
                                return result

                            del result[-1]
                else:
                    # The last digit between 9-0
                    if rest_numbers[0] < 10:
                        result.append(rest_numbers[0])
                        return result

                return None

        result = []
        build_time(result)

        if result:
            return "{}{}:{}{}".format(result[0], result[1], result[2], result[3])
        else:
            return ""

