class Solution:
    def prisonAfterNDays(self, cells: List[int], N: int) -> List[int]:
        id_cells, cells_id = dict(), dict()
        prev, loop = cells[:], None
        for k in range(N):
            for i in range(1, 7):
                cells[i] = 1 if prev[i+1] == prev[i-1] else 0
            cells[0] = cells[7] = 0 
            if tuple(cells) in cells_id: 
                loop = k-cells_id[tuple(cells)]
                break
            id_cells[k], cells_id[tuple(cells)] = cells[:], k
            prev = cells[:]
        return id_cells[(N-k-1)%loop] if loop else cells

class Solution:
    def isCompleteTree(self, root: Optional[TreeNode]) -> bool:

        res=[]
        from collections import deque
        q=deque()
        q.append((root,1))

        while q:
            node,ind=q.popleft()
            res.append(ind)
            if node.left:
                q.append((node.left,2*ind))
            if node.right:
                q.append((node.right,2*ind+1))

        for i in range(len(res)-1):
            if res[i+1]-res[i]!=1:
                return False

        return True

