                if grid[i][j] == "/":
                    mat[i * 3][j * 3 + 2] = 1;
                    mat[i * 3 + 1][j * 3 + 1] = 1;
                    mat[i * 3 + 2][j * 3] = 1;
                if grid[i][j] == "\\":
                    mat[i * 3][j * 3] = 1;
                    mat[i * 3 + 1][j * 3 + 1] = 1;
                    mat[i * 3 + 2][j * 3 + 2] = 1;

        def dfs(grid: List[List[int]], count: int, x, y, n):
                if grid[x][y] != 0: return
                grid[x][y] = count
                if x + 1 < n : 
                    dfs(grid, count, x + 1, y, n)
                if y + 1 < n: 
                    dfs(grid, count, x, y + 1, n)
                if x - 1 >= 0: 
                    dfs(grid, count, x - 1, y, n)
                if y - 1 >= 0: 
                    dfs(grid, count, x, y - 1, n)

        count = 0
        for i in range(n3):
            for j in range(n3):
                if mat[i][j] == 0:
                    count += 1
                    dfs(mat, count, i, j, n3)
        return count

class Solution:
    def regionsBySlashes(self, grid: List[str]) -> int:
        n,m=len(grid),len(grid[0])
        parent=[i for i in range((n+1)*(m+1))]
        rank=[1 for i in range((n+1)*(m+1))]
        matrix=[]
        cc=0
        for i in range(n+1):
            li=[]
            for j in range(m+1):
                li.append(cc)
                cc+=1
            matrix.append(li)
        boundary=[]
        boundary+=matrix[0]
        for row in range(1,len(matrix)-1):
            li=[matrix[row][0],matrix[row][-1]]
            boundary+=li
        boundary+=matrix[-1]
        boundary=boundary[1:]
        def find(x):
            if parent[x]==x:
                return x
            temp=find(parent[x])
            parent[x]=temp
            return temp
        def union(x,y):
            parentx=find(x)
            parenty=find(y)
            if parentx!=parenty:
                if rank[parentx]<rank[parenty]:
                    parent[parentx]=parenty
                elif rank[parentx]>rank[parenty]:
                    parent[parenty]=parentx
                else:
                    parent[parentx]=parenty
                    rank[parenty]+=1
        for b in boundary:
            union(0,b)
        count=1
        for row in range(n):
            for col in range(m):
                if grid[row][col]==" ":
                    continue
                elif grid[row][col]=="\\":
                    point1=row*(m+1)+col
                    point2=(row+1)*(m+1)+(col+1)
                else:
                    point1=((row+1)*(m+1))+(col)
                    point2=(row*(m+1))+(col+1)
                pp1=find(point1)
                pp2=find(point2)
                union(point1,point2)
                if pp1==pp2:
                    count+=1
        return count

