class Solution:
    def maxTurbulenceSize(self, arr: List[int]) -> int:

        if len(set(arr)) == 1:
            return 1

        longest = 2
        curr = 2
        for i in range(1, len(arr) - 1):
            if arr[i - 1] > arr[i]  and arr[i] < arr[i + 1]:
                curr += 1
            elif arr[i - 1] < arr[i] and arr[i] > arr[i + 1]:
                curr += 1
            else:
                curr = 2

            longest = max(curr, longest)

        return longest

class Solution:
    def maxTurbulenceSize(self, arr: List[int]) -> int:
        def cmp(a,b):
            if a == b: return 0
            if a > b : return 1
            return -1

        n = len(arr)
        ans = 1
        prev = 0
        for i in range(1,n):
            c = cmp(arr[i-1],arr[i])
            if c == 0:
                # we shift prev to i 
                prev = i
            elif i == n-1 or c * cmp(arr[i],arr[i+1]) != -1:
                ans = ans if ans > i - prev + 1 else i - prev + 1
                prev = i
        return ans

class Solution:
    def maxTurbulenceSize(self, arr: List[int]) -> int:

        def iterating(arr):   
            prev = arr[0]
            tmp = None
            for x in arr[1:]:
                if x == prev:
                    yield '='
                elif x > prev:
                    yield '<'
                else:
                    yield '>'
                prev = x

        queue = deque([])
        ans = 0
        for x in iterating(arr):

            if x == '=':
                queue.clear()
                continue

            if queue and x == queue[-1]:
                queue.clear()

            queue.append(x)
            ans = max(ans, len(queue))

        return ans+1

class Solution:
def maxTurbulenceSize(self, arr: List[int]) -> int:
    n=len(arr)
    if max(arr)==min(arr): return 1                 # If all elements are equal.
    if n<3: return n                                # if size of array is less then 3.

    left, right, res = [0]*n, [0]*n, [0]*n
    for i in range(1,n):
        left[i] = 1 if arr[i]>arr[i-1] else -1 if arr[i]<arr[i-1] else 0
        ind = n-i-1
        right[ind] = 1 if arr[ind]>arr[ind+1] else -1 if arr[ind]<arr[ind+1] else 0

    for i in range(1,n):
        if left[i]==right[i]:
            res[i]=res[i-1]+1

    return max(res)+2

class Solution:
    def distributeCoins(self, v: Optional[TreeNode], parent=None) -> int:
        if v is None:
            return 0
        m = self.distributeCoins(v.left, v) + self.distributeCoins(v.right, v)
        if v.val != 1:
            parent.val += v.val - 1
            m += abs(v.val - 1)
        return m

class Solution:
    def distributeCoins(self, root: TreeNode) -> int:
        count = 0

        def traverse(node: TreeNode) -> int:
            nonlocal count
            if not node:
                return 0
            move = node.val + traverse(node.left) + traverse(node.right) - 1
            count += abs(move)
            return move

        traverse(root)
        return count

class Solution:
    def distributeCoins(self, root: TreeNode) -> int:

        def fn(node):
            """Return surplus and number of moves at node."""
            if not node: return 0, 0 # surplus | move 
            xtr0, mv0 = fn(node.left)
            xtr1, mv1 = fn(node.right)
            return node.val - 1 + xtr0 + xtr1, mv0 + mv1 + abs(xtr0) + abs(xtr1)

        return fn(root)[1]

class Solution:
    def distributeCoins(self, root: TreeNode) -> int:

        def fn(node):
            """Return flux (surplus/deficit) of node."""
            nonlocal ans 
            if not node: return 0
            left, right = fn(node.left), fn(node.right)
            ans += abs(left) + abs(right)
            return node.val - 1 + left + right # surplus/deficit 

        ans = 0
        fn(root)
        return ans

class Solution:
    def uniquePathsIII(self, grid: List[List[int]]) -> int:
		# first, prepare the starting and ending points
		# simultaneously, record all the non-obstacle coordinates
        start = end = None
        visit = set()
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] == 0:
                    visit.add((i, j))
                elif grid[i][j] == 1:
                    start = (i, j)
                elif grid[i][j] == 2:
                    end = (i, j)
                    visit.add((i, j))

        def backtrack(x, y, visit):
            if (x, y) == end:
				# implement success condition: valid only if there are no more coordinates to visit
                return len(visit) == 0
            result = 0  # assume no valid paths by default

			# we need to try every possible path from this coordinate
            if (x-1, y) in visit:
				# the coordinate directly above this one is non-obstacle, try that path
                visit.remove((x-1, y))  # first, note down the 'visited status' of the coordinate
                result += backtrack(x-1, y, visit)  # then, DFS to find all valid paths from that coordinate
                visit.add((x-1, y))  # last, reset the 'visited status' of the coordinate
            if (x+1, y) in visit:
				# the coordinate directly below this one is non-obstacle, try that path
                visit.remove((x+1, y))
                result += backtrack(x+1, y, visit)
                visit.add((x+1, y))
            if (x, y-1) in visit:
				# the coordinate directly to the left of this one is non-obstacle, try that path
                visit.remove((x, y-1))
                result += backtrack(x, y-1, visit)
                visit.add((x, y-1))
            if (x, y+1) in visit:
				# the coordinate directly to the right of this one is non-obstacle, try that path
                visit.remove((x, y+1))
                result += backtrack(x, y+1, visit)
                visit.add((x, y+1))
            return result

        return backtrack(start[0], start[1], visit)  # we start from the starting point, backtrack all the way back, and consolidate the result

class Solution:
    def uniquePathsIII(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0]) # dimensions 
        empty = 0 
        for i in range(m):
            for j in range(n): 
                if grid[i][j] == 1: start = (i, j)
                elif grid[i][j] == 0: empty += 1 # empty squares 

        def fn(i, j, empty): 
            """Count paths via backtracking."""
            nonlocal ans 
            if grid[i][j] == 2: 
                if empty == -1: ans += 1
                return 
            grid[i][j] = -1 # mark as visited 
            for ii, jj in (i-1, j), (i, j-1), (i, j+1), (i+1, j): 
                if 0 <= ii < m and 0 <= jj < n and grid[ii][jj] != -1: 
                    fn(ii, jj, empty-1)
            grid[i][j] = 0 # backtracking

        ans = 0 
        fn(*start, empty)
        return ans

class Solution:
    def uniquePathsIII(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        mask = 0
        for i in range(m):
            for j in range(n): 
                if grid[i][j] == 1: start = (i, j)
                if grid[i][j] in (-1, 1): mask ^= 1 << i*n+j

        @cache
        def fn(i, j, mask): 
            """Return unique paths from (i, j) to end"""
            if grid[i][j] == 2 and mask == (1<<m*n) - 1: return 1
            ans = 0
            for ii, jj in (i-1, j), (i, j-1), (i, j+1), (i+1, j): 
                if 0 <= ii < m and 0 <= jj < n: 
                    kk = ii*n + jj 
                    if not mask &amp; 1<<kk: ans += fn(ii, jj, mask ^ 1<<kk)
            return ans 

        return fn(*start, mask)

class Solution:
