class Solution:
	def uniquePathsIII(self, grid: List[List[int]]) -> int:
		row, col = len(grid), len(grid[0])
		queue = deque([])
		numSquare = 1 # include starting point
		visited = set()

		for x in range(row):
			for y in range(col):
				if grid[x][y] == 1:
					visited.add((x,y))
					queue.append((x, y, visited))

				if grid[x][y] == 0:
					numSquare += 1            

		return self.bfs(queue, grid, row, col, numSquare)

	def bfs(self, queue, grid, row, col ,numSquare):
		result = 0
		while queue:
			x, y, visited = queue.popleft()

			for nx, ny in [[x+1,y], [x-1,y], [x,y+1], [x,y-1]]:
				if 0<=nx<row and 0<=ny<col and (nx,ny) not in visited:
					if grid[nx][ny] == 0:
						queue.append((nx, ny, visited | {(nx,ny)}))

					if grid[nx][ny] == 2:
						if len(visited) == numSquare:
							result += 1

		return result

class Solution:
    def uniquePathsIII(self, grid: List[List[int]]) -> int:
        rows = len(grid)
        cols = len(grid[0])
        nonObstacle = 0
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == 1:
                    start = [i,j]
                if grid[i][j] == 2:
                    end = [i,j]
                if grid[i][j]==0:
                    nonObstacle+=1
        count = 0
        directions = [[0,-1],[-1,0],[1,0],[0,1]]
        stack = []
        nonObsCount = 0
        stack.append((start, [start],nonObsCount ))
        grid[start[0]][start[1]] = -1  # mark start node as visited
        while stack:
            [r,c], path,nonObsCount  = stack.pop()
            for d in directions:
                ni,nj = r+d[0],c+d[1]
				#traverse only for non obstacle nodes
                if 0<=ni<rows and 0<=nj<cols and grid[ni][nj]!=-1:
                    if grid[ni][nj] == 2:
						#if you've reached the end node, check if you've visited all non obstacle nodes
                        if nonObsCount==nonObstacle:
                            #print('One of the paths',path)
                            count += 1
                        continue
                    elif grid[ni][nj] == 1:
                        continue
                    else:
                       #if [ni,nj] not in path, it's not visited yet, add it to the path
                        if [ni,nj] not in path:
                            stack.append(([ni,nj],path+[[ni,nj]], nonObsCount+1))
                        else:
							 #check if [ni,nj] already in path, if so continue as its visited already
                            continue
        return count

class Solution:
    def uniquePathsIII(self, A: List[List[int]]) -> int:
        m, n = len(A), len(A[0])
        start = end = p = 0 
        # Flatten the array for better performance
        A = reduce(operator.add, A)
        for key, val in enumerate(A):
            if val >= 0:
                p += 1 # Count the number of none obstacle square  
                if val == 1: start = key # get start and end index
                if val == 2: end = key

        l = m*n 
        def dfs(i, p): 
            if i == end and not p: 
                return 1
            if A[i] < 0 or i == end: return 0
            A[i], res= -1, 0 # place an obstacle on the square when passing by

            # check every legal action
            if i >= n: res += dfs(i - n, p - 1)
            if i < l - n: res += dfs(i + n, p - 1)
            if i % n: res += dfs(i - 1, p - 1)
            if (i - n + 1) % n: res += dfs(i + 1, p - 1) 

            A[i] = 0 # backtrack, remove obstacle
            return res
        return dfs(start, p-1)

class Solution:
    def countTriplets(self, nums: List[int]) -> int:
        freq = defaultdict(int)
        for x in nums: 
            for y in nums: 
                freq[x&amp;y] += 1

        ans = 0
        for x in nums: 
            mask = x = x ^ 0xffff
            while x: 
                ans += freq[x]
                x = mask &amp; (x-1)
            ans += freq[0]
        return ans

