class Solution:
    def countTriplets(self, nums: List[int]) -> int:
        ans = 0
        mem = [0] * (1 << 16)
        size = len(nums)

        for i in range(size):
            for j in range(i, size):
                mem[nums[i]&amp;nums[j]] += 2 if i != j else 1

        for ij in range(1 << 16):
            if mem[ij] > 0:
                for k in nums:
                    if k &amp; ij == 0:
                        ans += mem[ij]
        return ans

class Solution:
    def mincostTickets(self, days: List[int], costs: List[int]) -> int:
        dp = [0] * (days[-1]+1)
        date = 0 
        for idx in range(1,len(dp)):
            if idx == days[date]:
                one_day = dp[idx-1] + costs[0]
                seven_day = dp[idx-7] + costs[1] if idx - 7 >= 0 else costs[1]
                thirty_day = dp[idx-30] + costs[2] if idx - 30 >= 0 else costs[2]
                dp[idx] = min(one_day,seven_day,thirty_day)
                date += 1
            else:
                dp[idx] = dp[idx-1]
        return dp[-1]

class Solution:
    def mincostTickets(self, days: List[int], costs: List[int]) -> int:
        # map the number of days per ticket to the cost
        cost_map = {
            1: costs[0],
            7: costs[1],
            30: costs[2],
        }

        travelling_days = set(days)  # set of active travel days
        dp_costs = [0 for x in range(days[-1] + 1)]  # tracks the min cost day

        for i in range(days[-1] + 1):
            # store most recent lowest sum in arr to use later
            if i not in travelling_days:
                dp_costs[i] = dp_costs[i - 1]
                continue

            possible_costs = []
            for ticket,cost in cost_map.items():
                day_diff = i - ticket

                if day_diff <= 0:
                    # this ticket will cover the total cost
                    possible_costs.append(cost)
                else:
                    # ticket was bought day_diff ago
                    # sum lowest cost on day_diff with new ticket cost
                    possible_costs.append(cost + dp_costs[day_diff])

            # find min of all ticket options on this day
            dp_costs[i] = min(possible_costs)

        return dp_costs[-1]

class Solution:
    def mincostTickets(self, days: List[int], costs: List[int]) -> int:

        days = set(days)        
        graph = {0 : 1, 1 : 7, 2: 30}

        @functools.lru_cache(None)
        def recurse(day, end):

            if day > end:
                return 0

            if day not in days:
                return recurse(day+1, end)

            return min([
                c + recurse(day+graph[i], end)
                for i,c in enumerate(costs)   
            ])

        return recurse(1, max(days))

class Solution:
    def mincostTickets(self, days: List[int], costs: List[int]) -> int:

        @lru_cache(None)
        def fn(i):
            """Return minimum cost of traveling on days[i:]"""
            if i == len(days): return 0 # boundary condition (no more travel)
            ans = inf
            for cost, d in zip(costs, (1, 7, 30)): 
                ii = bisect_left(days, days[i]+d)
                ans = min(ans, cost + fn(ii))
            return ans 

        return fn(0)

class Solution:
    def mincostTickets(self, days: List[int], costs: List[int]) -> int:        
        cost_of_day = [0] * 366  
        for index, day in enumerate(days):
            if index == 0:
                cost_of_day[day] = min(costs)    
                continue
            for i in range(days[index-1]+1, day):
                cost_of_day[i] = cost_of_day[i-1]
