class Solution:
    def mincostTickets(self, days: List[int], costs: List[int]) -> int:
        days = sorted(days)
        res = [0] * (days[-1] + 1)  # represent each day. 

        start = days[0]
        res[start] = min(costs)  # in case day 7 pass is cheaper than day 1
        days = set(days)

        for d in range(start+1, len(res)):
            if d not in days:  # only consider the day in the days set.
                res[d] = res[d-1]  
            else:
                # case 1: buy day 1 pass for today (d)
                case_1 = costs[0] + res[d-1]

                # case 2: buy day 7 pass for today (d)
                if d - 7 >= start:
                    case_2 = res[d-7] + costs[1]
                else:
                    case_2 = costs[1]

                # case 3: buy day 30 pass for today (d)
                if d - 30 >= start:
                    case_3 = res[d-30] + costs[-1]
                else:
                    case_3 = costs[-1]

                res[d] = min(case_1, case_2, case_3)

        return res[-1]

class Solution:
    def mincostTickets(self, days: List[int], costs: List[int]) -> int:
        travel = [False] * (days[-1]) + [True] * 31
        for day in days: travel[day] = True
        dp = [0] * (days[-1] + 31)
        for i in range(days[-1], -1, -1):
            if travel[i]:
                dp[i] = min(costs[0] + dp[i + 1], costs[1] + dp[i + 7], costs[2] + dp[i + 30])
            else:
                dp[i] = dp[i + 1]
        return dp[0]

class Solution:
    def mincostTickets(self, days: List[int], costs: List[int]) -> int:
        min_cost = float('inf')
        que = deque()
        # enqueue the possible state of day 1
        que.append((days[0], costs[0]))
        que.append((days[0]+7-1, costs[1]))
        que.append((days[0]+30-1, costs[2]))
        last_day = days[-1]
        for i in range(1, len(days)):
            for _ in range(len(que)):
                node = que.popleft()
                if node[0] < days[i]:
                    # try taking all the three pass on that day and enqueue 
                    que.append((days[i], node[1]+costs[0]))
                    if days[i] + 7 - 1 >= last_day:
                        min_cost = min(min_cost, node[1] + costs[1])
                    else:
                        que.append((days[i]+7-1, node[1]+costs[1]))
                    if days[i] + 30 - 1 >= last_day: 
                        min_cost = min(min_cost, node[1] + costs[2])
                    else:
                        que.append((days[i]+30-1, node[1]+costs[2]))
                else:
                    que.append(node)
        for _ in range(len(que)):
            node = que.popleft()
            min_cost = min(min_cost, node[1])
        return min_cost

class Solution(object):

    def mincostTickets(self,days, costs):
        dp = {}
        def index_finder(i,days,arr):
            key = arr[i]
            while i<len(arr) and arr[i]< key+days:
                i+=1
            return i

        def solve(days,i,costs):


            if i>=len(days):
                return 0
            if days[i] in dp:
                return dp[days[i]]
            # cost 1 
            j = index_finder(i,1,days)
            v1 = solve(days,j,costs)+costs[0]
            # cost 2
            j = index_finder(i,7,days)
            v2 = solve(days,j,costs)+costs[1]
            # cost3
            j = index_finder(i,30,days)
            v3 = solve(days,j,costs)+costs[2]        
            dp[days[i]] = min(v1,v2,v3)
            return dp[days[i]]
        return solve(days,0,costs)

class Solution:
    def strWithout3a3b(self, a: int, b: int) -> str:
        res = []
        while a + b > 0:
            if len(res) >= 2 and res[-2:] == ['a', 'a']:
                res.append('b')
                b-=1
            elif len(res) >= 2 and res[-2:] == ['b', 'b']:
                res.append('a')
                a-=1
            elif a > b:
                res.append('a')
                a-=1
            else:
                res.append('b')
                b-=1

        return ''.join(res)

class Solution:
