class Solution:
    def strWithout3a3b(self, a: int, b: int) -> str:
        heap = []
        if a > 0:
            heapq.heappush(heap, (-a, 'a'))
        if b > 0:
            heapq.heappush(heap, (-b, 'b'))

        s = ''
        while heap:
            try:
                curr_char_remain, current_char = heapq.heappop(heap)
            except IndexError:
                break
            curr_char_remain = abs(curr_char_remain)
            if s[-2:] != 2 * current_char:
                if curr_char_remain >= 2:
                    s += 2 * current_char
                    curr_char_remain -= 2
                    if curr_char_remain > 0:
                        heapq.heappush(heap, (-1 * curr_char_remain, current_char))
                else:
                    s += current_char
            else:
                try:
                    n_curr_char_remain, n_current_char = heapq.heappop(heap)
                except IndexError:
                    break
                n_curr_char_remain = abs(n_curr_char_remain)
                s += n_current_char
                n_curr_char_remain -= 1
                if n_curr_char_remain != 0:
                    heapq.heappush(heap, (-1 * n_curr_char_remain, n_current_char))
                heapq.heappush(heap, (-1 * curr_char_remain, current_char))
        return s

class Solution:
    def strWithout3a3b(self, a: int, b: int) -> str:
		# n = current # of consecutive chracters in res that are the same
		# positive if it's consecutive as, negative if it's bs
        n = 0
        res = ''
        while a and b:
            if n == -2 or (n != 2 and a >= b):
                res += 'a'
                a -= 1
                n = max(1, n + 1)
            else:
                res += 'b'
                b -= 1
                n = min(-1, n - 1)
        return res + (a * 'a') + (b * 'b')

