class Solution:

    def __init__(self):
        self.order = collections.defaultdict(dict)

    def dfs(self, node, x, y):
        if not node:
            return
        self.order[x][y] = self.order[x].get(y, []) + [node.val]
        self.dfs(node.left, x-1, y-1)
        self.dfs(node.right, x+1, y-1)

    def verticalTraversal(self, root: TreeNode) -> List[List[int]]:
        # placeholder to store the list of reports
        verticalOrder = []

        # step 1 : traverse the tree, to create list of values at each (x, y)
        self.dfs(root, 0, 0)

        # step 2 : at each x, sort the values first by y, then by value
        for x in sorted(self.order):
            report = []
            for y in sorted(self.order[x], reverse=True):
                report += sorted(self.order[x][y]) 
            verticalOrder.append(report)

        # step 3 : return the list of reports
        return verticalOrder

class Solution:
    def verticalTraversal(self, root: Optional[TreeNode]) -> List[List[int]]:
        d = defaultdict(list)
        q = [(root, 0)]
        start = end = 0
        while q :
            n = len(q)
            curr = defaultdict(list)
            for i in range(n) :
                temp = q.pop(0)
                start = min(start, temp[1])
                end = max(end, temp[1])
                curr[temp[1]].append(temp[0].val)
                if temp[0].left :
                    q.append((temp[0].left, temp[1]-1))
                if temp[0].right :
                    q.append((temp[0].right, temp[1]+1))
            for i in curr :
                d[i] += sorted(curr[i])
        return [d[i] for i in range(start, end+1)]

