class Solution:
    def verticalTraversal(self, root: TreeNode) -> List[List[int]]:
        result = {}
        def traverse(node, width, depth):
            if node is None:
                return
            # (depth, val) order so that later we can sort by depth and if same depth then sort
            # by val in default sorted(), else we'll have to pass key=lambda x: (x[1], x[0])
            # if it was val first i.e (val, depth)
            try:
                result[width].append((depth, node.val))
            except KeyError:
			    # Apparently using normal dict with try catch is faster than default dict
				# as well as dict.get(dist, []) way
                result[width] = [(depth, node.val)]
            traverse(node.left, width-1, depth+1)
            traverse(node.right, width+1, depth+1)
        traverse(root, 0, 0)
        # This is pretty fast even with sorting as these are really small lists to sort
        return [list(map(lambda x: x[1], sorted(v)))
                for _,v in sorted(result.items())]

