    def verticalTraversal(self, root: Optional[TreeNode]) -> List[List[int]]:       

        ans = []

        def dfs(node, level, width):
            if not node :
                return
            nonlocal ans
            ans.append((width, node.val, level))
            dfs(node.left, level + 1, width - 1)
            dfs(node.right, level + 1, width + 1)

        dfs(root, 0, 0)

		# sort by width -> level (tie-break) -> value (tie-break)
        ans.sort(key = lambda x :(x[0], x[2], x[1]))

        res = [[ans[0][1]]]

        last = ans[0][0]

        for x in ans[1:]:
            if x[0] == last :
                res[-1].append(x[1])
            else:
                res.append([x[1]])

            last = x[0]

        return res

