    def verticalTraversal(self, root: Optional[TreeNode]) -> List[List[int]]:
        lst = [];
        def traversal(node: Optional[TreeNode],row: int,col: int):
            #traversing the left child if it exists
            if node.left:
                traversal(node.left,row+1,col-1);
            #appending the present node after finishing the left most traversal
            lst.append([[row,col],node.val]);
            #traversing the right child if it exists
            if node.right:
                traversal(node.right,row+1,col+1);
        traversal(root,0,0);
        #collecting the distinct column values and sorting
        distinct = [];
        for i in lst:
            if i[0][1] not in distinct:
                distinct.append(i[0][1]);
