        #nodes are sorted according to distinct(column values in ascending)
        lst1 = [[[k[0][0],k[1]] for k in lst if k[0][1] == j] for j in distinct];
        #nodes are sorted according to row values
        lst2 = [[x[1] for x in y] for y in [sorted(m) for m in lst1]];
        return lst2;

class Solution:
    def verticalTraversal(self, root: Optional[TreeNode]) -> List[List[int]]:
        traversal = defaultdict(list)
        output = []
        queue = deque()
        queue.append((root, 0))

        while queue:
            count = len(queue)
            level = defaultdict(list)

            for _ in range(count):
                node, column = queue.popleft()
                bisect.insort(level[column], node.val)

                if node.left is not None:
                    queue.append((node.left, column - 1))

                if node.right is not None:
                    queue.append((node.right, column + 1))

            for column in level.keys():
                traversal[column] += level[column]

        for i in range(min(traversal), max(traversal) + 1):
            output.append(traversal[i])

        return output

