			if visited is None:
				visited = set()
				visited.add(a)

			if a == b:
				return True

			if a not in graph:
				return False

			for key in graph[a]:

				if key not in visited:

					visited.add(key)

					if FindPath(key, b, visited):
						return True

			return False

		for equation in notequal:
			a = equation[0]
			b = equation[3]
			option = equation[1:3]

			if FindPath(a,b):
				return False

