        good_count = 0
        counter = collections.Counter()

        begin = 0
        for end in range(len(nums)):
            if counter[nums[end]] == 0:
                k -= 1
            counter[nums[end]] += 1

            while k < 0:
                counter[nums[begin]] -= 1
                if counter[nums[begin]] == 0:
                    k += 1

                begin += 1

            good_count += end - begin + 1

        return good_count

