            """Return squareful arrays given prev value and mask."""
            if not mask: return 1 
            ans = 0 
            seen = set()
            for i, x in enumerate(nums): 
                if x not in seen and (mask == (1 << len(nums)) - 1 or mask &amp; (1 << i) and int(sqrt(x+v))**2 == x+v): 
