def bstFromPreorder(self, preorder):
    def insert(root, val):
        if root is None:
            return TreeNode(val)
        if root.val >= val:
            root.left = insert(root.left, val)
        if root.val < val:
            root.right = insert(root.right, val)
        return root
    root = None
    for item in preorder:
        root = insert(root, item)
    return root

