            x,y = queue.popleft()
            A[x][y] = "T"
            if (x,y) in visited: continue
            visited.add((x,y))
            for nx,ny in [[x+1,y],[x-1,y],[x,y+1],[x,y-1]]:
                if 0<=nx<row and 0<=ny<col and A[nx][ny]==1:
                    A[nx][ny] = "T"
                    queue.append((nx,ny))
        return A

    bfs(queue,A)

    count = 0
    for x in range(row):
        for y in range(col):
            if A[x][y] == 1:
                count+=1
