class Solution:
    def numEnclaves(self, grid: List[List[int]]) -> int:
        if not grid:
            return 0
        rows, cols = len(grid), len(grid[0])

        def dfs(r, c, value):
            if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] == 0:
                return
            grid[r][c] = value
            dfs(r - 1, c, value)
            dfs(r + 1, c, value)
            dfs(r, c + 1, value)
            dfs(r, c - 1, value)

        for r in range(rows):
            dfs(r, 0, 0)
            dfs(r, cols - 1, 0)

        for c in range(cols):
            dfs(0, c, 0)
            dfs(rows - 1, c, 0)
        count = 0

        return sum([1 for r in range(rows) for c in range(cols) if grid[r][c] == 1])

class Solution:
    def dfs_util(self,grid: List[List[int]],i:int,j:int,r:int,c:int) -> int:
        # if any land cell touches boundary return -1
        if i<0 or j<0 or i>=r or j>=c:
            return -1
        if grid[i][j]==0:
            return 0
        grid[i][j]=0
        left = self.dfs_util(grid,i,j-1,r,c)
        right = self.dfs_util(grid,i,j+1,r,c)
        top = self.dfs_util(grid,i-1,j,r,c)
        bottom = self.dfs_util(grid,i+1,j,r,c)

        # if any land cell touches boundary return -1
        if (left==-1 or right==-1 or top==-1 or bottom==-1):
            return -1
        return (1+left + right + top + bottom)        

    def numEnclaves(self, grid: List[List[int]]) -> int:
        r = len(grid)
        c = len(grid[0]) if r else 0
        ans=0
        for i in range(r):
            for j in range(c):
                if grid[i][j]==1:
                    gridVal = self.dfs_util(grid,i,j,r,c)
                    # -1 means the island touched boundary thus checking for non -1 values that holds the cell count
                    if gridVal!=-1:
                        ans+=gridVal
        return ans

class Solution(object):
    def numEnclaves(self, mat):
        """
        :type grid: List[List[int]]
        :rtype: int
        """
        def solve(r, c):
            if r not in range(len(mat)):
                return float("inf")
            if c not in range(len(mat[0])):
                return float("inf")
            if mat[r][c] == 0:
                return 0

            mat[r][c] = 0
            return 1 + solve(r+1, c) + solve(r-1, c) + solve(r, c+1) + solve(r, c-1) 
        count = 0
        for r in range(len(mat)):
            for c in range(len(mat[0])):
                if mat[r][c] == 1:
                    res = solve(r, c)
                    if res != float("inf"):
                        count += res
        return count

