class Solution:
    def numEnclaves(self, grid: List[List[int]]) -> int:
        R, C = len(grid), len(grid[0])
        ans = 0


        q = collections.deque([])
        for r in range(R):
            if r == 0 or r == R-1:
                for c in range(C):
                    if grid[r][c] == 1:
                        q.append((r,c))
                        grid[r][c] = 2
            else:
                if grid[r][0] == 1:
                    q.append((r,0))
                    grid[r][0] = 2
                if grid[r][C-1] == 1:
                    q.append((r,C-1))
                    grid[r][C-1] = 2

        while q:
            for _ in range(len(q)):
                r,c = q.popleft()
                for _r,_c in [(r+1,c),(r-1,c),(r,c+1),(r,c-1)]:
                    if 0 <= _r < R and 0 <= _c < C and grid[_r][_c] == 1:
                        grid[_r][_c] = 2
                        q.append((_r,_c))

        for r in range(1, R-1):
            for c in range(1, C-1):
                if grid[r][c] == 1:
                    ans += 1
        return ans

