class Solution:
    def camelMatch(self, queries: List[str], pattern: str) -> List[bool]:
        return [True if self.compare(s, pattern) else False for s in queries]

    def compare(self, s, pattern):
        # two pointers, i for s, j for pattern
        # If s[i] matches pattern[j], increase pattern pointer
        # if does not match and s[i] is in lowercase, continue
        # if does not match and s[i] is in uppercase, return false

        n = len(pattern)
        j = 0

        for i, char in enumerate(s):
            if j < n and s[i] == pattern[j]:
                j += 1
            else:
                if s[i].islower():
                    continue
                elif s[i].isupper():
                    return False

        return j == n

