class Solution:
    def videoStitching(self, clips: List[List[int]], time: int) -> int:
        if (time == 0): return 0
        clips.sort(key=lambda i: (i[0], -i[1]))
        output = [clips[0]]
        start, end = output[-1][0], output[-1][1]

        for currStart, currEnd in clips[1:]:
            if (currStart <= end <= currEnd and end < time):
                # pop the last clip if the second last clip overlaps with current clip and current clip is longer than the last clip
                if (len(output) > 1 and currStart <= output[-2][1]):
                    output.pop()
                start = min(start, currStart)
                end = max(end, currEnd)
                output.append([currStart, currEnd])


        if (start <= 0 and end >= time):
            return len(output)
        else:
            return -1

class Solution:
    def videoStitching(self, clips: List[List[int]], time: int) -> int:
        # first sort the clips
        clips.sort()
        # if start is not 0 we can never cover entire event
        if clips[0][0] != 0 : return -1
        # dictionary (key,value) key = int value = max int we can reach from value in 1 move
        dictionary = {}
        for x,y in clips:
            dictionary[x] = y
        # make a dp list
        dp = [float('inf')]*(time+1)
        dp[0] = 0
        for i in range(1,time+1):
            best = dp[i]
            for j in range(i):
                # can we reach i or above i from j
                if j in dictionary and dictionary[j] >= i:
                    # if yes can we reach in minimum steps so far
                    if dp[j] + 1 < best: best = dp[j] + 1
            if best == float('inf'):return -1
            dp[i] = best
        return dp[-1] if dp[-1] != float('inf') else -1

