    def videoStitching(self, clips: List[List[int]], time: int) -> int:
        # Swipe Line
        clips.sort()
        if clips[0][0] != 0: return -1
        intervals = [(clips[0][0], clips[0][1])]
        for c in clips[1:]:
            l, r = c
            if intervals[-1][1] < l: break
            if intervals[-1][1] < r:
                while intervals and intervals[-1][0] >= l:  intervals.pop()
                if not intervals: intervals.append((l, r))
                elif intervals[-1][1] < r: intervals.append((intervals[-1][1], r))
        ret = 0
        for intv in intervals:
            ret += 1
            if time <= intv[-1]: return ret
        return -1
        # DP
        clips.sort()
        dp = [0] + [sys.maxsize] * time
        clips = sorted(clips)
        for clip in clips:
            s, e = clip[0], clip[1]
            for j in range(s, min(e, time)):
                dp[j+1] = min(dp[j+1], dp[s] + 1)
        return -1 if dp[-1] == sys.maxsize else dp[-1]

class Solution:
    def videoStitching(self, clips: List[List[int]], T: int) -> int:
        from collections import defaultdict
        clip_map = defaultdict(list)
        clips.sort()
        for i, (s_i, e_i) in enumerate(clips):
            for s_j, e_j in clips[:i] + clips[i + 1:]:
                if s_i < s_j <= e_i and e_j > e_i:
                    clip_map[(s_i, e_i)].append((s_j, e_j))

        res = float('inf')
        for c in clips:
            q, path = [], 1
            if c[0] != 0: continue
            if c[1] >= T: return 1
            q = clip_map[tuple(c)]
            while q:
                s, e = q.pop()
                path += 1
                if e >= T:
                    break
                q += clip_map[(s, e)]
            else:
                path = float('inf')
            res = min(res, path)
        return -1 if res == float('inf') else res

