class Solution:
    def isBoomerang(self, points: List[List[int]]) -> bool:

        # get the directional pointer
        pointer = []
        for c1, c0 in zip(points[1], points[0]):
            pointer.append(c1-c0)

        # check whether those are equal
        visited = set([tuple(points[0]), tuple(points[1])])
        if len(visited) < 2:
            return False

        # go through the rest of the points
        boomerang = False
        for point in points[2:]:

            # initialize a factor
            factor = None

            # check whether we already visited this
            if tuple(point) in visited:
                return False
            visited.add(tuple(point))

            # check whether we already found point not on the line
            if boomerang:
                continue

            # check whether all points fit
            for p, dire, start in zip(point, pointer, points[0]):
                # check whether dire is zero, then p also needs
                # to have the same coordinate as the point zero
                if dire == 0:
                    if p != start:
                        boomerang = True
                        break
                elif factor is not None and factor != (p-start)/dire:
                    boomerang = True
                    break
                else:
                    factor = (p-start)/dire
        return boomerang

