    def lastStoneWeightII(self, stones: List[int]) -> int:

        @lru_cache(None)
        def fn(i, v): 
            """Return minimum weight of stones[i:] given existing weight."""
            if i == len(stones): return abs(v)
            return min(fn(i+1, v - stones[i]), fn(i+1, v + stones[i]))

