def divisors(n):
	d, e = [], []
	for i in range(1,1+int(n**.5)):
		if n%i == 0:
			d += [i]
			e += [int(n/i)]
	e.reverse()
	if d[-1] == e[0]: del e[0]
	return(d+e)


