class Solution:
    def maxEqualRowsAfterFlips(self, matrix: List[List[int]]) -> int:
        m, n = len(matrix), len(matrix[0]) # dimensions 
        score = [0]*m

        for j in range(1, n): 
            for i in range(m):
                score[i] *= 2
                if matrix[i][0] != matrix[i][j]: score[i] += 1

        freq = {}
        for x in score: freq[x] = 1 + freq.get(x, 0)
        return max(freq.values())

class Solution:
    def maxEqualRowsAfterFlips(self, matrix: List[List[int]]) -> int:
        def flip(alist):
            olist = []
            for v in alist:
                olist.append(0 if v else 1)

            return tuple(olist)

        complementary_row_dict = {}
        for row in matrix:            
            if not row[0]:
                row = flip(row)
            else:
                row = tuple(row)

            complementary_row_dict[row] = complementary_row_dict.get(row, 0) + 1

        return max(complementary_row_dict.values())

