        cands = set()
        def dfs(node, s):
            if node.left is None and node.right is None:
                if (s + node.val) < limit:
                    return True
                else:
                    return False
            else:
                if node.left:
                    left = dfs(node.left, s + node.val)
                    if left:
                        node.left = None
                else:
                    left = True
                if node.right:
                    right = dfs(node.right, s + node.val)
                    if right:
                        node.right = None
                else:
