class Solution:
    def braceExpansionII(self, expression: str) -> List[str]:
        stack,res,cur=[],[],[]
        for i in range(len(expression)):
            v=expression[i]
            if v.isalpha():
                cur=[c+v for c in cur or ['']]
            elif v=='{':
                stack.append(res)
                stack.append(cur)
                res,cur=[],[]
            elif v=='}':
                pre=stack.pop()
                preRes=stack.pop()
                cur=[p+c for c in res+cur for p in pre or ['']]
                res=preRes
            elif v==',':
                res+=cur
                cur=[]
        return sorted(set(res+cur))

class Solution:
    def braceExpansionII(self, expression: str) -> List[str]:
        mp, stack = {}, []
        for i, x in enumerate(expression): 
            if x == "{": stack.append(i)
            elif x == "}": mp[stack.pop()] = i 

        def fn(lo, hi): 
            """Return expanded outcome of expression[lo:hi]."""
            ans = [[""]]
            if lo+1 < hi: 
                i = lo
                while i < hi: 
                    if expression[i] == ",": ans.append([""])
                    else: 
                        if expression[i] == "{": 
                            y = fn(i+1, mp[i])
                            i = mp[i]
                        else: y = expression[i]
                        ans.append([xx+yy for xx in ans.pop() for yy in y])
                    i += 1
            return sorted({xx for x in ans for xx in x}) 

        return fn(0, len(expression))

class Solution:
    def braceExpansionII(self, s: str) -> List[str]:
        def getWord():
            nonlocal i
            word = ""
            while i < len(s) and s[i].isalpha():
                word += s[i]
                i += 1
            return word


        def dfs():
            nonlocal i
            res = set()
            if s[i] == '{':
                i += 1
                res.update(dfs())
                while i < len(s) and s[i] == ',':
                    i += 1
                    res.update(dfs())
                i += 1
            elif s[i].isalpha():
                res.add(getWord())

            while i < len(s) and (s[i] == '{' or s[i].isalpha()): 
                res = {w + a for a in dfs() for w in res}
            return res

        i = 0
        return sorted(dfs())

