        k = []


        while True:
            if label ==1:
                k.append(1)

                break


            for i in range(21):
                if 2**i <= label and 2**(i+1) > label:
                    k.append(label)
                    start = 2**(i-1)
                    end = (2**i) -1


                    label = label//2

                    label = end - (label - start)


        return k[::-1]

