    def minHeightShelves(self, books, shelfWidth):
        @lru_cache(None)
        def dp(idx,cur_height,cur_width):
            if cur_width < 0:
                return float("inf")

            if idx == len(books):
                return cur_height

            thickness, height = books[idx]
            same_shelf = dp(idx+1,max(height,cur_height),cur_width-thickness)
