class Solution:
    def parseBoolExpr(self, expression: str) -> bool:
        logics = []
        stack = []

        def cal(tmp, top, op):
            if op == '!':
                tmp = 't' if tmp == 'f' else 'f'
            elif op == '&amp;':
                tmp = 't' if (tmp == 't' and top == 't') else 'f'
            elif op == '|':
