                    top = stack.pop()
                    # print(tmp, top, op)
                    if op == '!' and top == '(': tmp = cal(tmp, tmp, op)
                    if top == '(': break
                    tmp = cal(tmp, top, op)
                stack.append(tmp)
            elif i == ',': continue
            else:
                stack.append(i)
