                    open_count +=1
                if c == ')':
                    current_arg +=c
                    open_count -= 1
                    if open_count == 0:
                        args.append(current_arg)
                        current_arg = ''
            return args

        bool_mp = {'f': False, 't': True}
        if len(expression) == 1:
            return bool_mp[expression]

        if expression[0] == '!':
            return not self.parseBoolExpr(expression[2:-1])

        if expression[0] == '|':
            args = parse_args(expression[2:-1])
            return any(self.parseBoolExpr(arg) for arg in args)

        if expression[0] == '&amp;':
            args = parse_args(expression[2:-1])
            return all(self.parseBoolExpr(arg) for arg in args)

class Solution:
    def parseBoolExpr(self, expression: str) -> bool:     
        # 0b0000 - ' '
        # 0b0100 - '!'
        # 0b1000 - '&amp;'
        # 0b1100 - '|'
        # 0b0010 (2) - if t in expression
        # 0b0001 (1) - if f in expression

        d = { 0b0110:1, 0b0101:2,
               0b1010:2, 0b1001:1, 0b1011:1,
               0b1110:2, 0b1101:1, 0b1111:2,
               0b0010:True, 0b0001:False }        


        levels = [0]
        for x in expression:                             
            if x == ',' or x == "(":
                continue
            elif x == 't':
                levels[-1] |= 2
            elif x == 'f':
                levels[-1] |= 1
            elif x == ')':     
                level = levels.pop()
                levels[-1] |= d[level]
            elif x =='!':
                levels.append(0b0100)
            elif x =='&amp;':
                levels.append(0b1000)
            elif x =='|':
                levels.append(0b1100)                            

        return d[levels[0]]

