        for sr in range(n):
            for sc in range(m):
                er,ec = sr,sc
                while True:
                    if grid[sr][ec] == 0 or grid[er][sc] == 0: break
                    flag = True
                    for i in range(sr,er+1):
                        if grid[i][ec] == 0:
