class Solution:
    def largest1BorderedSquare(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0]) # dimensions 

        hori = deepcopy(grid)
        vert = deepcopy(grid)
        for i in range(m):
            for j in range(n): 
                if grid[i][j]: 
                    if j: hori[i][j] += hori[i][j-1] # horizontal precipitation
                    if i: vert[i][j] += vert[i-1][j] # vertical precipitation 

        ans = 0
        for i in reversed(range(m)):
            for j in reversed(range(n)): 
                val = min(hori[i][j], vert[i][j])
                while val > ans: 
                    if vert[i][j-val+1] >= val and hori[i-val+1][j] >= val: 
                        ans = val 
                    val -= 1
        return ans*ans

class Solution:
    def stoneGameII(self, piles: List[int]) -> int:
        suffix_sum = self._suffix_sum(piles)

        @lru_cache(None)
        def dfs(pile: int, M: int, turn: bool) -> Tuple[int, int]:
            # turn: true - alex, false - lee
            sum_alex, sum_lee = suffix_sum[pile], suffix_sum[pile]

            for next_pile in range(pile + 1, min(pile + 2 * M + 1, len(piles) + 1)):
                sum_alex_next, sum_lee_next = dfs(
                    next_pile, max(M, next_pile - pile), not turn
                )
                range_sum = suffix_sum[pile] - suffix_sum[next_pile]

                if turn:
                    if sum_lee_next < sum_lee:
                        sum_alex = sum_alex_next + range_sum
                        sum_lee = sum_lee_next
                else:
                    if sum_alex_next < sum_alex:
                        sum_alex = sum_alex_next
                        sum_lee = sum_lee_next + range_sum

            return sum_alex, sum_lee

        return dfs(0, 1, True)[0]

class Solution:
    def stoneGameII(self, piles: List[int]) -> int:
        suffix_sum = self._suffix_sum(piles)

        @lru_cache(None)
        def dfs(pile: int, M: int) -> int:
            sum_next_player = suffix_sum[pile]

            for next_pile in range(pile + 1, min(pile + 2 * M + 1, len(piles) + 1)):
                sum_next_player = min(
                    sum_next_player, dfs(next_pile, max(M, next_pile - pile))
                )

            sum_player = suffix_sum[pile] - sum_next_player

            return sum_player

        return dfs(0, 1)

class Solution:
    def stoneGameII(self, piles: List[int]) -> int:
        suffix_sum = self._suffix_sum(piles)

        dp = [[0] * (len(piles) + 1) for _ in range(len(piles) + 1)]

        for pile in reversed(range(len(piles))):
            for M in reversed(range(len(piles))):
                sum_next_player = suffix_sum[pile]

                for next_pile in range(pile + 1, min(pile + 2 * M + 1, len(piles) + 1)):
                    sum_next_player = min(
                        sum_next_player, dp[next_pile][max(M, next_pile - pile)]
                    )

                sum_player = suffix_sum[pile] - sum_next_player

                dp[pile][M] = sum_player

        return dp[0][1]

class Solution:
    def stoneGameII(self, piles: List[int]) -> int:
        N = len(piles)
        self.dp = {}

        def recursiveStoneGame(start, M):            
            if start >= N:
                return 0

            # take all if possible
            if N - start <= 2*M:
                return sum(piles[start:])

            # memoization
            if (start, M) in self.dp:
                return self.dp[(start, M)]

            my_score = 0
            total_score = sum(piles[start:])
            # the opponent can take [1, 2*M] stones
            for x in range(1, 2*M+1):
                # get opponent's score
                opponent_score = recursiveStoneGame(start+x, max(x, M))
                # maintains max my_score
                my_score = max(my_score, total_score - opponent_score)

            self.dp[(start, M)] = my_score

            return my_score


        return recursiveStoneGame(0, 1)

class Solution:
    def stoneGameII(self, piles: List[int]) -> int:
        if not piles:
            return 0

        n = len(piles)
        postSum = [0] * n
        postSum[n - 1] = piles[n - 1]
        for i in range(n - 2, -1, -1):
            postSum[i] = postSum[i + 1] + piles[i]

        return self.helper(0, 1, postSum, {})

    def helper(self, start, M, postSum, cache):
        if (start, M) in cache:
            return cache[(start, M)]

        n = len(postSum)
        if start >= n:
            return 0
        if n - start <= 2 * M:
            return postSum[start]

        minNext = float('inf')
        for x in range(1, 2 * M + 1):
            minNext = min(minNext, self.helper(start + x, max(M, x), postSum, cache))
        res = postSum[start] - minNext
        cache[(start, M)] = res
        return res

class Solution:
    def stoneGameII(self, piles: List[int]) -> int:
        if not piles:
            return 0

        n = len(piles)
        postSum = [0] * n
        postSum[n - 1] = piles[n - 1]
        for i in range(n - 2, -1, -1):
            postSum[i] = postSum[i + 1] + piles[i]

        f = [[0 for _ in range(n)] for _ in range(n)]
        for i in range(n - 1, -1, -1):
            for m in range(1, n):
                if n - i <= 2 * m:
                    f[i][m] = postSum[i]
                    continue

                minNext = float('inf')
                for x in range(1, 2 * m + 1):
                    minNext = min(minNext, f[i + x][max(m, x)])
                f[i][m] = postSum[i] - minNext

        return f[0][1]

class Solution:
    def stoneGameII(self, piles: List[int]) -> int:
        @functools.cache
        def dp(l, m, i_am_alice): # lets return alice count
            if l == len(piles): return 0

            left = []
            taking_now = 0

            for x in range(2*m):
                if l+x == len(piles): break

                if i_am_alice:
                    taking_now += piles[l+x]
                taking_later = dp(l+x+1, max(m,x+1), not i_am_alice)

                left.append(taking_now + taking_later)

            if i_am_alice: # i want to maximize alice
                return max(left)

            else: # i am bob, want to minimize alice
                return min(left)

        return dp(0,1,True)

class Solution:
    def longestCommonSubsequence(self, text1: str, text2: str) -> int:

        dp = []

        # Fill the matrix
        for _ in range(len(text1)+1):
            row = []
            for _ in range(len(text2)+1):
                row.append(0)

            dp.append(row)


        longest_length = 0

        # Start looping throught the text1 and text2
        for i in range(1, len(text1)+1):
            for j in range(1, len(text2)+1):

                # If characters match
				# fill the current cell by adding one to the diagonal value
                if text1[i-1] == text2[j-1]:
                    dp[i][j] = dp[i-1][j-1] + 1
                else:
                    # If characters do not match
					# Fill the cell with max value of previous row and column
                    dp[i][j] = max(dp[i-1][j], dp[i][j-1])

                # Keep track of the MAXIMUM value in the matrix
                longest_length = max(longest_length, dp[i][j])

        return longest_length

class Solution:
    def longestCommonSubsequence(self, text1: str, text2: str) -> int:
        n = len(text1)
        m = len(text2)
        dp = [[-1 for i in range(m+1)] for i in range(n+1)]

        for j in range(m+1):
            dp[0][j] = 0

        for i in range(n+1):
            dp[i][0] = 0    

        for ind1 in range(1,n+1):
            for ind2 in range(1,m+1):
                if(text1[ind1-1] == text2[ind2-1]):
                    dp[ind1][ind2] = 1 + dp[ind1-1][ind2-1]
                else:
                    dp[ind1][ind2] = max(dp[ind1-1][ind2],dp[ind1][ind2-1])
        return dp[n][m]

class Solution:
    def longestCommonSubsequence(self, text1: str, text2: str) -> int:
        n = len(text1)
        m = len(text2)

        prev = [0 for i in range(m+1)]
        cur = [0 for i in range(m+1)]

        for ind1 in range(1,n+1):
            for ind2 in range(1,m+1):
                if(text1[ind1-1] == text2[ind2-1]):
                    cur[ind2] = 1 + prev[ind2-1]
                else:
                    cur[ind2] = max(prev[ind2],cur[ind2-1])
            prev = [x for x in cur]
        return prev[m]

class Solution:
    def longestCommonSubsequence(self, text1: str, text2: str) -> int:

        # padding one space for empty string representation
        text1 = ' ' + text1
        text2 = ' ' + text2

        w, h = len(text1), len(text2)

        dp_table = [ [ 0 for x in range(w) ] for y in range(h) ]

        # update dynamic programming table with optimal substructure
        for y in range(1, h):
            for x in range(1, w):

                if text1[x] == text2[y]:
                    # with the same character
                    # extend the length of common subsequence
                    dp_table[y][x] = dp_table[y-1][x-1] + 1

                else:
                    # with different characters
                    # choose the optimal subsequence
                    dp_table[y][x] = max( dp_table[y-1][x], dp_table[y][x-1] )

        return dp_table[-1][-1]

class Solution:
    def longestCommonSubsequence(self, text1: str, text2: str) -> int:

        @cache
        def dp(i, j):

            if i == -1 or j == -1:
                # Any string compare to empty string has no common sequence
                return 0

            elif text1[i] == text2[j]:
                # Current character is the same
                return dp(i-1, j-1) + 1

            else:
                # Current characters are different
                return max( dp(i-1, j), dp(i, j-1) )

        # -------------------------------------------------
        return dp( len(text1)-1, len(text2)-1 )

class Solution:
    def longestCommonSubsequence(self, text1: str, text2: str) -> int:
        m, n = len(text1), len(text2)
        dp = [[0]*(n+1) for _ in range(m+1)]
        for i in range(m-1, -1, -1): 
            for j in range(n-1, -1, -1): 
                if text1[i] == text2[j]: dp[i][j] = 1 + dp[i+1][j+1]
                else: dp[i][j] = max(dp[i+1][j], dp[i][j+1])
        return dp[0][0]

