        m, n = len(text1), len(text2)
        ans = [0]*(n+1)

        for i in range(m): 
            tmp = ans.copy()
            for j in range(n): 
                if text1[i] == text2[j]: ans[j+1] = 1 + tmp[j]
                else: ans[j+1] = max(tmp[j+1], ans[j])

        return ans[-1]

class Solution:
    def longestPalindromeSubseq(self, s: str) -> int:

        @lru_cache(None)
        def lcs(i, j): 
            """Return longest common subsequence of text1[i:] and text2[j:]."""
            if i == len(s) or j == len(s): return 0 
            if s[i] == s[~j]: return 1 + lcs(i+1, j+1)
            else: return max(lcs(i+1, j), lcs(i, j+1))

        return lcs(0, 0)

class Solution:
    def longestCommonSubsequence(self, text1: str, text2: str) -> int:
        m, n = len(text1), len(text2)
        dp = [0]*(n+1)
        for i in reversed(range(m)):
            prev = curr = 0
            for j in reversed(range(n)):
                curr = dp[j]
                if text1[i] == text2[j]: dp[j] = 1 + prev
                else: dp[j] = max(dp[j], dp[j+1])
                prev = curr 
        return dp[0]

