class Solution:
    def movesToMakeZigzag(self, nums: List[int]) -> int:
        def greedy(nums, small_first=True):
            if n <= 1: return 0
            ans = 0
            for i in range(n-1):
                if small_first and nums[i] >= nums[i+1]:
                    ans += nums[i] - (nums[i+1]-1)
                    nums[i] = nums[i+1] - 1
                elif not small_first and nums[i] <= nums[i+1]:
                    ans += nums[i+1] - (nums[i]-1)
                    nums[i+1] = nums[i] - 1
                small_first = not small_first
            return ans    
        n = len(nums)
        return min(greedy(nums[:], True), greedy(nums[:], False))

class Solution:
    def solve(self,arr,n,x):
        idx = 1
        ans = 0
        while idx < n:
            if idx == 0: idx += 1
            if idx % 2 == x:
                if arr[idx-1] >= arr[idx]:
                    ans += arr[idx-1] - arr[idx] + 1
                    arr[idx-1] = arr[idx] - 1
                    idx = idx-1
                else:
                    idx = idx+1
            else:
                if arr[idx-1] <= arr[idx]:
                    ans += arr[idx] - arr[idx - 1] + 1
                    arr[idx] = arr[idx-1] - 1
                idx += 1               
        return ans

    def movesToMakeZigzag(self, nums: List[int]) -> int:
        ans1 = self.solve([x for x in nums],len(nums),0)
        ans2 = self.solve([x for x in nums],len(nums),1)
        return min(ans1,ans2)

class Solution:
    def movesToMakeZigzag(self, nums: List[int]) -> int:
        moves_even, moves_odd = 0, 0
        ldec_even, ldec_odd = 0, 0

        if len(nums) > 1:
            moves_even += max(0, nums[1] - nums[0] + 1)
            ldec_even = moves_even

        for i, num in enumerate(nums[1:], 1):
            if i % 2 == 0:
                # even
                moves_even += max(0, nums[i-1] - num - ldec_even + 1)
                if i+1 < len(nums):
                    ldec_even = max(0, nums[i+1] - num + 1) 
                    moves_even += ldec_even
            else:
                # odd
                moves_odd += max(0, nums[i-1] - num - ldec_odd + 1)
                if i+1 < len(nums):
                    ldec_odd = max(0, nums[i+1] - num + 1) 
                    moves_odd += ldec_odd

        return min(moves_even, moves_odd)

