class Solution:
    def btreeGameWinningMove(self, root: TreeNode, n: int, x: int) -> bool:
        l = r = 0
        def count(node):
            nonlocal l, r
            total = 0
            if node: 
                l_count, r_count = count(node.left), count(node.right)
                if node.val == x: 
                    l, r = l_count, r_count
                total += l_count + r_count + 1
            return total
        s = count(root) 
        p = s-l-r-1 
        return l+r < p or l+p < r or r+p < l

class Solution:
    def btreeGameWinningMove(self, root: TreeNode, n: int, x: int) -> bool:

        def fn(node): 
            """Return size of subtree rooted at node."""
            if not node: return 0 
            left, right = fn(node.left), fn(node.right)
            if node.val == x: 
                cnt[0], cnt[1] = left, right
            return 1 + left + right

        cnt = [0, 0]
        fn(root)
        return max(max(cnt), n-1-sum(cnt)) > n//2

class Solution:
    def longestDecomposition(self, text: str) -> int:
        n=len(text)-1
        dp=[[-1 for i in range(n+1)] for j in range(n+1)]
        def dfs(start,end):
            if start>end:
                return 0
            if dp[start][end]!=-1:
                return dp[start][end]
            best=1
            l,r=start,end
            mid=(r+l)//2
            while r>mid:
                chunk=end-r+1
                if text[l:l+chunk]==text[r:end+1]:
                    val=dfs(l+chunk,r-1)+2
                    best=max(best,val)
                r-=1
            dp[start][end]=best
            return dp[start][end]
        return dfs(0,n)

class Solution:
    def longestDecomposition(self, text: str) -> int:
        i, j = 0, len(text)-1
        count = 0
        left = ''
        right = ''
        while i <= j:
            left += text[i]
            right = text[j] + right
            if i == j:
                break
            else:
                if left == right:
                    left = ''
                    right = ''
                    count += 2
            i += 1
            j -= 1
        if left != '' and right != '':
            count += 1
        return count

