class Solution:
    def dayOfYear(self, date: str) -> int:
        year, mon, day = map(int, date.split('-'))
        days = 0
        def is_leap(year):
            if year % 4 == 0 or (year % 100 == 0 and year % 400 == 0):
                return True
            return False
        leap = is_leap(year)
        for i in range(1,mon):
            if i in [1,3,5,7,8,10]:
                days += 31
            elif i in [4,6,9,11]:
                days += 30
            else:
                days += 28
        days += day
        if leap:
            if mon > 2:
                return days + 1
        return days

class Solution:
