class Solution:
    def numRollsToTarget(self, d: int, f: int, target: int) -> int:
        if d*f < target: return 0        # Handle special case, it speed things up, but not necessary
        elif d*f == target: return 1     # Handle special case, it speed things up, but not necessary
        mod = int(10**9 + 7)
        dp = [[0] * (target+1) for _ in range(d+1)] 
        for j in range(1, min(f+1, target+1)): dp[1][j] = 1
        for i in range(2, d+1):
            for j in range(1, target+1):
                for k in range(1, f+1):
                    if j - k >= 0: dp[i][j] += dp[i-1][j-k]
                dp[i][j] %= mod        
        return dp[-1][-1]

class Solution:
    def numRollsToTarget(self, n: int, k: int, target: int) -> int:
        modulo = 10**9+7

        @lru_cache(None)
        def dp(dice_left: int, target_left: int) -> int:
            if dice_left == 0:
                if target_left == 0:
                    return 1
                return 0
            res = 0
            for i in range(1, k+1):
                res += dp(dice_left-1, target_left-i)
                res %= modulo
            return res % modulo

        return dp(n, target)

class Solution:
    def numRollsToTarget(self, n: int, k: int, target: int) -> int:
        modulo = 10**9+7
        dp = [[0]*(target+1) for _ in range(n+1)]
        dp[0][0] = 1

        for dice_left in range(1, n+1):
            for target_left in range(1, target+1):
                for i in range(1, min(k, target_left)+1):
                    dp[dice_left][target_left] += dp[dice_left-1][target_left-i]
                dp[dice_left][target_left] %= modulo
        return dp[n][target]

