                return 0
            if (i,tr) in dic:
                return dic[(i,tr)]
            sm=0
            for j in range(1,k+1):
                # print(i+1,tr-j)
                sm+=func(i+1,n,k,tr-j,dic)
            dic[(i,tr)]=sm
            return sm
