class Solution:

    def numRollsToTarget(self, n: int, k: int, target: int) -> int:

        @lru_cache(maxsize=None)
        def recur(n, t):
            if t <= 0 or t > n*k:
                return 0

            if n==1:
                if t <=k:
                    return 1
                else:
                    return 0
            count = 0
            for i in range(1, k+1):
                count+=recur(n-1, t-i)

            return count

        return recur(n,target) % ((10**9) + 7)

