class Solution:
    def maxRepOpt1(self, text: str) -> int:
        first_occurence,last_occurence = {},{}
        ans,prev,count = 1,0,0
        n = len(text)

        for i in range(n):
            if text[i] not in first_occurence: first_occurence[text[i]] = i
            last_occurence[text[i]] = i

        for i in range(n+1):
            if i < n and text[i] == text[prev]:
                count += 1
            else:
                if first_occurence[text[prev]] < prev or last_occurence[text[prev]] > i : count += 1
                ans = max(ans,count)
                count = 1
                prev = i

        def someWork(item,before,after):
            count = 0
            while before >= 0 and text[before] == item: 
                count += 1
                before -= 1
            while after < n and text[after] == item:
                count += 1
                after += 1
            if first_occurence[item] <= before or last_occurence[item] >= after:count+=1
            return count

        for i in range(1,n-1):
            ans = max(ans,someWork(text[i+1],i-1,i+1))
        return ans

class Solution:
    def maxRepOpt1(self, text: str) -> int:
        freq = {}
        for ch in text:
            freq[ch] = freq.get(ch, 0)+1

        n=len(text)
        i=0
        distinct = 0
        cur={}
        def include(ind):
            nonlocal distinct
            ch = text[ind]
            cur[ch] = cur.get(ch,0)+1
            if cur[ch] == 1:
                distinct+=1 
        def exclude(ind):
            nonlocal distinct
            ch = text[ind]
            cur[ch]-=1
            if cur[ch]==0:
                cur.pop(ch)
                distinct-=1
        for j in range(n):
            #expansion
            include(j)

            if distinct >= 3:
                #movement
                exclude(i)
                i+=1
                continue
            if distinct == 2:
                keys = list(cur.keys())
                a,b = keys[0], keys[1]
                if cur[a] == 1 or cur[b] == 1:
                    if cur[a] == 1:
                        if freq[b] == cur[b]:
                            exclude(i)
                            i+=1
                    else:
                        if freq[a] == cur[a]:
                            exclude(i)
                            i+=1
                else:
                    exclude(i)
                    i+=1
        return n-i

class Solution:
    def maxRepOpt1(self, text: str) -> int:
        lst = [(key, len(list(seq))) for key, seq in groupby(text)]
        len_lst_2 = len(lst) - 2
        cnt = Counter(text)
        max_len = 0
        for i, (key, n) in enumerate(lst):
            max_len = max(max_len, n)
            if n < cnt[key]:
                max_len = max(max_len, n + 1)
            if i < len_lst_2 and lst[i + 1][1] == 1 and lst[i + 2][0] == key:
                if (len_both := n + lst[i + 2][1]) < cnt[key]:
                    max_len = max(max_len, len_both + 1)
                else:
                    max_len = max(max_len, len_both)
        return max_len

