        levels = []
        sums = float('-inf')
        res = 0

        def levelorder(node, level):
            if level >= len(levels):
                levels.append([])

            if node:
                levels[level].append(node.val)
                if node.left:
                    levelorder(node.left, level + 1)

                if node.right:
                    levelorder(node.right, level + 1)

        levelorder(root, 0)

        for i in range(len(levels)):
