                sums = sum(levels[i])
                res = i + 1

        return res

class Solution:
    def maxLevelSum(self, root: Optional[TreeNode]) -> int:
        q = collections.deque()
        tracker = [float('-inf'),0]
        q.append(root)
        level = 1

        while q:
            levelSum = 0
            for _ in range(len(q)):
                node = q.popleft()
                levelSum += node.val
                if node.left:
                    q.append(node.left)
                if node.right:
                    q.append(node.right)
            if levelSum > tracker[0]:
                tracker[0] = levelSum
                tracker[1] = level
            level += 1

        return tracker[1]

class Solution:
    def maxLevelSum(self, root: Optional[TreeNode]) -> int:
        def getHeight(root):
            if root.left==None and root.right==None:
                return 0
            left=0
            if root.left!=None:
                left = getHeight(root.left)
            right=0
            if root.right!=None:
                right=getHeight(root.right)
            return (max(left, right) + 1)

        def calculateLevelSum(root, level, sum):
            if root == None:
                return sum
            sum[level]+=root.val
            calculateLevelSum(root.left, level+1, sum)
            calculateLevelSum(root.right, level+1, sum)
            return sum

        levels=getHeight(root) + 1
        sum=[0]*levels
        sum=calculateLevelSum(root, 0, sum)
        return sum.index(max(sum))+1

