        h = defaultdict(int)
        while stack:
            node, depth = stack.pop()
            if node:
                h[depth] += node.val
                stack.append((node.left, 1+depth))
                stack.append((node.right, 1+depth))
        minv = float('-inf')
        res = -1

        for key in h:
            v = h[key]
