class Solution:
    def maxDistance(self, grid: List[List[int]]) -> int:
        dist = [[math.inf] * len(grid[0]) for i in range(0, len(grid))]
        land = 0

        for i in range(0, len(grid)):
            for j in range(0, len(grid[0])):
                if(grid[i][j] == 1):
                    dist[i][j] = 0
                    land += 1
                else:
                    if(i > 0):
                        dist[i][j] = min(dist[i-1][j] + 1, dist[i][j])
                    if(j > 0):
                        dist[i][j] = min(dist[i][j-1] + 1, dist[i][j])
                    if(i > 0 and j > 0):
                        dist[i][j] = min(dist[i-1][j-1] + 2, dist[i][j])

        if(len(grid) * len(grid[0]) == land or land == 0):
            return -1

        for i in range(len(grid)-1, -1, -1):
            for j in range(len(grid[0]) -1 , -1, -1):
                if(i < len(grid) - 1):
                    dist[i][j] = min(dist[i+1][j] + 1, dist[i][j])
                if(j < len(grid[0]) - 1):
                    dist[i][j] = min(dist[i][j+1] + 1, dist[i][j])
                if(i < len(grid) - 1 and j < len(grid[0]) - 1):
                    dist[i][j] = min(dist[i+1][j+1] + 2, dist[i][j])

        ans = 0
        for i in range(len(grid)-1, -1, -1):
            for j in range(len(grid[0])-1, -1, -1):
                ans = max(ans, dist[i][j])
        return ans

class Solution:
    def lastSubstring(self, s: str) -> str:
        n = len(s)
        cmax = max(s)
        indexes = [ i for i,c in enumerate(s) if c == cmax ]
        gap = 1
        while len(indexes) > 1:
            new_indexes = []
            cmax = max(s[i+gap] for i in indexes if i+gap < n)
            for i,st in enumerate(indexes):
                if i > 0 and indexes[i-1] + gap == st: continue
                if st + gap < n and s[st + gap] == cmax:new_indexes.append(st)
            indexes = new_indexes
            gap += 1
        return s[indexes[0]:]

