    def numSmallerByFrequency(self, queries: List[str], words: List[str]) -> List[int]:
        def freq(word):
            l = len(word)
            ans,minn = 1,word[0]
            for i in range(1,l):
                if word[i] == minn: ans += 1
                elif word[i] < minn : 
                    minn = word[i]
                    ans = 1
            return ans

        n = len(words)
        m = len(queries)
        words_fs = []
        for i,word in enumerate(words):
            words_fs.append(freq(word))
        words_fs.sort()

        def binarysearch(x):
            low ,high = 0,n-1
            while low <= high:
                mid = (low+high)//2
                if words_fs[mid] == x:
                    low = mid + 1
                elif words_fs[mid] < x:
                    low = mid + 1
                else:
                    high = mid - 1
            return high

        ans = [0]*m
        for i,word in enumerate(queries):
            fq = freq(word)
            idx = binarysearch(fq)
            ans[i] = n - idx - 1
        return ans

