        len_s = len(s)
        freq = [defaultdict(int)] * len_s
        freq[0][s[0]] += 1
        for i in range(1, len_s):
            freq[i] = freq[i - 1].copy()
            freq[i][s[i]] += 1
        ans = [True] * len(queries)
        for i, (left, right, k) in enumerate(queries):
            left1 = left - 1
            n_odd = sum((n - (freq[left1][c] if left1 > -1 else 0)) % 2
                        for c, n in freq[right].items())
            ans[i] = n_odd - 2 * k <= 1
        return ans

class Solution:
    def canMakePaliQueries(self, s: str, queries: List[List[int]]) -> List[bool]:
        runningCount = [[0]*26]
        countSnapshot = [0]*26
        a = ord("a")
        for c in s:
            countSnapshot[ord(c)-a] += 1
            runningCount.append([*countSnapshot]) # the * is necessary to deep copy the list

        for left,right,k in queries:
            if k>=13:
                yield True
                continue
            odds = 0
            for i in range(26):
                odds += (runningCount[right+1][i] - runningCount[left][i])%2
            yield k>=odds//2

class Solution:
    def mask(self, word: str) -> int:
        result = 0
        for ch in word:
            result |= 1 << (ord(ch)-ord('a'))
        return result

    def findNumOfValidWords(self, words: List[str], puzzles: List[str]) -> List[int]:
        word_count = Counter(self.mask(word) for word in words)
        result = []
        for puzzle in puzzles:
            original_mask, first = self.mask(puzzle[1:]), self.mask(puzzle[0])
            curr_mask, count = original_mask, word_count[first]
            while curr_mask:
                count += word_count[curr_mask|first]
                curr_mask = (curr_mask-1)&amp;original_mask
            result.append(count)
        return result

class Solution:
    def gen_combinations(self, word):
        if not word:
            yield 0
        else:
            c = word.pop()
            for v in self.gen_combinations(word):
                yield v
                yield v | (1 << (ord(c) - ord('a')))

    def findNumOfValidWords(self, words: List[str], puzzles: List[str]) -> List[int]:
        table = defaultdict(Counter)
        for w in words:
            chars = set(list(w)) 
            if len(chars) > 7:
                continue
            h = reduce(operator.or_, [1 << (ord(c) - ord('a')) for c in chars], 0)
            for c in chars:
                table[c][h] += 1
        for i, p in enumerate(puzzles):
            puzzles[i] = sum(table[p[0]][h] for h in self.gen_combinations(list(p)))
        return puzzles

