        for word in words: 
            mask = 0
            for c in word: mask |= 1 << (ord(c) - 97)
            freq[mask] += 1

        ans = []
        for puzzle in puzzles: 
            mask = val = 0 
            for c in puzzle: mask |= 1 << (ord(c) - 97)
            mask0 = mask # loop through sub-masks
            while mask: 
                if mask &amp; (1 << ord(puzzle[0])-97): val += freq[mask]
                mask = mask0 &amp; (mask - 1)
            ans.append(val)
        return ans

