    def distanceBetweenBusStops(self, distance: List[int], start: int, destination: int) -> int:
        l = len(distance)
        temp =  start
        if start == destination:
            return 0
        clock_wise = 0
        while start != destination:
            clock_wise += distance[start]
            start = (start + 1) % l
        anti = 0
        start = temp
        while start != destination:
            anti += distance[(start - 1) % l ]
            start = (start - 1) % l 
        return min(clock_wise, anti)

