class Solution:
    def dayOfTheWeek(self, day: int, month: int, year: int) -> str:

        d = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"]

        if month == 1:
            year -= 1
            month  = 11
        elif month == 2:
            year -= 1
            month = 12
        else:
            month -= 2

        D, C = int(str(year)[2:]), int(str(year)[:2])

        r = day + ((13 * month - 1) // 5) + D + (D // 4) + (C // 4) - (2 * C)
        return d[int(r % 7)]

