            px = find(x)
            py = find(y)
            if px != py:
                p[py] = px

        # End of Union Find Data Structure

        # Grouping
        for x, y in pairs:
            union(x, y)

        dic = defaultdict(list)
        for idx, el in enumerate(p):
            dic[find(el)].append(idx)

        # eg. pairs = [[0,3],[1,2]], dic = {0: [0, 3], 1: [1, 2]}

