class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        cur = self.root
        for i in range(1, len(word)):
            c = word[i]
            if c not in cur.children:
                cur.children[c] = TrieNode(c)
            elif cur.children[c].is_end:
                return False
            cur = cur.children[c]
        cur.is_end = True
        return True

