        @lru_cache(None)
        def helper(i):
            if i == N: return 0
            j = i + 1
            while j < N and jobs[i][1] > jobs[j][0]:
                j += 1
            one = jobs[i][2] + helper(j)
            two = helper(i+1)
            return max(one, two)

        return helper(0)

