            else:
                start = mid + 1

        return end



    def jobScheduling(self, startTime: List[int], endTime: List[int], profit: List[int]) -> int:
        n = len(profit)
        jobs = [[endTime[i], startTime[i], profit[i]] for i in range(n)]
        jobs.sort()
        A = [v[0] for v in jobs]

        dp = [0 for _ in range(n)]
        dp[0] = jobs[0][2]

        for i in range(1, n):
            if jobs[i][1] < A[0]:
                dp[i] = max(dp[i-1], jobs[i][2])
                continue

            lower = self.binSearch(A, 0, i-1, jobs[i][1])
            dp[i] = max(dp[i-1], jobs[i][2] + dp[lower])

        return dp[n-1]

