class Solution:
    def circularPermutation(self, n: int, start: int) -> List[int]:
        ans = [start]
        seen = set(ans)

        def fn(i, x): 
            """Return circular permutation with x at i."""
            if i == 2**n: 
                diff = ans[-1] ^ start
                if not diff &amp; (diff-1): return ans 
            for k in range(n): 
                xx = x ^ 1 << k 
                if xx not in seen: 
                    seen.add(xx)
                    ans.append(xx)
                    if tmp := fn(i+1, xx): return tmp 
                    ans.pop()
                    seen.remove(xx)

        return fn(1, start)

