class Solution:
    def minRemoveToMakeValid(self, s: str) -> str:
        stackParan = []
        stackIdx = []
        n = len(s)
        for i in range(n):
            if s[i].islower() == True:
                continue
            else:
			#Checking Valid Paranthesis
                if len(stackParan) == 0 and len(stackIdx) == 0:
                    stackParan.append(s[i])
                    stackIdx.append(i)
                else:
                    if stackParan[-1] == "(" and s[i] == ")":
                        stackParan.pop()
                        stackIdx.pop()
                    elif stackParan[-1] == ")" or stackParan[-1] == "(":
                        stackParan.append(s[i])
                        stackIdx.append(i)

        s = list(s)
        while stackIdx != []:
            s.pop(stackIdx[-1])
            stackIdx.pop()

        return "".join(s)

class Solution:
    def minRemoveToMakeValid(self, s: str) -> str:
        '''
        Keep a stack of indices of front parens "(", pop when you encounter a back paren ")".
        If front stack is empty, add index to back set.
        Add everything in front stack to back set for fast lookup.
        Recompute s, skipping any index that's in the set.
        '''

        front, back = [], set()

        for i, c in enumerate(s):
            if c == '(':
                front.append(i)
            elif c == ')':
                if front:
                    front.pop()
                else:
                    back.add(i)

        for i in front:
            back.add(i)

        return ''.join([c for i, c in enumerate(s) if i not in back])

