    def countServers(self, grid: List[List[int]]) -> int:
        N = len(grid)
        M = len(grid[0])
        # 1. set up two dictionaries. 
		# rows[i] denotes server number on i-th row
        # cols[j] denotes server number on j-th column
        rows = {}
        cols = {}

        for i in range(N):
            for j in range(M):
                if grid[i][j] == 1:
                    try: rows[i] += 1
