class Solution:
    def numWays(self, steps: int, arrLen: int) -> int:
        M = 10 ** 9 + 7
        @lru_cache(None)
        def dfs(pos, steps):
            # if we walk outside the array or use all the steps
            # then return 0
            if pos < 0 or pos > steps or pos > arrLen - 1: return 0
            # if we use all the steps, return 1 only if pos is 0
            if steps == 0: return pos == 0
            return (
                # move to the left
                dfs(pos - 1, steps - 1) +
                # stay at current position
                dfs(pos, steps - 1) +
                # move to the right
                dfs(pos + 1, steps - 1) 
            ) % M
        return dfs(0, steps)

class Solution:
    def numWays(self, steps: int, arrLen: int) -> int:
        MOD = (10**9)+7
        @cache
        def dfs(steps,index):
            if steps == 0 and index == 0:
                return 1

            if steps == 0:
                return 0

            goLeft = 0
            goRight = 0
            goStay = 0

            if index > 0:
                goLeft = dfs(steps-1,index-1)

            if index < arrLen-1:
                goRight = dfs(steps-1,index+1)

            goStay = dfs(steps-1,index)

            return goLeft+goStay+goRight

        return dfs(steps,0) % MOD

class Solution:
	def numWays(self, steps: int, arrLen: int) -> int:
		mod=10**9+7
		to_consider=min(arrLen,steps//2+1)
		dp=[1]+[0]*(to_consider-1)
		for i in range(steps):
			new_dp=[0]*to_consider
			for j in range(to_consider):
				new_dp[j]=(dp[j]+(dp[j+1] if j+1<to_consider else 0)+(dp[j-1] if j-1>=0 else 0))%mod
			dp=new_dp
		return dp[0]

class Solution:
    def numWays(self, steps: int, arrLen: int) -> int:
        n = min(arrLen, steps//2+1) #reachable right end
        ways = [1] + [0]*(n-1)
        for step in range(steps): 
            ways = [sum(ways[max(0,i-1):i+2]) % (10**9+7) for i in range(min(step+2,steps-step,n))]
        return ways[0]

class Solution:
    def tictactoe(self, moves: List[List[int]]) -> str:
        # keep track of the "net score" of each row/col/diagonal
        # player A adds 1 to the "net score" of each row/col/diagonal they play in,
        # player B subtracts 1
        # scores[0], scores[1] and scores[2] are for rows 0, 1 and 2
        # scores[3], scores[4] and scores[5] are for cols 0, 1 and 2
        # scores[6] and scores[7] are for the forward and backward diagonal
        scores = [0] * 8

        for i, (row, col) in enumerate(moves):
            if i % 2 == 0:  # if player A is playing
                x = 1
            else:  # if player B is playing
                x = -1

            scores[row] += x
            scores[col + 3] += x
            if row == col:
                scores[6] += x
            if 2 - row == col:
                scores[7] += x

        for score in scores:
            if score == 3:
                return 'A'
            elif score == -3:
                return 'B'

        return 'Draw' if len(moves) == 9 else 'Pending'

