        return self.__win_row_wise(board, player) or self.__win_column_wise(board, player) or self.__win_diagonal_wise(board, player)

    def __win_row_wise(self, board : List[List[str]], player : str) -> bool:
        n = len(board)
        player_code = self.__get_player_code(player)

        for i in range(n):
            if all([player_code== board[i][j] for j in range(n)]):
                return True
        return False

    def __win_column_wise(self, board : List[List[str]], player : str) -> bool:
        n = len(board)
        player_code = self.__get_player_code(player)

        for j in range(n):
            if all([player_code== board[i][j] for i in range(n)]):
                return True
        return False

    def __win_diagonal_wise(self, board : List[List[str]], player : str) -> bool:
        n = len(board)
        player_code = self.__get_player_code(player)

        if all([player_code== board[i][j] for i in range(n) for j in range(n) if i == j]):
                return True

        if all([player_code== board[i][j] for i in range(n) for j in range(n) if (i+j)==n-1]):
            return True
        return False

