class Solution:
    def palindromePartition(self, S, K):
        N = len(S)
        dp = [[N] * (N + 1) for _ in range(K + 1)]
        dp[0][0] = 0
        for i in range(2 * N - 1):
            c = 0
            l = i // 2
            r = l + (i &amp; 1)
            while 0 <= l and r < N:
                if S[l] != S[r]: c += 1
                for i in range(K):
                    dp[i + 1][r + 1] = min(dp[i + 1][r + 1], dp[i][l] + c)
                l -= 1
                r += 1
        return dp[-1][-1]

class Solution:
    def palindromePartition(self, s: str, k: int) -> int:
        n = len(s)
        def costToMakePalindrome(left,right):
            change = 0
            while left<=right:
                if s[left]!=s[right]:
                    change+=1
                left+=1
                right-=1
            return change
        @cache
        def dp(ind,partition):
            if ind == n:
                if partition == 0:
                    return 0
                else:
                    return math.inf
            if partition == 0:
                return math.inf
            res = math.inf
            for i in range(ind,n-partition+1):
                res = min(res,dp(i+1,partition - 1) + costToMakePalindrome(ind,i))
            return res
        return dp(0,k)

class Solution:
    def palindromePartition(self, s: str, k: int) -> int:

        n = len(s)

        def getChanges(i, j):
            ret = 0
            while i < j:
                if s[i] != s[j]:
                    ret += 1
                i += 1
                j -= 1
            return ret

        cost = [[getChanges(i, j) for j in range(n)] for i in range(n)]

        @cache
        def res(l = 0, r = 0, k = k):
            if l == len(s) and r == len(s) and k == 0:
                return 0
            elif r == len(s) or k <= 0:
                return math.inf
            else:
                return min(cost[l][r] + res(r + 1, r + 1, k - 1), res(l, r +1, k))

        return res()

