class Solution:
    def groupThePeople(self, groupSizes: List[int]) -> List[List[int]]:

        lookup = defaultdict(list)
        result = []

        # Build lookup dictionary key: group size, value: list of ids that are in that group size
        for id, size in enumerate(groupSizes):
            lookup[size].append(id)

        # Check for too many ids for group size and break up into groups of 'key' size 
        for key, value in lookup.items():
            left = 0
            right = key
            while right <= len(value):
               result.append(value[left:right])
               left += key
               right += key

        return result

