class Solution:
    def minFallingPathSum(self, grid: List[List[int]]) -> int:
        n= len(grid)
        dp = [[0 for c in range(n)]for r in range(n)]
        for c in range(n):
            dp[0][c] = grid[0][c]

        for r in range(1,n):
            for c in range(n):
                #find the minimum in the previous row, except that particular column
                if c == 0:
                    dp[r][c] = grid[r][c] + min(dp[r-1][1:])
                elif c == n - 1:
                    dp[r][c] = grid[r][c] + min(dp[r-1][:n-1])
                else:
                    min_left = min(dp[r-1][:c])
                    min_right = min(dp[r-1][c+1:])
                    dp[r][c] = grid[r][c] + min(min_left,min_right)
        return min(dp[-1])

class Solution:
    def minFallingPathSum(self, grid: List[List[int]]) -> int:
        if len(grid) == 1:
            return grid[0][0]

        minVal = 0
        minPos = -1
        prevMin = 0

        for row in grid:
            # Since the maximum path sum would be 99 * 200 = 19800, set initital min values to max + 1
            newMin = 19801
            newMinPos = 0
            newPrevMin = 19801

            for i, val in enumerate(row):
                if i == minPos:
                    val += prevMin
                else:
                    val += minVal

                if val < newMin:
                    newPrevMin = newMin
                    newMin = val
                    newMinPos = i
                elif val < newPrevMin:
                    newPrevMin = val

            minVal = newMin
            minPos = newMinPos
            prevMin = newPrevMin

        return minVal

class Solution:
    def minFallingPathSum(self, arr: List[List[int]]) -> int:
        if not arr or not arr[0]:
            return 0
        m, n = len(arr), len(arr[0])
        if n == 1:
            return arr[0][0] if m == 1 else 0
        dp = arr[0]
        prev = [x for x in dp]
        min1, min2 = self.find_two_smallest(arr[0])
        for i in range(1, m):
            for j in range(n):
                dp[j] = prev[min1] if j != min1 else prev[min2]
                dp[j] += arr[i][j]
            min1, min2 = self.find_two_smallest(dp)
            dp, prev = prev, dp
        return min(prev)

    def find_two_smallest(self, arr):
        n = len(arr)
        min1, min2 = 0, 1
        for i in range(1, n):
            if arr[i] < arr[min1]:
                min1, min2 = i, min1
            elif arr[i] < arr[min2]:
                min2 = i
        return min1, min2

