                    new_r < len(grid) and 
                    new_c >= 0 and
                    new_c < len(grid[0])):
                    if grid[new_r][new_c] == 1 and e > 0 and (new_r,new_c,e-1) not in visited:
                        visited.add((new_r,new_c,e-1))
                        q.append((new_r,new_c,e-1,steps+1))
