class Solution:
    def isPossibleDivide(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        if n%k != 0:
            return False

        d = {}
        for num in nums:
            d[num] = d.get(num, 0) + 1

        while d:
            mn = min(d.keys())
            for i in range(k):
                if (mn+i) in d:
                    if d[(mn+i)] == 1:
                        del d[(mn+i)]
                    else:
                        d[(mn+i)] -= 1
                else:
                    return False

        return True

class Solution:
    def isPossibleDivide(self, nums: List[int], k: int) -> bool:

        def dfs_util(num_counts, val, left):
            if left == 0:
                return True
            if val not in num_counts:
                return False
            else:
                num_counts[val] -= 1
                if num_counts[val] == 0:
                    del(num_counts[val])
            return dfs_util(num_counts, val+1, left-1)

        if (len(nums) % k != 0):
            return False
        rounds = len(nums) // k
        num_counts = collections.Counter(nums)
        for _ in range(rounds):
            start = min(num_counts.keys())
            #print("start: ", start)
            if not dfs_util(num_counts, start, k):
                #print("failing", start, num_counts)
                return False
        return True

class Solution:
    def isPossibleDivide(self, N: List[int], k: int) -> bool:
        L, C = len(N), collections.Counter(N)
        for i in range(L//k):
            m = min(C.keys())
            for j in range(m,m+k):
                if C[j] > 1: C[j] -= 1
                else: del C[j]
        return not (C or L % k)


