class Solution:
    def maxFreq(self, s: str, maxLetters: int, minSize: int, maxSize: int) -> int:
        freq = {}
        temp = {}
        for i in range(len(s)): 
            temp[s[i]] =  1 + temp.get(s[i], 0)
            if i >= minSize: 
                temp[s[i-minSize]] -= 1 
                if temp[s[i-minSize]] == 0: temp.pop(s[i-minSize])

