        friends = [set(lst) for lst in friends]
        row = friends[id]
        previous_friends = {id}
        for _ in range(1, level):
            previous_friends.update(row)
            new_row = set()
            for friend in row:
                new_row.update(friends[friend])
            row = new_row - previous_friends
        videos = defaultdict(int)
