        for _ in range(K-1):
            A = set(sum([F[a] for a in A],[])) - V - A
            V = V.union(A)
        C = collections.Counter(sorted(sum([W[a] for a in A], [])))
        return sorted(C.keys(), key = lambda x: C[x])


