    @cache
    def maxPalinSeq(self, s: str) -> int:
    # input: string
    # output: maximal length of palindrome sequence inside s


        ## Base case:

        # Empty string
        if not s:
            return 0

        # Only one character
        if len(s) == 1:
            return 1

        # Only two characters
        if len(s) == 2:

            if s[0] == s[1]:
                return 2
            else:
                return 1


        ## General cases
        if s[0] == s[-1]:

            # head and tail are with the same character
            return self.maxPalinSeq( s[1:-1] ) + 2

        else:
            # head and tail are different
            return max( self.maxPalinSeq( s[:-1] ), self.maxPalinSeq( s[1:] ) )

