    def matrixBlockSum(self, mat: List[List[int]], k: int) -> List[List[int]]:
        m, n = len(mat), len(mat[0])
        # sum rows
        ans = [r[:] for r in mat]
        for i in range(m):
            ans[i][0] = sum(mat[i][:k+1])
            for j in range(1,n):
                ans[i][j] = ans[i][j-1]
                ans[i][j] -= mat[i][j-k-1] if j>=k+1 else 0
                ans[i][j] += mat[i][j+k] if j<n-k else 0
        # sum cols
        mat = [r[:] for r in ans]
        for j in range(n):
            mat[0][j] = sum(ans[l][j] for l in range(k+1))
            for i in range(1,m):
                mat[i][j] = mat[i-1][j]
                mat[i][j] -= ans[i-k-1][j] if i>=k+1 else 0
                mat[i][j] += ans[i+k][j] if i<m-k else 0
        return mat

