class Solution:
    def makeConnected(self, n: int, connections: List[List[int]]) -> int:
        # if number of connected component - 1 == number of redundant wire
        # use union find

        par = [i for i in range(n)]
        rank = [1 for i in range(n)]

        connected = n
        redundant_wire = 0

        def find(n1):
            p = par[n1]
            while p != par[p]:
                p = par[p]
            return p

        def union(n1, n2):
            p1 = find(n1)
            p2 = find(n2)

            if p1 == p2: # redundant connetion
                return False

            if rank[p1] >= rank[p2]:
                par[p2] = p1
                rank[p1] += rank[p2]
            else:
                par[p1] = p2
                rank[p2] += rank[p1]

            return True

        for connection in connections:
            if union(connection[0], connection[1]):
                connected -= 1
            else:
                redundant_wire += 1
		# if we have more redundant wire, we just need connected - 1 wires
        if connected - 1 <= redundant_wire:
            return connected-1
        return -1

