                dist,node = heappop(minHeap)

                for nei_node,nei_dist in graph[node]:
                    new_dist = dist + nei_dist
                    if new_dist < distance[nei_node]:
                        distance[nei_node] = new_dist
                        heappush(minHeap,(new_dist,nei_node))
            count = 0
            for dist in distance:
                if dist <= distanceThreshold:
                    count += 1

            if count <= best_count:
                best_count = count
                city = src_city

        return city

class Solution:
    def findTheCity(self, n: int, edges: List[List[int]], distanceThreshold: int) -> int:
        graph = {i:[] for i in range(n)}
        for u, v, wt in edges:
            graph[u].append((v, wt))
            graph[v].append((u, wt))

        def dijksta(city):
            dist = [float('inf')] * n
            dist[city] = 0
            heap = []
            heapq.heappush(heap, (0, city))

            while heap:
                dis, node = heapq.heappop(heap)

                for adj in graph[node]:
                    adj_city, adj_dis = adj[0], adj[1]
                    if adj_dis + dist[node] < dist[adj_city]:
                         dist[adj_city] = adj_dis + dist[node]
                         heapq.heappush(heap, (dist[adj_city], adj_city))
            return dist

        count = [0] * n
        res = 0
        for city in range(n):
            distance = dijksta(city)
            count[city] = sum(1 if dis <= distanceThreshold else 0 for dis in distance)
            if count[city] <= count[res]:
                res = city

        return res

