class Solution:
    def findTheCity(self, n: int, edges: List[List[int]], distanceThreshold: int) -> int:
        mat = [[math.inf] * n for i in range(n)]

        for i in range(n):
            # Distance of node to itself is zero
            mat[i][i] = 0
        for i, j, wt in edges:
            # Adding weights of given edges in matrix
            mat[i][j] = wt
            mat[j][i] = wt

        # Using Floyd Warshall Algorithm
        for k in range(n):
            # For every vertice
            for i in range(n):
                for j in range(n):
                    if(i == k or j == k):
                        continue
                    mat[i][j] = min(mat[i][j], mat[i][k] + mat[k][j])

        # Count no. of neighbours reachable within threshold for every vertice
        min_neighbor = n
        ans = n-1
        for i in range(n):
            count = 0
            for j in range(n):
                if(mat[i][j] <= distanceThreshold and i != j):
                    count += 1
            if(count <= min_neighbor):
                min_neighbor = count
                ans = i
        return ans

class Solution:
    def minDifficulty(self, jobDifficulty: List[int], d: int) -> int:
        jobCount = len(jobDifficulty)    
        if jobCount < d:
            return -1

        @lru_cache(None)
        def topDown(jobIndex: int, remainDayCount: int) -> int:
            remainJobCount = jobCount - jobIndex
            if remainDayCount == 1:
                return max(jobDifficulty[jobIndex:])

            if remainJobCount == remainDayCount:
                return sum(jobDifficulty[jobIndex:])

            minDiff = float('inf')
            maxToday = 0
            for i in range(jobIndex, jobCount - remainDayCount + 1):
                maxToday = max(maxToday, jobDifficulty[i])
                minDiff = min(minDiff, maxToday + topDown(i+1, remainDayCount-1))
            return minDiff

        return topDown(0, d)

class Solution:
    def minDifficulty(self, jobDifficulty: List[int], d: int) -> int:

        n = len(jobDifficulty)
        @lru_cache(None)
        def dfs(index, remaining_days):

            if remaining_days == 0:
                if index == n: return 0
                else: return sys.maxsize
            if index == n:
                if remaining_days == 0: return 0
                else: return sys.maxsize

            ans = sys.maxsize
            count_max = 0
            for i in range(index, n):
                count_max = max(count_max, jobDifficulty[i])
                ans = min(ans, count_max + dfs(i+1, remaining_days-1)) 
            return ans

        if n < d: return -1
        return dfs(0, d)

class Solution:
    def minDifficulty(self, jobDifficulties: List[int], days: int) -> int:
        n = len(jobDifficulties)

        @cache
        def dfs(i: int, days: int) -> int:
            if days == 0 or n - i < days:
                return -1

            if days == 1:
                # we can't partition any more
                return max(jobDifficulties[i:])

            res = math.inf

            curr_max = -math.inf
            for j in range(i, n - days + 1):
                # keep track of max in current "day"
                curr_max = max(curr_max, jobDifficulties[j])

                # keep track of min difficulty seen
                res = min(res, curr_max + dfs(j + 1, days - 1))

            return res

        return dfs(0, days)

class Solution:
    def minDifficulty(self, jobDifficulty: List[int], d: int) -> int:
        n = len(jobDifficulty)
        if n < d:
            return -1

        dp = [[-1] * (d + 1) for _ in range(n + 1)]

        def helper(index, dayleft):
            if dp[index][dayleft] != -1:
                return dp[index][dayleft]

            if dayleft == 1:
                return max(jobDifficulty[index :])

            else:
                best = float('inf')
                curr = 0
                for i in range(index, n - dayleft + 1):
                    curr = max(curr, jobDifficulty[i])
                    best = min(best, curr + helper(i + 1, dayleft - 1))
                    dp[index][dayleft] = best

                return best


        return helper(0, d)

class Solution:
    def minDifficulty(self, jobDifficulty: List[int], d: int) -> int:

        @lru_cache(None)
        def dp(idx,d,curr):

            if idx == len(jobDifficulty) and d == 0: return curr
            if idx >= len(jobDifficulty) or  d <= 0: return inf

            return min(dp(idx+1,d,max(curr,jobDifficulty[idx])),
                       max(curr,jobDifficulty[idx])+dp(idx+1,d-1,0))

        ans = dp(0,d,0)

        return ans if ans != inf else -1
