class Solution:
    def minDifficulty(self, jd: List[int], d: int) -> int:
        n = len(jd)
        if n < d: 
            return -1
        elif n == d: 
            return sum(jd)

        dic = {}
        def calc(i, restd, prev_max): 
            if i == n or restd < 0: 
                return float('inf')
            if (i, restd, prev_max) in dic: 
                return dic[(i, restd, prev_max)]
            if n - i < restd: 
                dic[(i, restd, prev_max)] = float('inf')
                return float('inf')
            elif n - i == restd: 
                dic[(i, restd, prev_max)] = max(prev_max, jd[i]) + sum(jd[i + 1:])
                return dic[(i, restd, prev_max)]
            else: 
                if i == 0: 
                    dic[(i, restd, prev_max)] = calc(i + 1, restd, jd[i])
                    return dic[(i, restd, prev_max)]
                case1 = calc(i + 1, restd, max(prev_max, jd[i]))
                case2 = prev_max + calc(i + 1, restd - 1, jd[i])
                dic[(i, restd, prev_max)] = min(case1, case2)
                return dic[(i, restd, prev_max)]
        return calc(0, d, 0)

