    def minDifficulty(self, jobDifficulty: List[int], d: int) -> int:
        N = len(jobDifficulty)
        if len(jobDifficulty) < d: return -1
        maxLookup = [-1]*N
        maxLookup[-1] = jobDifficulty[-1]

        for i in range(N-2, -1, -1):
            maxLookup[i] = max(jobDifficulty[i], maxLookup[i+1])

        def bt(idx, dt, mincarry):
            print (idx, dt, mincarry)
            if idx == len(jobDifficulty) and dt > 0:
                return -1

            if dt == 1:
                return mincarry+maxLookup[idx]

            maxi = jobDifficulty[idx] 
            ret = 10**9

            for i in range(idx+1, N-dt+2):
                ret = min(ret, bt(i, dt-1, mincarry+maxi))
                maxi = max(jobDifficulty[i], maxi)
            return ret 

        return bt(0, d, 0)

