class Solution:
    def kWeakestRows(self, mat: List[List[int]], k: int) -> List[int]:

        NoOfOnesInARow = {}
        for row in range(len(mat)):
            count = mat[row].count(1)
            if count in NoOfOnesInARow:
                NoOfOnesInARow[count].append(row)
            else:
                NoOfOnesInARow[count] = [row]


        counter = 0
        result = []
        while k>0:
            if counter in NoOfOnesInARow:
                x = NoOfOnesInARow.get(counter)
                x.sort()
                while k>0 and len(x):
                    result.append(x.pop(0))
                    k-=1
            counter+=1
        return result

