    def kWeakestRows(self, mat: List[List[int]], k: int) -> List[int]:
        m, n = len(mat), len(mat[0])
        vals = []
        for i in range(m): 
            lo, hi = 0, n
            while lo < hi: 
                mid = lo + hi >> 1
                if mat[i][mid]: lo = mid + 1
                else: hi = mid 
            vals.append((lo, i))
