class Solution:
    def minSetSize(self, arr: List[int]) -> int:
        n_removed = count = 0
        half_len_arr = ceil(len(arr) / 2)
        for _, n in Counter(arr).most_common():
            n_removed += 1
            count += n
            if count >= half_len_arr:
                return n_removed

class Solution:
    def minSetSize(self, arr: List[int]) -> int:
        counts = Counter(arr)
        pq = []
        for num in counts.keys():
            heapq.heappush(pq, -1 * counts[num])
        length = len(arr)
        cutoff = length//2
        res = 0
        while length > cutoff:
            length += heapq.heappop(pq)
            res += 1
        return res

