class Solution:
    def isPossible(self, target: List[int]) -> bool:
        n = len(target)
        sumk = 0
        for x in sorted(target):
            if x == 1:
                continue
            if (x-1) % (n-1) != 0:
                return False
            k = (x-1)//(n-1)
            if not k > sumk:
                return False
            sumk += k
        return True

