class Solution:
    def numberOfSubstrings(self, s: str) -> int:
        def helper(s):
            hm = defaultdict(int)
            hs, l, res = set(), 0, 0
            for r in range(len(s)):
                hm[s[r]] += 1
                hs.add(s[r])
                while len(hs) == 3:
                    hm[s[l]] -= 1
                    if not hm[s[l]]:
                        hs.remove(s[l])
                    l += 1
                res += r - l + 1
            return len(s) * (len(s) + 1) // 2 - res
        return helper(s)

