class Solution:
    def countOrders(self, n: int) -> int:
        mod = 10**9+7

        fact, pows = 1, n
        for i in range(2, n*2+1):
            if pows > 0:
                i /= 2
                pows -= 1
            fact = (fact * i) % mod

        return int(fact) % mod

