class Solution:
    def daysBetweenDates(self, date1: str, date2: str) -> int:

        days_in_month = [0, 31,28,31,30,31,30,31,31,30,31,30,31]

        y1, y2 = int(date1[:4]), int(date2[:4])
        m1, m2 = int(date1[5:7]), int(date2[5:7])
        d1, d2 = int(date1[-2:]), int(date2[-2:])

        def isleap(year):
            return 1 if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0) else 0

        dist1, dist2 = 0, 0
        for year in range(1971, y1):
                dist1 += 365 + isleap(year)
        for year in range(1971, y2):
                dist2 += 365 + isleap(year)

        for month in range(1, m1):
            if month == 2 and isleap(y1):
                dist1 += 1
            dist1 += days_in_month[month]

        for month in range(1, m2):
            if month == 2 and isleap(y2):
                dist2 += 1
            dist2 += days_in_month[month]

        dist1, dist2 = dist1 + d1, dist2 + d2

        return abs(dist1 - dist2)

