	    parent = {}
        for p, children in enumerate(zip(leftChild, rightChild)):
            for c in children:
                if c == -1:
                    continue
                if c in parent:
                    return False
                if p in parent and parent[p] == c:
                    return False
                parent[c] = p
        root = set(range(n)) - set(parent.keys())
