class Solution:
    def validateBinaryTreeNodes(self, n: int, L: List[int], R: List[int]) -> bool:
        visited = set()
        roots = list(range(n))
        components = n

        for i in range(n):
            if i not in visited:
                nodes = [i]

                while nodes:
                    curr = nodes.pop(0)

                    if curr in visited:
                        if roots[curr] != curr or roots[curr] == i:
                            return False
                        else:
                            roots[curr] = i

                    else:
                        visited.add(curr)
                        roots[curr] = i

                        if L[curr] != -1:
                            nodes.append(L[curr])
                        if R[curr] != -1:
                            nodes.append(R[curr])

                    if roots[curr] != curr:
                        components -= 1

        return components == 1

class Solution:
    def validateBinaryTreeNodes(self, n: int, leftChild: List[int], rightChild: List[int]) -> bool:
        hmap=defaultdict(list)
        degree=[0]*n
        for i in range(n):
            if leftChild[i]!=-1:
                hmap[i].append(leftChild[i])
                degree[leftChild[i]]+=1
            if rightChild[i]!=-1:
                hmap[i].append(rightChild[i])
                degree[rightChild[i]]+=1
        parent=[ind for ind,i in enumerate(degree) if i==0]
        vis=set()
        root=parent[0] if len(parent) else 0
        vis.add(root)
        if self.dfs(root,vis,hmap) and len(vis)==n:
            return True
        else:
            return False
    def dfs(self,node,vis,hmap):
        for it in hmap[node]:
            if it not in vis:
                vis.add(it)
                if self.dfs(it,vis,hmap):
                    continue
                else:
                    return False
            else:
                return False
        return True

class Solution:
    def validateBinaryTreeNodes(self, n: int, leftChild: List[int], rightChild: List[int]) -> bool:
        # find the root of tree --> node which is not in both list
        root = -1
        leftright = set(leftChild + rightChild)
        for i in range(n):
            if i not in leftright:
                root = i
                break
        # add the root to queue
        if root != -1:
            q = deque([root])
        else:
            return False
        # visited checks two things
        # 1. No node is visited again i.e cycle in the tree
        # 2. All the node are visited i.e check for disconnected nodes
        visited = set()
        while q:
            index = q.popleft()
            if index != -1:
                # if a node has two parent
                if index in visited:
                    return False
                visited.add(index)
                q.append(leftChild[index])
                q.append(rightChild[index])
        # If all the nodes are traversed or no disconected nodes
        return True if len(visited) == n else False

