        def dfs(node, seen):
            if node in seen:
                return False

            self.node_count += 1
            seen.add(node)

            if leftChild[node] != -1:
                if not dfs(leftChild[node], seen):
                    return False

            if rightChild[node] != -1:
                if not dfs(rightChild[node], seen):
                    return False

            return True


        root_set = set(range(n))
        for e in chain(leftChild, rightChild):
            if e != -1:
                if e not in root_set:
                    return False
                root_set.remove(e)

        if len(root_set) != 1:
            return False

        self.node_count = 0
        if not dfs(root_set.pop(), set()):
            return False

        return self.node_count == n

