		if num==2: return [2,2]
		res=[-float("inf"),float("inf")]
		for i in range(1,int(num**0.5)+2):
			a,b=(num+1)//i,(num+2)//i
			diff_r,diff_s_r=abs(res[0]-res[1]),min(abs(res[0]*res[1]-num-1),abs(res[0]*res[1]-num-2))
