class Solution:
    def isSubPath(self, head: Optional[ListNode], root: Optional[TreeNode]) -> bool:      

		# Utilize KMP String Pattern Matching Algorithm with the preorder traversal
		# O(N) space where N is max( depth of Tree, size of linked llist)
		# O(N) Runtime.

        def LPS(stack, size):

            prd = [0] * size
            prefixMatch = 0
            i = 1

            while i < size:
                if stack[i] == stack[prefixMatch]:
                    prefixMatch += 1
                    prd[i] = prefixMatch
                    i += 1
                else:
                    if prefixMatch != 0:
                        prefixMatch = prd[prefixMatch - 1]
                    else:
                        i += 1
            return prd

        def preorder(node, stack, lps, j):

            if j == len(stack):
                return True
            elif node is None:
                return False

            if node.val == stack[j]:
                    j += 1
            else:
                while j:
                    j = lps[j - 1]
                    if node.val == stack[j]:
                        j += 1
                        break
            return preorder(node.left, stack, lps, j) or preorder(node.right, stack, lps, j)

        if head is None or root is None:
            return False

        stack = []
        while head:
            stack.append(head.val)
            head = head.next

        lps = LPS(stack, len(stack))
        return preorder(root, stack, lps, 0)

class Solution:
    def isSubPath(self, head: ListNode, root: TreeNode) -> bool:
        if root is None:
            return False
        if self.helper(head, root):
            return True
        if self.isSubPath(head, root.left):
            return True
        return self.isSubPath(head, root.right)

    def helper(self, list_node: ListNode, tree_node: TreeNode) -> bool:
        if list_node is None:
            return True
        if tree_node is None:
            return False
        if tree_node.val != list_node.val:
            return False
        else:
            return self.helper(list_node.next, tree_node.left) or self.helper(list_node.next, tree_node.right)

