    def longestZigZag(self, root: Optional[TreeNode]) -> int:

        def postorder(node = root):
            nonlocal longest
            if not node:
                return (0, 0)
            L, R = postorder(node.left), postorder(node.right)
            M0, M1 = max(L[1]+1, 1), max(R[0]+1, 1)
            longest = max(M0, M1, longest)
            return (M0, M1)

        longest = 0
        postorder()
        return longest-1

