class Solution:
    def frogPosition(self, n: int, edges: List[List[int]], t: int, target: int) -> float:
        def gen_adjacency():
            adj = collections.defaultdict(list)
            for a, b in edges:
                adj[a].append(b)
                adj[b].append(a)
            return adj

        def dfs(node, cumprob, time):
            canjump = sum(1 for neigh in adj[node] if neigh not in visited)
            if node==target:
                if (time <= t and not canjump) or (time==t and canjump):
                    self.ans = cumprob
                return
            visited.add(node)
            if canjump:
                prob = 1/canjump
            else:
                return
            for neigh in adj[node]:
                if neigh not in visited:
                    dfs(neigh, cumprob * prob, time+1)

        visited = set()
        adj = gen_adjacency()
        self.ans = 0
        dfs(node=1, cumprob=1, time=0)
        return self.ans

class Solution:
    def frogPosition(self, n: int, edges: List[List[int]], t: int, target: int) -> float:
        if n==1:
            return 1.0
        D=defaultdict(list)
        for i,j in edges:
            D[i].append(j)
            D[j].append(i)
        L=[[-1,0]]*(n+1)
        L[1]=[1.0,0]
        q=[(1,1,0)]
        visited=set()
        astro=0
        while q:
            node,prob,time=q.pop(0)
            visited.add(node)
            for new_node in D[node]:
                if new_node not in visited:
                    new_prob=prob*(1/(len(D[node]) if astro==0 else len(D[node])-1))
                    q.append((new_node,new_prob,time+1))
                    L[new_node]=list([new_prob,time+1])
            astro+=1
        end_nodes=[]
        for d in D:
            if len(D[d])==1:
                end_nodes.append(d)
        if 1 in end_nodes:
            end_nodes.remove(1)
        if target in end_nodes:
            if L[target][1]>t:
                return 0.0
            return L[target][0]
        else:
            if L[target][1]==t:
                return L[target][0]
            return 0.0

class Solution:
    def frogPosition(self, n: int, edges: List[List[int]], t: int, target: int) -> float:
        if target==1:
            return 1.0 if len(edges)==0 else 0.0
        # note it's a undirected graph
        graph=[{} for _ in range(n+1)]
        for src,dst in edges:
            graph[src][dst]=1
            graph[dst][src]=1
        # do a bfs
        queue=[(1,1.0)]
        next=[]
        for time in range(t):
            for node,p in queue:
                for child in graph[node]:
                    del graph[child][node]
                    if child==target:
                        if time==t-1 or len(graph[child])<1:
                            return p/len(graph[node])
                        else:
                            return 0.0
                    next.append((child,p/len(graph[node])))
            queue=next
            next=[]
        return 0.0

