		for row in rowsTaken.keys():
			valid(row, [(row,2), (row,3), (row,4), (row,5)])

			valid(row, [(row,4), (row,5), (row,6), (row,7)])

			valid(row, [(row,6), (row, 7), (row,8), (row,9)])

