        if not grid or not grid[0]:
            return False

        M, N = len(grid), len(grid[0])
        left, right, up, down = (0,-1), (0,1), (-1,0), (1,0)
        direction = { 1: (left, right), 2: (up, down), 3: (left, down), 4: (right, down), 5: (left, up), 6: (right, up) }
        compatibles = { right: {1, 3, 5}, left: {1, 4, 6}, up: {2, 3, 4}, down: {2, 5, 6} }

        q = collections.deque([(0, 0)])
        seen = {(0, 0)}
        while q:
            r, c = q.popleft()
            if (r, c) == (M-1, N-1):
                return True
            di_x, di_y = direction[grid[r][c]]
            accepted_paths = compatibles[di_x] | compatibles[di_y]
            for dr, dc in [di_x, di_y]:
                cr, cc = r+dr, c+dc
                if (cr, cc) not in seen and 0 <= cr < M and 0 <= cc < N and grid[cr][cc] in accepted_paths:
                    seen.add((cr, cc))
                    q.append((cr, cc))
        return False

class Solution:
    def longestPrefix(self, s: str) -> str:
        n = [0] + [None] * (len(s) - 1)

        for i in range(1, len(s)):
            k = n[i - 1] # trying length k + 1
            while (k > 0) and (s[i] != s[k]):
                k = n[k - 1]
            if s[i] == s[k]:
                k += 1
            n[i] = k
        happy_border = n[-1]
        return s[:happy_border]

class Solution:
    def longestPrefix(self, s: str) -> str:
        n = len(s)
        z = [0] * n
        l, r = 0, 0
        for i in range(1, n):
            if i < r:
                z[i] = min(r - i, z[i - l])
            while i + z[i] < n and s[z[i]] == s[i + z[i]]:
                z[i] += 1
            if i + z[i] == n:
                return s[i:]
            if i + z[i] > r:
                l, r = i, i + z[i]
        return ''

