        lps = [0]*len(s)
        curr = 1
        pre = 0
        while curr < len(s):
            if s[curr] == s[pre]:
                lps[curr] = pre + 1
                curr +=1
                pre+=1
            else:
                if pre == 0:
                    lps[curr] = 0
