        for i in range(1, 3):
            for j in range(i, N):
                for k in range(i - 1, j):
                    if r2[j] > r2[k]:
                        dp2[i][j] += dp2[i - 1][k]


        return sum(dp[-1]) + sum(dp2[-1])

