class Solution:
    def entityParser(self, text):
        END = '&amp;'
        START = ';'
        d = {
            '&amp;quot;': '"',
            '&amp;apos;': "'",
            '&amp;amp;': '&amp;',
            '&amp;gt;': '>',
            '&amp;lt;': '<',
            '&amp;frasl;': '/',
        }
        stack = []
        seen_start = False
        for ch in reversed(text):
            if ch == START:
                seen_start = True
            stack.append(ch)
            if ch == END and seen_start:
                # check for a match
                temp = []
                while stack[-1] != START:
                    temp.append(stack.pop())
                temp.append(stack.pop()) # the ;
                val = ''.join(temp)
                if val in d:
                    stack.append(d[val])
                else:
                    stack.append(val)
                seen_start = False
        return ''.join(reversed(stack))

class Solution:
    def entityParser(self, text: str) -> str:
        chars = {'&amp;quot;':'"', 
                 '&amp;apos;':'\'', 
                 '&amp;amp;':'&amp;', 
                 '&amp;gt;':'>', 
                 '&amp;lt;':'<', 
                 '&amp;frasl;':'/'}
        output = ''
        i = 0
        while i < len(text):
            if text[i] != '&amp;':
                output += text[i]
                i += 1
            else:
                if i == len(text) - 1:
                    output += text[i]
                    break
                check = True
                next_idx = i + 1
                while text[next_idx] != ';':
                    if text[next_idx] == '&amp;':
                        check = False
                        break
                    else:
                        next_idx += 1
                if check: 
