        if len(res) >= k:
            return res[k-1]  
        else:
            return""
    def backtrack(self,res, letters, n, k, curr):
        if n == len(curr):
            res.append("".join(curr[:]))
        for i in range(0, len(letters)):
            if len(curr)>0 and letters[i] == curr[-1]: continue
            if n == len(curr): continue
            curr.append(letters[i])
            self.backtrack(res, letters, n, k, curr)
            curr.pop()

