class Solution:
    def reformat(self, s: str) -> str:
        n = len(s)
        letters = sum(c.isalpha() for c in s)
        digits = n - letters
        if abs(letters - digits) > 1:
            return ''

        res = [''] * n
        i = 0 if letters >= digits else 1
        j = 1 - i

        for c in s:
            if c.isalpha():
                res[i] = c
                i += 2
            else:
                res[j] = c
                j += 2

        return ''.join(res)

class Solution:
    def reformat(self, s: str) -> str:
        count_letters = count_digits = 0
        letters =digits = []

        for ch in s:
            if ch.isdigit():
                count_digits += 1
                digits.append(ch)
            else:
                count_letters += 1
                letters.append(ch)

        ans = "" 

        if abs(count_letters - count_digits) >1:
            return ""

        else:
            if count_digits >= count_letters:
                for index, digit in enumerate(digits):
                    if index < count_letters:
                        ans = ans + digit + letters[index]
                    else:
                        ans += digit
            else:
                for index, letter in enumerate(letters):
                    if index < count_digits:
                        ans = ans + letter + digits[index]
                    else:
                        ans += letter

        return ans

