class Solution:
    def displayTable(self, orders: List[List[str]]) -> List[List[str]]:
        orderDict = dict()
        tableHeader = set()
		"""
			below we create a dictionary with table id as key and a dictionary 
			containing no of each items as value. we also create a tableHeader 
			set to store all unique items ordered.
		"""
        for order in orders:
            if(order[1] not in orderDict):
                orderDict[order[1]] = dict()
            if(order[2] not in orderDict[order[1]]):
                orderDict[order[1]][order[2]] = 0
            orderDict[order[1]][order[2]] += 1
            tableHeader.add(order[2])
		"""
			output after above steps:
			orderDict: {
					'3': {
						'Ceviche': 2, 
						'Fried Chicken': 1
					},
					'10': {
						'Beef Burrito': 1
					}, 
					'5': {
						'Water': 1,
						'Ceviche': 1
					}
			} 
			tableHeader: {'Ceviche', 'Water', 'Fried Chicken', 'Beef Burrito'}

			Then we convert our set to a list and sort it as required.
			and iterate over the dict and create an array for each table
			where first item is the table id and following that are the 
			count of each item ordered by that table.
		"""
        tableHeader = list(tableHeader)    
        tableHeader.sort()
        answer = list()
        for tableId in orderDict:
            temp = list()
            temp.append(tableId)
            for header in tableHeader:
                if(header in orderDict[tableId]):
                    temp.append(str(orderDict[tableId][header]))
                else:
                    temp.append("0")
            answer.append(temp)
		"""
			Finally we sort the answer array based on the first value of each sub array i.e. the table id
			and add our tableHeader list as required to the answer on the first index.
		"""
        answer.sort(key = lambda x: int(x[0]))
        tableHeader.insert(0, "Table")
        answer.insert(0, tableHeader)
        return answer

