class Solution:
    def minNumberOfFrogs(self, croakOfFrogs: str) -> int:
        string = "croak"
        cnt = [0] * len(string)
        res, cur = 0, 0
        for c in croakOfFrogs:
            index = string.index(c)
            cnt[index] += 1
            # current char cnt should be greater than previous
            if index > 0 and cnt[index] > cnt[index-1]:
                return -1
            # new singing, increasing cur cnt
            if c == "c":
                cur += 1
            # singing finished, decreasing
            if c == "k":
                cur -= 1
            # capture max concurrent singing frogs
            res = max(res, cur)
        # all element should be the same
        if max(cnt) != min(cnt):
            return -1
        return res

class Solution:
    def minNumberOfFrogs(self, croakOfFrogs: str) -> int:
        counter = defaultdict(int)
        counter[''] = sys.maxsize
        mapping = {'c': '', 'r': 'c', 'o': 'r', 'a': 'o', 'k': 'a'}

        res = current = 0

        for char in croakOfFrogs:
            counter[char] += 1
            if counter[char] > counter[mapping[char]]:
                return -1

            if char == 'c':
                current += 1
            elif char == 'k':
                current -= 1

            res = max(res, current)

        if counter['c'] != counter['k']:
            return -1

        return res

