        vals = {'c': 0, 'r': 1, 'o': 2, 'a': 3, 'k': 4}
        croaks = [0] * 4
        frogs = 0

        for c in croakOfFrogs:
            val = vals[c]
            if val:
                if not croaks[val - 1]:
                    return -1
                croaks[val - 1] -= 1

            if val != 4:
                croaks[val] += 1

            frogs = max(frogs, sum(croaks))

        return frogs if not sum(croaks) else -1

class Solution:
    def numOfArrays(self, n: int, m: int, K: int) -> int:
        MOD = 10 ** 9 + 7
        # f[i][j][k] cumulative sum, first i elements, current max less than or equal to j, k more maximum to fill
        f = [[[0 for _ in range(K + 1)] for _ in range(m + 1)] for _ in range(n + 1)]
        for j in range(m + 1):
            f[0][j][K] = 1

        for i in range(n + 1):
            for j in range(1, m + 1):
                for k in range(K):
                    #             prev value       a[i] <= pref high                            a[i] = j refresh high
                    f[i][j][k] = (f[i][j - 1][k] + j * (f[i - 1][j][k] - f[i - 1][j - 1][k]) + f[i - 1][j - 1][k + 1]) % MOD

        return f[n][m][0]

class Solution:
    def numOfArrays(self, n: int, m: int, k: int) -> int:
        @lru_cache(None)
        def solve(size,maxNum,lis):
            val=0
            if size==1:
                return lis==1
            for mx in range(1,m+1):
                if mx<maxNum:
                    val+=solve(size-1,mx,lis-1)
                else:
                    val+=solve(size-1,maxNum,lis)
            return val%1000000007

        ans=0
        ans=solve(n+1,m+1,k+1)
        return ans

class Solution:
    def numOfArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7
        dp = {}

        def helper(curr_max, n,k):
            if k==0:
                return (curr_max ** n)%MOD

            if n==0:
                return 0

            if (curr_max, n,k) in dp:
                return dp[(curr_max, n,k)]

            a = 0
            for val in range(1,m+1):
                # 1 take it
                temp = k
                if curr_max < val:
                    temp-=1
                a = (a + helper(max(curr_max, val),n-1,temp))%MOD
            dp[(curr_max, n,k)] = a
            return dp[(curr_max, n,k)]
        return helper(0,n,k)%MOD

class Solution:
    def numOfArrays(self, n: int, m: int, k: int) -> int:

        @cache
        def fn(i, x, k): 
            """Return number of ways to build arr[i:] with current max at x and remaining cost at k."""
            if n - i < k: return 0 # impossible 
            if m - x < k: return 0 # impossible 
            if k == 0: return x**(n-i)
            return x*fn(i+1, x, k) + fn(i+1, x+1, k-1) + fn(i, x+1, k) - (x+1)*fn(i+1, x+1, k)

        return fn(0, 0, k) % 1_000_000_007

