class Solution:
    def maxScore(self, cardPoints: List[int], k: int) -> int:
        if len(cardPoints) == 0: 0
        if len(cardPoints) <= k: return sum(cardPoints)

        subArraySum = sum(cardPoints[0:len(cardPoints) - k])
        subArraySumArray = [subArraySum]

        for i in range(k):
            subArraySum = subArraySum - cardPoints[i] + cardPoints[i + len(cardPoints) - k]
            subArraySumArray.append(subArraySum)

        return sum(cardPoints) - min(subArraySumArray)

