        for i in range(1, n):
            dp[i] = nums[i] + max(0, dp[mono_dec_q[0]])
            while mono_dec_q and dp[i] >= dp[mono_dec_q[-1]]:
                mono_dec_q.pop()
            if mono_dec_q and i - mono_dec_q[0] == k:
                mono_dec_q.popleft()
            mono_dec_q.append(i)
            res = max(res, dp[i])
        return res

