        return count(1, 0)

class Solution:
    def numberWays(self, hats: List[List[int]]) -> int:
        # use hat masks in bottom up dp
        n_hats, n_persons = 40, len(hats)                

        dp = [collections.defaultdict(int) for i in range(n_persons + 1)]
        # dp[i] = dict hat_mask -> count using [:i] persons

        curr = dp[0]
        curr[0] = 1
        prev = curr

        for i in range(n_persons):
            curr = dp[i + 1]
            for key in prev:
                curr[key] += prev[key]
            for h in hats[i]:
                bit = 1 << (h - 1)
                for hat_mask in prev:
                    if bit &amp; hat_mask == 0:
                        curr[bit | hat_mask] += prev[hat_mask]
            prev = curr

        # answer is sum over all masks with n_persons 1 bits
        masks = []
        for m in dp[n_persons]:
            count, mm = 0, m
            while mm:
                count += 1
                mm = mm &amp; (mm - 1)
            if count == n_persons:
                masks.append(m)                
        return sum(dp[n_persons][m] for m in masks) % 1000000007

class Solution:
    def numberWays(self, hats: List[List[int]]) -> int:
        # use person masks in bottom up dp
        n_hats, n_persons = 40, len(hats)
        n_masks = 1 << n_persons
        persons = [[] for _ in range(n_hats)]
        for person, arr in enumerate(hats):
            for hat in arr:
                persons[hat - 1].append(person) # hat is one based

        dp = [[0 for person_mask in range(n_masks)] for i in range(n_hats + 1)]
        # dp[i][person_mask] = count using [:i] hats

        curr = dp[0]
        curr[0] = 1
        prev = curr

        for i in range(n_hats):
            curr = dp[i + 1]
            for person_mask in range(n_masks):
                curr[person_mask] += prev[person_mask]
            for person in persons[i]:
                bit = 1 << person
                for person_mask in range(n_masks):
                    if bit &amp; person_mask == 0:
                        curr[bit | person_mask] += prev[person_mask]
            prev = curr

        return curr[(1 << n_persons) - 1] % 1000000007

class Solution:
    def numberWays(self, hats: List[List[int]]) -> int:
        N = len(hats) # number of people
        h2p = collections.defaultdict(list) # hat -> people
        for person in range(N):
            for hat in hats[person]:
                h2p[hat].append(person)

        if len(h2p) < N: # when the number of hats < the number of people
            return 0

		# For each hat, dp stores the status of the people has been matched by a hat.
        # e.g. 0b0000000000 means no one wears a hat
        # 0b0010000000 means only person No.2 wears a hat
        # There are totally 2 ^ N different possible status.
        MASK = [1 << p for p in range(N)]
        dp = [[0] * (2 ** N) for _ in range(len(h2p) + 1)]
        dp[0][0] = 1

        i, MOD = 1, 1000000007
        while h2p: # O(H)
            _, people = h2p.popitem()
            for j, n in enumerate(dp[i - 1]): #O(2^P)
                if not n:
                    continue

                dp[i][j] += n # when mask = 0
                for p in people: #O(P)
                    if not (MASK[p] &amp; j):
                        dp[i][MASK[p] + j] += n
            i += 1

        return dp[-1][-1] % MOD

