class Solution:
    def kLengthApart(self, nums: List[int], k: int) -> bool:
        # k represents the minimum distance 1's are allowed to be apart
        # keep count of 1's and 0's seen
        # if the count of 1's equals 2, check to make sure the count of 0's is greater
        # than k
        # if it is, reset 1's count to 1 (because we just saw a 1) and make 0's
        # count 0
        # time O(N) space O(1)

        seen = count = 0

        for i in range(len(nums)):
