			   cls._good_nodes(node.left, curr_max) + \
			   cls._good_nodes(node.right, curr_max)

class Solution:
    def goodNodes(self, root: TreeNode) -> int:
        ans = 0 
        stack = [(root, -inf)]
        while stack: 
            node, val = stack.pop()
            if node: 
                if node.val >= val: ans += 1
                val = max(val, node.val)
                stack.append((node.left, val))
                stack.append((node.right, val))
        return ans

