        def isPalindromicPath(palinArr: [int]) -> bool:
            hasSeenFirstOdd: bool = False
            for i in range(0, len(palinArr)):
                if(palinArr[i] % 2 == 1):
                    if hasSeenFirstOdd: return False
                    hasSeenFirstOdd = True
            return True

