class Solution:
    def pseudoPalindromicPaths (self, root: Optional[TreeNode]) -> int:
        answer = 0
        val_count = [0] * 9
        visited = {}
        stack = [root]

        while stack != []:
            node = stack.pop()
            if visited.get(node) is None:
                val_count[node.val-1] += 1
                stack.append(node)
                visited[node] = 1

                is_leaf = True
                if node.right:
                    is_leaf = False
                    stack.append(node.right)
                if node.left:
                    is_leaf = False
                    stack.append(node.left)

                if is_leaf:
                    odds = 0
                    for i in val_count:
                        if i % 2 == 1:
                            odds += 1

                    answer += 1 if odds <= 1 else 0

            else:
                val_count[node.val-1] -= 1


        return answer

