		m, n = len(grid), len(grid[0])

		@lru_cache(None)
		def dfs(r,c1,c2):
			if r==m:
				return 0

			ch = grid[r][c1] if c1==c2 else grid[r][c1]+grid[r][c2]            
			res = 0
			for p in range(c1-1,c1+2):
				for q in range(c2-1,c2+2):
