                    visited[i]=1
            for i in outdegree[x]:
                if visited[i]==0:
                    lst.append(i)
                    visited[i]=1
                    # here we have to change the direction of edge
                    ct+=1
        return ct

class Solution:
    def minReorder(self, n: int, connections: List[List[int]]) -> int:
        graph = defaultdict(set)
        for a, b in connections:
            graph[a].add((b, True))
            graph[b].add((a, False))

        queue = deque([(0, False)])
        ans = 0
        visited = set()
        while queue:
            city, needs_flipped = queue.popleft()
            visited.add(city)
            if needs_flipped:
                ans += 1
            for neighbour in graph[city]:
                if neighbour[0] not in visited:
                    queue.append(neighbour)
        return ans

class Solution:
    def __init__(self):
        self.res = 0 # number of changed edges

    def dfs(self, g, v, visited):
        visited[v] = 1 # v is visited

        for neigb in g[v]:
            if visited[neigb[0]] == 0: # if  neigb[0] (v) is not visited
                if neigb[1] == 1: # if weight = 1, then wee need change edge (we moving from root (from 0))
                    self.res += 1

                self.dfs(g, neigb[0], visited)

    def minReorder(self, n: int, connections: List[List[int]]) -> int:
        g = collections.defaultdict(list)
        visited = [0] * n

        for conn in connections:
            """
            [conn[1], 1] - conn[1] - v and 1 - weight (1 means that v has output edge)
            [conn[0], -1] - conn[0] - v and -1 - weight (-1 means that v has input edge))
            """
            g[conn[0]].append([conn[1], 1]) 
            g[conn[1]].append([conn[0], -1])

        self.dfs(g, 0, visited)

        return self.res

class Solution:
    def minReorder(self, n: int, connections: List[List[int]]) -> int:
        in_, out = dict(), dict()
        for u, v in connections: 
            out.setdefault(u, []).append(v)
            in_.setdefault(v, []).append(u)

        def dfs(n): 
            """Return required number of reverses"""
            seen[n] = True
            ans = sum(not seen[x] for x in out.get(n, []))
            for nn in in_.get(n, []) + out.get(n, []): 
                if not seen[nn]: ans += dfs(nn)
            return ans 

        seen = [False]*n
        return dfs(0)

class Solution:
    def minReorder(self, n: int, connections: List[List[int]]) -> int:
        incoming={}
        outgoing={}
        for n1,n2 in connections:
            if outgoing.get(n1):
                outgoing[n1].append(n2)
            else:
                outgoing[n1]=[n2]
            if incoming.get(n2):
                incoming[n2].append(n1)
            else:
                incoming[n2]=[n1]
        q=collections.deque()
        q.append(0)
        res=0
        visited=set()

        while q:
            node=q.popleft()
            if incoming.get(node) :
                for i in incoming[node]:
                    if i is not 0 and i not in visited:
                        q.append(i)
            if outgoing.get(node):
                for o in outgoing[node]:
                    if o is not 0 and o not in visited:
                        q.append(o)
                        res+=1
            visited.add(node)
        return res

class Solution:
    def minReorder(self, n: int, connections: List[List[int]]) -> int:
        ans = 0
        edges = {x:{} for x in range(n)}
        for e in connections:
            edges[e[0]][e[1]] = 1
            edges[e[1]][e[0]] = 0
        return self.dfs(0, edges)

    def dfs(self, root, edges):
        if not edges[root]: return 0
        ans = 0
        for k,v in edges[root].items():
            if v!=-1:
                ans+=v
                edges[root][k] = -1
                edges[k][root] = -1
                ans+=self.dfs(k,edges)
        return ans

class Solution:
    def minReorder(self, n: int, connections: List[List[int]]) -> int:
        # Build the graph: (connected node, forward)
        graph = [[] for _ in range(n)]
        for c in connections:
            graph[c[0]].append((c[1], True))
            graph[c[1]].append((c[0], False))

        seen = [False] * n
        seen[0] = True
        q = deque([0])
        res = 0

        while q:
            cur = q.popleft()
            for n, forward in graph[cur]:
                if not seen[n]:
                    seen[n] = True
                    q.append(n)
                    if forward:
                        res += 1

        return res

class Solution:
    def getProbability(self, balls: List[int]) -> float:
        n = sum(balls)//2

        @cache 
        def fn(i, s0, s1, c0, c1):
            """Return number of ways to distribute boxes successfully (w/o considering relative order)."""
            if s0 > n or s1 > n: return 0 # impossible 
            if i == len(balls): return int(c0 == c1)
            ans = 0 
            for x in range(balls[i]+1): 
                ans += fn(i+1, s0+x, s1+balls[i]-x, c0+(x > 0), c1+(x < balls[i])) * comb(balls[i], x)
            return ans

        return fn(0, 0, 0, 0, 0) / comb(2*n, n)

