class Solution(object):
    def shuffle(self, nums, n):
        """
        :type nums: List[int]
        :type n: int
        :rtype: List[int]
        """
        def swappairs(i,j):
            while(i<j):
                swap(i,i+1)
                i+=2
        def swap(i,j):
            tmp = nums[i]
            nums[i] = nums[j]
            nums[j] = tmp
        for i in range(n-1):
            swappairs(n-1-i,n+i)
        return nums

