class Solution:
    def getStrongest(self, arr: List[int], k: int) -> List[int]:
        new_arr = []
        arr.sort()
        med = arr[int((len(arr) - 1)//2)]
        for num in arr : 
            new_arr.append([int(abs(num - med)), num])

        new_arr = sorted(new_arr, key = lambda x : (x[0], x[1]))

        output, counter = [], 0
        for i in reversed(range(len(new_arr))) : 
            output.append(new_arr[i][1])
            counter += 1 
            if counter == k : 
                return output 

        return output

class Solution:
    def getStrongest(self, arr: List[int], k: int) -> List[int]:
        arr.sort()
        n = len(arr)
        median = arr[(n - 1) // 2]
        res = []
        left, right = 0, n - 1

        for _ in range(k):
            if median - arr[left] > arr[right] - median:
                res.append(arr[left])
                left += 1
            else:
                res.append(arr[right])
                right -= 1

        return res

class Solution:
    def getStrongest(self, arr: List[int], k: int) -> List[int]:
        z = sorted(arr)
        n = len(arr)
        median = (n-1)//2
        i = 0
        j = n-1
        res = []
        while len(res) != k:
            if z[j]-z[median] > z[median]-z[i] or (z[j]-z[median] == z[median]-z[i] and z[j] >= z[i]):
                res.append(z[j])
                j -= 1
            elif z[j]-z[median] < z[median]-z[i] or (z[j]-z[median] == z[median]-z[i] and z[j] < z[i]):
                res.append(z[i])
                i += 1
        return res

class Solution:
    def getStrongest(self, arr: List[int], k: int) -> List[int]:
        arr.sort()
        m = arr[(len(arr)-1)//2]
        ans, lo, hi = [], 0, len(arr)-1
        while len(ans) < k: 
            if m - arr[lo] > arr[hi] - m: 
                ans.append(arr[lo])
                lo += 1
            else:
                ans.append(arr[hi])
                hi -= 1
        return ans

class Solution:
    def getStrongest(self, arr: List[int], k: int) -> List[int]:
        n = len(arr)

        if n == 1:
            return arr[:k]
        elif n == k:
            return arr

        arr.sort()
        m = arr[(n-1)//2]

        res = []
        i, j = 0, n-1
        while i < j:
            if abs(arr[i]-m) > abs(arr[j]-m):
                res.append(arr[i])
                i += 1
            elif abs(arr[i]-m) < abs(arr[j]-m):
                res.append(arr[j])
                j -= 1
            else: # abs(arr[i]-m) == abs(arr[j]-m)
                if arr[i] > arr[j]:
                    res.append(arr[i])
                    i += 1
                elif arr[i] < arr[j]:
                    res.append(arr[j])
                    j -= 1
                else:
                    res.append(arr[i])
                    i += 1
            if len(res) == k:
                return res

class Solution:
    def minCost1(self, houses: List[int], cost: List[List[int]], R: int, C: int, target: int) -> int:
        # think as if we are traveling downward
        # at any point, if switch our column then (target--)

        @functools.cache
        def dp(x,y,k): # O(100*20*100) time space
            if x == R:
                return 0 if k == 0 else math.inf
            elif k <= 0: 
                return math.inf

            # if this house is already colored, dont recolor!!
            if houses[x] > 0 and houses[x] != y+1: return math.inf

            cur_cost = 0 if houses[x] == y+1 else cost[x][y] 

            # now try all columns! O(20) time
            res = math.inf
            for c in range(C):
                if c == y:
                    res = min(res, cur_cost + dp(x+1,c,k))
                else:
                    res = min(res, cur_cost + dp(x+1,c,k-1))
            # print('dp',x,y,k,'=',res)
            return res

        ans = min(dp(0,y,target) for y in range(C))

        return -1 if ans == math.inf else ans

class Solution:
    def minCost(self, houses: List[int], cost: List[List[int]], m: int, n: int, target: int) -> int:        
        # dp_values[i][j][k] records the min costs that we have k+1 neighbors 
        # in the first i houses and the ith house is painted with j
        dp_values = [[[float('inf')]*target for _ in range(n)] for _ in range(m)]
		# initial values
        if houses[0] != 0:
            dp_values[0][houses[0]-1][0] = 0
        else:
            for i in range(n):
                dp_values[0][i][0] = cost[0][i]
        for i in range(1, m):
            for j in range(n):
                # houses[i] is painted. we only consider when j == houses[i]
                if houses[i] != 0 and j != houses[i]-1:
                    continue
                for k in range(target):
                    # for i houses, we can't have more than i neighbors 
                    if k > i:
                        break
                    if houses[i-1] != 0:
                        if j == houses[i-1]-1:
                            dp_values[i][j][k] = dp_values[i-1][j][k]
                        else:
                            # if k == 0, it makes no sense to consider the case that current 
                            # house color is different from the previous house's color.
                            if k > 0:
                                dp_values[i][j][k] = dp_values[i-1][houses[i-1]-1][k-1]
                    else:
                        min_with_diff_color = float('inf')
                        if k > 0:
                            for w in range(n):
                                if w == j:
                                    continue
                                min_with_diff_color = min(min_with_diff_color, dp_values[i-1][w][k-1])
                        dp_values[i][j][k] = min(min_with_diff_color, dp_values[i-1][j][k])
                    # if the house is not painted, we need extra cost
                    if houses[i] == 0:
                        dp_values[i][j][k] += cost[i][j]
        costs = float('inf')
        for j in range(n):
            costs = min(costs, dp_values[m-1][j][target-1])
        return costs if costs != float('inf') else -1

class Solution:
    def minCost(self, houses: List[int], cost: List[List[int]], _: int, colors: int, target: int) -> int:

        @cache
        def dfs(index, last_color, neighborhoods):
            if index == len(houses):
                return 0 if neighborhoods == target else float('inf')

            if neighborhoods > target:
                return float('inf')

            # this house needs to be painted
            if houses[index] == 0:
                result = float('inf')
                for c in range(1, colors + 1):
                    result = min(result, dfs(index + 1, c, neighborhoods + (c != last_color)) + cost[index][c-1])
                return result

            # this house is already painted
            return dfs(index + 1, houses[index], neighborhoods + (houses[index] != last_color))

        result = dfs(0, 0, 0)
        return result if result != float('inf') else -1

class Solution:
    def minCost(self, houses: List[int], cost: List[List[int]], H: int, C: int, target: int) -> int:

        dp={}
        inf=math.inf

        def finder(i,last_color,neigh):

            if i==H:
                if neigh==target:
                    return 0
                return inf

            if neigh>target:
                return inf 

            if (i,last_color,neigh) in dp:
                return dp[(i,last_color,neigh)]

            if houses[i]==0:

                ans=inf

                for current_color in range(1,C+1):

                    if last_color==current_color:
                        ans= min(ans,finder(i+1,last_color,neigh)+cost[i][current_color-1])
                    else:
                        ans= min(ans,finder(i+1,current_color,neigh+1)+cost[i][current_color-1])

                dp[(i,last_color,neigh)]=ans
                return ans

            else:

                ans=None

                if last_color==houses[i]:
                    ans= finder(i+1,last_color,neigh)
                else:
                    ans= finder(i+1,houses[i],neigh+1)

                dp[(i,last_color,neigh)]=ans
                return ans

        ans=finder(0,0,0)

        if ans>=inf:
            return -1
        return ans

class Solution:
    def minCost(self, houses: List[int], cost: List[List[int]], m: int, n: int, target: int) -> int:

        @lru_cache(None)
        def rec(i, k, last):
            if i == 0:
                return int(k != 0) * 10**9

            if k == -1 or i < k:
                return 10**9

            if houses[i-1] == 0:
                temp = 10**9
                for v in range(1, n+1):
                    if v == last:
                        temp = min(temp, rec(i-1, k, last) + cost[i-1][last-1])
                    else:
                        temp = min(temp, rec(i-1, k-1, v) + cost[i-1][v-1])
                return temp

            if last == houses[i-1]:
                return rec(i-1, k, last)

            return rec(i-1, k-1, houses[i-1])


        z = rec(m, target, -1)
        return -1 if z >= 10**9 else z

class Solution:
    def minCost(self, houses: List[int], cost: List[List[int]], m: int, n: int, target: int) -> int:

        @lru_cache(None)
        def dp(idx, target, prev):
            # remaining house < remaining neighbor to form
            if target < 0 or target > m - idx:
                return float('inf')

            if idx == m:
                return 0

            # houses painted
            if houses[idx]:
                return dp(idx + 1, target - (prev != houses[idx]), houses[idx])
            # no more neighbor need to be formed (all remaining must be painted as previous one)
            if target == 0:
                return cost[idx][prev-1] + dp(idx + 1, target, prev)

            ans = float('inf')
            for paint in range(n):
                ans = min(ans, cost[idx][paint] + dp(idx + 1, target - (prev != paint+1), paint+1))
            return ans                          

        ans = dp(0, target, -1)
        return ans if ans < float("inf") else -1

class Solution:
    def minCost(self, houses: List[int], cost: List[List[int]], m: int, n: int, target: int) -> int:

        @cache
        def dp(house, last_color, neis):
            # to many neighborhoods or not enough
            if neis < 0 or house + neis > m:
                return float('inf')
            # after last house, 0 neighborhoods left -> valid
            if house == m and neis == 0:
                return 0
            # already painted
            if houses[house] > 0:
                if last_color != houses[house] - 1:
                    neis -= 1
                return dp(house + 1, houses[house] - 1, neis)

            min_cost = float('inf')
            for color in range(n):
                if last_color == color: # same neighborhood
                    min_cost = min(min_cost, cost[house][color] + dp(house + 1, color, neis) )
                else: # start a new neighborhood
                    min_cost = min(min_cost, cost[house][color] + dp(house + 1, color, neis - 1) )

            return min_cost

        cost = dp(0, -1, target)
        return -1 if cost >= float('inf') else cost

class Solution:
    def minCost(self, houses: List[int], cost: List[List[int]], m: int, n: int, target: int) -> int:
        # dp[i][c][k]: i means the ith house, c means the cth color, k means k neighbor groups
        dp = [[[math.inf for _ in range(n)] for _ in range(target + 1)] for _ in range(m)]

        for c in range(1, n + 1):
            if houses[0] == c:
                dp[0][1][c - 1] = 0
            elif not houses[0]:
                dp[0][1][c - 1] = cost[0][c - 1]

        for i in range(1, m):
            for k in range(1, min(target, i + 1) + 1):
                for c in range(1, n + 1):
                    if houses[i] and c != houses[i]:
                        continue
                    same_neighbor_cost = dp[i - 1][k][c - 1]
                    diff_neighbor_cost = float("inf")
                    for c_ in range(n):
                        if c_ == c-1:
                            continue
                        diff_neighbor_cost = min(diff_neighbor_cost,dp[i - 1][k - 1][c_])
                    paint_cost = cost[i][c - 1] * (not houses[i])
                    dp[i][k][c - 1] = min(same_neighbor_cost, diff_neighbor_cost) + paint_cost
        res = min(dp[-1][-1])
        return res if res != math.inf else -1

class Solution:
    def finalPrices(self, prices: List[int]) -> List[int]:
        len_prices = len(prices)
        i = 0
        while i <= len_prices-2:
            for j in range(i+1, len(prices)):
                if prices[i] >= prices[j] and j > i:
                    prices[i] = prices[i] - prices[j]
                    break

            i += 1

        return prices

class Solution:
    def finalPrices(self, prices: List[int]) -> List[int]:
        for i in range(len(prices)):
          for j in range(i+1,len(prices)):
            if prices[j]<=prices[i]:
              prices[i]=prices[i]-prices[j]
              break
        return (prices)

class Solution:
    def finalPrices(self, prices: List[int]) -> List[int]:
        ans=[]
        for i in range(len(prices)-1):
            flag=False
            for j in range(i+1,len(prices)):
                if prices[i]>=prices[j]:
                    ans.append(abs(prices[i]-prices[j]))
                    flag=True
                    break
            if flag==False:
                ans.append(prices[i])


        ans.append(prices[-1])
        return ans

class Solution:
    def finalPrices(self, p: List[int]) -> List[int]:

        n=len(p)
        stack =[]
        ans=[]

        for j in range(n-1,-1,-1):

            while stack and stack[-1]>p[j]:
                stack.pop()

            if len(stack)==0:
                ans.append(p[j])
            else:
                ans.append(p[j]-stack[-1])
            stack.append(p[j])
        return ans[::-1]

class Solution:
    def finalPrices(self, prices: List[int]) -> List[int]:
        for i in range(len(prices)-1):
            for j in range(i+1,len(prices)):
                if prices[j] <= prices[i]:
                    prices[i] -= prices[j]
                    break
        return prices

class Solution:
    def finalPrices(self, prices: List[int]) -> List[int]:
        #create a monotonic stack
        mono_stack = []

        #loop through the elements of prices
        for i,p in enumerate(prices):

            #subtract current prices from prices at last index of mono_stack until it is greater or equal to the current prices
            while len(mono_stack)>0 and prices[mono_stack[-1]]>=p:
                prices[mono_stack.pop()]-=p
            #at last append current price to the mono_stack
            mono_stack.append(i)

        return prices

class Solution:
    def finalPrices(self, prices: List[int]) -> List[int]:
        output = []
        for i in range(len(prices)):
            for j in range(i+1,len(prices)):
                if j == len(prices)-1 and prices[j] > prices[i]:
                    output.append(prices[i])
                elif j == len(prices)-1 and prices[j] == prices[i]:
                    output.append(prices[i]-prices[j])
                elif prices[j] <= prices[i]:
                    output.append(prices[i]-prices[j])
                    break
        output.append(prices[-1])
        return output

class Solution:
	def finalPrices(self, prices: List[int]) -> List[int]:
		ans=[i for i in prices]
		stack=[] #index stack

		# increasing stack
		for i in range(len(prices)):
			while stack and prices[stack[-1]]>=prices[i]:
				idx=stack.pop()
				ans[idx]=ans[idx]-prices[i]
			stack.append(i)

		return ans

class Solution:
    def finalPrices(self, prices: List[int]) -> List[int]:
        if len(prices) == 1:
            return prices

        for j in range(1, len(prices)):
            if prices[j] <= prices[0]:
                return [prices[0] - prices[j]] + self.finalPrices(prices[1:])

        return [prices[0]] + self.finalPrices(prices[1:])

raw.description:
Implement the class `SubrectangleQueries` which receives a `rows x cols` rectangle as a matrix of integers in the constructor and supports two methods:
1.` updateSubrectangle(int row1, int col1, int row2, int col2, int newValue)`
Updates all values with `newValue` in the subrectangle whose upper left coordinate is `(row1,col1)` and bottom right coordinate is `(row2,col2)`.

2.` getValue(int row, int col)`
Returns the current value of the coordinate `(row,col)` from the rectangle.


Example 1:
Input
["SubrectangleQueries","getValue","updateSubrectangle","getValue","getValue","updateSubrectangle","getValue","getValue"]
[[[[1,2,1],[4,3,4],[3,2,1],[1,1,1]]],[0,2],[0,0,3,2,5],[0,2],[3,1],[3,0,3,2,10],[3,1],[0,2]]
Output
[null,1,null,5,5,null,10,5]
Explanation
SubrectangleQueries subrectangleQueries = new SubrectangleQueries([[1,2,1],[4,3,4],[3,2,1],[1,1,1]]);  
// The initial rectangle (4x3) looks like:
// 1 2 1
// 4 3 4
// 3 2 1
// 1 1 1
