class Solution:
    def minNumberOfSemesters(self, n: int, dependencies: List[List[int]], k: int) -> int:
        pre = [0]*n # prerequisites 
        for u, v in dependencies: 
            pre[v-1] |= 1 << (u-1) 

        @cache
        def fn(mask): 
            """Return min semesters to take remaining courses."""
            if mask == (1 << n) - 1: return 0 # all courses taken 
            can = [] # available courses 
            for i in range(n): 
                if not mask &amp; 1 << i and mask &amp; pre[i] == pre[i]: 
                    can.append(i)

            ans = inf
            for courses in combinations(can, min(k, len(can))): 
                temp = mask | reduce(lambda x, y: x | 1 << y, courses, 0)
                ans = min(ans, 1 + fn(temp))
            return ans 

        return fn(0)

class Solution:
    def minNumberOfSemesters(self, n: int, relations: List[List[int]], k: int) -> int:
        adj = defaultdict(list)
        in_deg = [0]*n

        for prev, nxt in relations:
            adj[prev-1].append(nxt-1)
            in_deg[nxt-1]+=1

        # bit_mask:
        # 1 means not taken
        # 0 mean taken
        # initialize to 1<<n -1

        @cache
        def backtrack(bit_mask):
            if not bit_mask:
                return 0

            catalog = [i for i in range(n) if in_deg[i] == 0 and bit_mask &amp; 1<<i]             
            ret = float("inf")
            for k_courses in combinations(catalog,min(k,len(catalog))):
                nxt_bit_mask = bit_mask                
                for course in k_courses:
                    nxt_bit_mask ^= 1<<course
                    for parent in adj[course]:
                        in_deg[parent]-=1

                ret = min( ret, 1 + backtrack( nxt_bit_mask ) )

                for course in k_courses:
                    for parent in adj[course]:
                        in_deg[parent]+=1                
            return ret

        return backtrack((1<<n) -1)

class Solution:
    def minNumberOfSemesters(self, n: int, dependencies: List[List[int]], k: int) -> int:
        graph = collections.defaultdict(int)
        for x, y in dependencies:
            graph[y] |= 1 << (x - 1) # dependency mask of course y
        last_mask = (1 << n) - 1 # all course
        queue = collections.deque([(0, 0)]) # start with zero course taken
        visited = {0}
        while queue:
            mask, num_semesters = queue.popleft()
			# mask &amp; (1 << (x - 1)) == 0 course have not been taken
			# mask &amp; graph[x] == graph[x] but all its dependency course have been taken
            free_courses = [x for x in range(1, n + 1) if (mask &amp; (1 << (x - 1)) == 0) and mask &amp; graph[x] == graph[x]]
            for courses in itertools.combinations(free_courses, min(k, len(free_courses))):
                new_mask = mask
                for x in courses:
                    new_mask |= 1 << (x - 1)
                if new_mask == last_mask:
                    return num_semesters + 1
                if new_mask not in visited:
                    visited.add(new_mask)
                    queue.append((new_mask, num_semesters + 1))

