class Solution:
    def numSubseq(self, nums: List[int], target: int) -> int:
        mod = 10 ** 9 + 7
        ct = 0

        n = len(nums)
        nums.sort()

        def bsearch(x: List[int], t: int, l: int, n: int = n) -> int:
			# Returns the rightmost valid index for number <= target
            r = n-1
            while(l < r):
                m = l + (r - l) // 2 + 1
                if x[m] <= t:
                    l = m
                else:
                    r = m - 1
            return r

		# loop on min value
