                res += pow(2, r-l, mod)
                l += 1

        return res % mod

class Solution:
    def numSubseq(self, nums: List[int], target: int) -> int:

        # sort 
        nums.sort()

        # easy corner case
        if nums[0] > target:
            return 0

        # preprocess the nums to remove useless numbers that are already greater than target
        left = 0
        right = len(nums)
        while left < right:
            mid = (left + right) >> 1
            if nums[mid] <= target:
                left = mid + 1
            else:
                right = mid
        nums = nums[:left]

        # regular two-pointer move
        right = left-1
        left = 0
        result = 0
        mod = (10**9 + 7)
        while left <= right:
            if nums[left] + nums[right] <= target:
                result += pow(2, right - left, mod)
                left += 1
            else:
                right -= 1

        return result % mod

class Solution:
    def numSubseq(self, nums: List[int], target: int) -> int:
        nums.sort()
        ans = 0
        for i in range(len(nums)):
            # single entry
            if 2*nums[i] <= target:
                ans += 1

			# minimum is nums[i]
            # binary search to find the maximum feasible number associated with nums[i]
            lo, hi = i+1, len(nums)-1
            while lo < hi:
                m = (lo + hi) // 2 + 1
                if nums[i] + nums[m] > target:
                    hi = m - 1
                else:
                    lo = m

            # In the subarray [i+1, ..., hi], at least one number has to be taken with nums[i], 
			# count all such combinations
            if nums[i] + nums[hi] <= target:
                ans += (1 << (hi - i)) - 1

        return ans % (10**9 + 7)

class Solution:
