        moves = 3
        left, right = 0, len(nums) - 1
        nums.sort()

        def diff(i: int, left: int, right: int) -> int:
            if i == moves or left == right:
                return nums[right] - nums[left]

            # remove smallest or remove biggest
            remove_left = diff(i + 1, left + 1, right)
