        if stones in self.results[alice]:
            return self.results[alice][stones]
        if stones==0:
            return not alice 
        win,s=True,int(stones**0.5)
        if alice:
            win=False
        while s**2>0:
            if alice:
                win=win or self.game(not alice,stones-s**2)
            else:
