                c=1
            pf[i+1]=pf[i]+c 
            s1.add(s[i])
        for i in range(n-1,-1,-1):
            if s[i] in s2:
                c=0 
            else:
                c=1
            sf[i]=sf[i+1]+c 
            s2.add(s[i])
        #print(pf)
