class Solution:
    def countPairs(self, root: TreeNode, distance: int) -> int:
        ans = 0

        def fn(node): 
            """Return distances of leaves of sub-tree rooted at node."""
            nonlocal ans 
            if not node: return []
            if node.left is node.right is None: return [0]
            left, right = fn(node.left), fn(node.right)
            for x in right: 
                k = bisect_right(left, distance - x - 2) # binary search 
                ans += k
            # merge 
            out = []
            i = j = 0 
            while i < len(left) or j < len(right): 
                if j == len(right) or i < len(left) and left[i] < right[j]: 
                    out.append(1 + left[i])
                    i += 1
                else:
                    out.append(1 + right[j])
                    j += 1
            return out

        fn(root)
        return ans

class Solution:

    def __init__(self):
        self.sol = 0

    def countPairs(self, root: TreeNode, distance: int) -> int:
        def solve(node):
            if not node:
                return []
            if not node.left and not node.right:
                # node, depth
                return [[0, 0]]
            else:
                cur = []
                l = solve(node.left)
                r = solve(node.right)
                for n in l: n[1] += 1
                for n in r: n[1] += 1
                for n in r:
                    for n1 in l:
                        if n[1] + n1[1] <= distance: self.sol += 1
                return l+r
        solve(root)
        return self.sol

class Solution:
    def countPairs(self, root: TreeNode, distance: int) -> int:
        self.distance = distance
        self.ans = 0
        self.dfs(root)
        return self.ans

    def dfs(self, root):
        if not root:
            return []
        if not root.left and not root.right:
            return [1]

        l, r = self.dfs(root.left), self.dfs(root.right)

        for i in l:
            for j in r:
                if i + j <= self.distance:
                    self.ans += 1
        l = [i+1 for i in l]
        r = [j+1 for j in r]

        return l+r

class Solution:
    def __init__(self):
