        while i < len(nums1) and j < len(nums2):
            if nums1[i] < nums2[j]:
                scores[nums1[i]] = nums1[i] if i == 0 else scores[nums1[i-1]] + nums1[i]
                i += 1
            elif nums1[i] > nums2[j]:
                scores[nums2[j]] = nums2[j] if j == 0 else scores[nums2[j-1]] + nums2[j]
