                                       0 if j == 0 else scores[nums2[j-1]]) + nums1[i]
                i, j = i + 1, j + 1                
        while i < len(nums1):
            scores[nums1[i]] = nums1[i] if i == 0 else scores[nums1[i-1]] + nums1[i]
