class Solution:
    def findKthPositive(self, arr: List[int], k: int) -> int:
        left, right = 0, len(arr)
        while left < right:
            mid = left+(right-left)//2
            n_missing = arr[mid]-mid-1
            if n_missing >= k:
                right = mid
            else:
                left = mid+1
