        dp = [[0]*len(cuts) for _ in cuts] 
        for i in reversed(range(len(cuts))):
            for j in range(i+2, len(cuts)): 
                dp[i][j] = cuts[j] - cuts[i] + min(dp[i][k] + dp[k][j] for k in range(i+1, j))
