class Solution:
    def minOperations(self, n: int) -> int:
        vals = [i*2 +1 for i in range(n)]
        mid = len(vals)//2
        vals = [abs(vals[mid] - vals[i]) for i in range(len(vals))]
        return sum(vals)//2

