class Solution:
    def maxDistance(self, position: List[int], m: int) -> int:

        position.sort()
        def max_balls(force):
            res = 1
            start = position[0]
            for i in range(1, len(position)):
                if position[i] - start >= force:
                    res += 1
                    start = position[i]
            return res

        left, right = 1, position[-1] -  position[0]
        while left < right:
            mid = left + (right - left + 1) // 2
            if max_balls(mid) >= m:
                left = mid
            else:
                right = mid - 1
        return left

class Solution:
    def maxDistance(self, position: List[int], m: int) -> int:
        position = sorted(position)
        def helper(x):
            prev = float('-inf')
            counter = 0
            for p in position:
                if abs(p-prev) >= x:
                    counter += 1
                    prev = p
            if counter >= m:
                return True
            else:
                return False

        l, r = 1, max(position)+1
        while l < r:
            mid = (l+r) // 2
            if not helper(mid):
                r = mid
            else:
                l = mid+1
        return l-1

class Solution:
    def canPlace(self,m,n,position,sep):
        count = 1
        location = position[0]
        for i in range(1,n):
            current_loc = position[i]
            if current_loc - location >= sep:
                count += 1
                location = current_loc

                if count == m:
                    return True

        return False

    def maxDistance(self, position: List[int], m: int) -> int:
        n = len(position)
        position.sort()
        low = 0
        #high will be difference of the sorted array
        high = position[-1]-position[0]
        ans = -1
        while low <= high:
            mid = (low+high)//2
            place = self.canPlace(m,n,position,mid)
            if place:
                ans = mid
                low = mid+1
            else:
                high = mid-1
        return ans

class Solution:
    def maxDistance(self, A, n):
        A.sort()
        L    = len(A)
        lo   = 1
        hi   = (A[-1]-A[0])//(n-1)
        best = 1
        n   -= 1
        def valid(mid):
            prev = A[0]
            i    = 0
            for j in range(n):
                d = prev + mid
                while i<L and A[i]<d:
                    i += 1
                if i==L:
                    return False
                prev = A[i]
            return True

        while lo<=hi:
            mid = (lo+hi) >> 1
            if valid(mid):
                best = mid
                lo   = mid + 1
            else:
                hi = mid - 1

        return best

