class Solution:
    def thousandSeparator(self, n: int) -> str:
        if n < 1000:
            return str(n)
        digits, count = [], 1
        while True:
            digits.append(str(n % 10))
            n //= 10
            if n == 0:
                break
            if count % 3 == 0:
                digits.append('.')
            count += 1
        return "".join(reversed(digits))

