class Solution:
    def findSmallestSetOfVertices(self, n: int, edges: List[List[int]]) -> List[int]:
        graph = defaultdict(set)

        visited = set()
        result = set()

        for src,dest in edges:
            graph[src].add(dest)


        def dfs(src):
            visited.add(src)
            for dest in graph[src]:
                if dest not in visited:
                    dfs(dest)
                elif dest in result:
                    result.remove(dest)


        for i in range(n):
            if i not in visited:
                result.add(i)
                dfs(i)

        return result

class Solution:
    def findSmallestSetOfVertices(self, n: int, edges: List[List[int]]) -> List[int]:
        # find all nodes with indegree of 0, these are the vertices that you must start from and cant be reached by anything else
        # so thats the smallest set of vertices that allow for you to dfs over all nodes
        indegrees = [0 for _ in range(n)]

        for a, b in edges:
            indegrees[b] += 1

        return [i for i in range(len(indegrees)) if indegrees[i] == 0]

class Solution:
    def findSmallestSetOfVertices(self, n: int, edges: List[List[int]]) -> List[int]:
        graph = collections.defaultdict(list)
        for u, v in edges:
            graph[u].append(v)

        def dfs(vertex, visited: list, graph: dict, ans:list):
            visited[vertex] = True
            for node in graph[vertex]:
                if not visited[node]:
                    dfs(node, visited, graph, ans)
                elif node in ans: ans.remove(node)

        visited = [False]*n
        ans = set()
        for i in range(n):
            if not visited[i]:
                dfs(i, visited, graph, ans)
                ans.add(i)

        return ans

