class Solution:
    def minOperations(self, nums: List[int]) -> int:
        x = sum(nums)
        count = 0
        while x != 0:
            for i in range(len(nums)):
                if nums[i] % 2 != 0:
                    count += 1
                    x -= 1
            if x != 0:
                for i in range(len(nums)):
                    if nums[i] != 0:
                        nums[i] //= 2
                        x -= nums[i]
                count += 1
        return count

class Solution:
    def minOperations(self, nums: List[int]) -> int:
        count = 0
        n = len(nums)
        if max(nums) == 0:
            return 0
        while max(nums) != 0:
            for i in range(n):
                if nums[i] % 2 == 1:
                    nums[i] -= 1
                    count += 1
            for i in range(n):
                nums[i] //= 2
            count += 1
        return count - 1

