class Solution:
    def dfs(self, grid, row, col, visit, prev_row, prev_col, prev, visited):
        if row < 0 or col < 0 or row == len(grid) or col == len(grid[0]) or grid[row][col] != prev:
            return
        if (row, col) in visit:
            #print(row, col)
            self.ans = True
            return
        #print(row, col, prev_row, prev_col)
        visit.add((row, col))
        visited[row][col] = True
        if row-1 != prev_row:
            self.dfs(grid, row-1, col, visit, row, col, grid[row][col], visited)
        if col-1 != prev_col:
            self.dfs(grid, row, col-1, visit, row, col, grid[row][col], visited)
        if row+1 != prev_row:
            self.dfs(grid, row+1, col, visit, row, col, grid[row][col], visited)
        if col+1 != prev_col:
            self.dfs(grid, row, col+1, visit, row, col, grid[row][col], visited)
        visit.remove((row, col))

    def containsCycle(self, grid: List[List[str]]) -> bool:
        self.ans = False
        m, n = len(grid), len(grid[0])
        visited = [[False for _ in range(n)] for _ in range(m)]
        for i in range(m):
            for j in range(n):
                if visited[i][j] == False:
                    self.ans = False
                    visit = set()
                    self.dfs(grid, i, j, visit, -1, -1, grid[i][j], visited)
                    if self.ans == True:
                        return True
        return False

class Solution:
    def containsCycle(self, grid: List[List[str]]) -> bool:
        m,n = len(grid),len(grid[0])
        parent = list(range(m*n))
        rank = [1 for _ in range(m*n)]
        def find(node):
            if parent[node]!=node:
                parent[node] = find(parent[node])
            return parent[node]
        def union(node1,node2):
            p1,p2 = find(node1),find(node2)
            if p1==p2:
                return
            if rank[p1]>rank[p2]:
                p1,p2 = p2,p1
            rank[p2] += rank[p1]
            parent[p1] = p2
        for i in range(m):
            for j in range(n):
                for x,y in ((i,j+1),(i+1,j)):
                    if 0<=x<m and 0<=y<n and grid[i][j]==grid[x][y]:
                        n1,n2 = i*n+j,x*n+y
                        if find(n1)==find(n2):
                            return True
                        else:
                            union(n1,n2)
        return False

class Solution:
    def containsCycle(self, grid: List[List[str]]) -> bool:
        m, n = len(grid), len(grid[0])

        def valid(x, y):
            return x>=0 and x<=m-1 and y>=0 and y<=n-1

        def neighbor(p1, p2):
            x1, y1 = p1
            x2, y2 = p2
            return valid(x1, y1) and valid(x2, y2) and abs(x1-x2) + abs(y1-y2) == 1

        def dfs(p, q):
            nonlocal grid

            stack = [(p, q, 1)]
            val = grid[p][q]

            while stack: 
                x, y, length = stack.pop()
                grid[x][y] = "X"
                if neighbor((x, y), (p, q)) and length >= 4:

                    return True 
                for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    xi, yi = x+dx, y+dy
                    if valid(xi, yi) and grid[xi][yi] == val and grid[xi][yi] != "X":
                        stack.append((xi, yi, length + 1))

            return False

        for i in range(m):
            for j in range(n):

                if i< m-1 and j < n-1 and grid[i][j] == grid[i][j+1] == grid[i+1][j] and grid[i][j] != "X": 
                    if dfs(i, j):
                        return True

        return False

class Solution:
    def containsCycle(self, grid: List[List[str]]) -> bool:
        H,W=len(grid),len(grid[0])
        seen=[[False]*W for _ in range(H)]

        def dfs(old_r,old_c, r,c):
            if seen[r][c]: return True
            seen[r][c]=True

            for nr,nc in (r+1,c),(r-1,c),(r,c+1),(r,c-1):
                if H>nr>=0<=nc<W and grid[nr][nc]==grid[r][c]:
                    if (nr,nc)!=(old_r,old_c):
                        if dfs(r,c,nr,nc): return True
            return False

        return any(dfs(-1,-1,r,c) for r in range(H) for c in range(W) if not seen[r][c])

class Solution:
	def containsCycle(self, grid: List[List[str]]) -> bool:
		row, col = len(grid), len(grid[0])
		visited = set()

		for x in range(row):
			for y in range(col):
				if (x,y) not in visited:
					queue = deque([(x, y, set([]), None)])
					if self.bfs(queue, row, col, grid[x][y], grid, visited):
						return True

		return False

	def bfs(self, queue, row, col, curVal, grid, visited):
		while queue:
			x, y, curPath, prev = queue.popleft()

			visited.add((x,y))
			curPath.add((x,y))

			for nx, ny in [[x+1,y],[x-1,y],[x,y-1],[x,y+1]]:
				if 0<=nx<row and 0<=ny<col and grid[nx][ny] == curVal:
					if (nx,ny) in curPath and (nx,ny) != prev:
						return True
					if (nx,ny) not in curPath:
						queue.append((nx,ny, curPath, (x,y)))

