class Solution:
    def stoneGameV(self, stoneValue: List[int]) -> int:
        n = len(stoneValue)
        pre = [0]
        for i in range(n):
            pre.append(stoneValue[i] + pre[-1])
        @lru_cache(None)
        def dfs(l, r):
            if r <= l:
                return 0
            res = 0
            for i in range(l, r):
                # [l, i] [i + 1, r]
                left = pre[i + 1] - pre[l]
                right = pre[r + 1] - pre[i + 1]
                if right > left:
                    res = max(res, dfs(l, i) + left)
                elif left > right:
                    res = max(res, dfs(i + 1, r) + right)
                else:
                    res = max(res, dfs(l, i) + left)
                    res = max(res, dfs(i + 1, r) + right)
            return res
        return dfs(0, n - 1)

class Solution:
    def stoneGameV(self, stoneValue: List[int]) -> int:
        # prefix sum 
        prefix = [0]
        for x in stoneValue: prefix.append(prefix[-1] + x)

        @lru_cache(None)
        def fn(lo, hi):
            """Return the score of arranging values from lo (inclusive) to hi (exclusive). """
            if lo+1 == hi: return 0 
            val = 0
            for mid in range(lo+1, hi): 
                lower = prefix[mid] - prefix[lo]
                upper = prefix[hi] - prefix[mid]
                if lower < upper: val = max(val, lower + fn(lo, mid))
                elif lower > upper: val = max(val, upper + fn(mid, hi))
                else: val = max(val, lower + max(fn(lo, mid), fn(mid, hi)))
            return val 

        return fn(0, len(stoneValue))

