        def fn(x, y, freq): 
            """Return count of triplet of nums[i]**2 = nums[j]*nums[k]."""
            ans = 0
            for xx in x: 
                xx *= xx
                ans += sum(freq[xx//yy] - (yy == xx//yy) for yy in y if not xx%yy and xx//yy in freq)
            return ans//2

        return fn(nums1, nums2, cnt2) + fn(nums2, nums1, cnt1)

