class Solution:
    def minCostConnectPoints(self, points: List[List[int]]) -> int:
        manhattan = lambda p1, p2: abs(p1[0]-p2[0]) + abs(p1[1]-p2[1])
        n, c = len(points), collections.defaultdict(list)
        for i in range(n):
            for j in range(i+1, n):
                d = manhattan(points[i], points[j])
                c[i].append((d, j))
                c[j].append((d, i))
        cnt, ans, visited, heap = 1, 0, [0] * n, c[0]
        visited[0] = 1
        heapq.heapify(heap)
        while heap:
            d, j = heapq.heappop(heap)
            if not visited[j]:
                visited[j], cnt, ans = 1, cnt+1, ans+d
                for record in c[j]: heapq.heappush(heap, record)
            if cnt >= n: break        
        return ans

class Solution:
    def minCostConnectPoints(self, points: List[List[int]]) -> int:
        d, res = {(x, y): float('inf') if i else 0 for i, (x, y) in enumerate(points)}, 0
        while d:
            x, y = min(d, key=d.get)  # obtain the current minimum edge
            res += d.pop((x, y))      # and remove the corresponding point
            for x1, y1 in d:          # for the rest of the points, update the minimum manhattan distance
                d[(x1, y1)] = min(d[(x1, y1)], abs(x-x1)+abs(y-y1))
        return res

class Solution:
    def minCostConnectPoints(self, points: List[List[int]]) -> int:

        if len(points) <= 1:
            return 0

        graph = self.create_graph(points)
        graph.sort(key=lambda x: x[2])

        n = len(points)
        uf = UnionFind(n)

        result = 0
        count = 0

        for i in graph:
            vertex, node, cost = i

            if count == n - 1:
                break

            if uf.union(vertex, node):
                result += cost
                count += 1
            else:
                continue

        return result

    def create_graph(self, points):
        graph = []

        for i in range(len(points) - 1):
            for j in range(i + 1, len(points)):

                curr_point = points[i]
                next_point = points[j]
                result = self.difference(curr_point[0], curr_point[1],
                                        next_point[0], next_point[1])

                graph.append([i, j, result])

        return graph

    def difference(self, a, b, c, d):
        return abs(a - c) + abs(b - d)


class UnionFind:
    def __init__(self, size):
        self.root = [i for i in range(size)]
        self.rank = [1 for _ in self.root]

    def find(self, vertex):
        if vertex == self.root[vertex]:
            return vertex
        self.root[vertex] = self.find(self.root[vertex])
        return self.root[vertex]

    def union(self, v1, v2):
        root1 = self.find(v1)
        root2 = self.find(v2)

        if root1 != root2:
            if self.rank[root1] > self.rank[root2]:
                self.root[root2] = root1
            elif self.rank[root1] < self.rank[root2]:
                self.root[root1] = root2
            else:
                self.root[root2] = root1
                self.rank[root1] += 1

            return True

        else:
            return False

class Solution:
    def minCostConnectPoints(self, points: List[List[int]]) -> int:
        N = len(points)

        adj = {i:[] for i in range(N)}

        for i in range(N):
            x1, y1 = points[i]
            for j in range(i+1, N):
                x2, y2 = points[j]
                dis = abs(x1-x2) + abs(y1-y2)
                adj[i].append([dis, j])
                adj[j].append([dis, i])

        res = 0
        minHeap = [[0,0]]
        visit = set()
        while len(visit) < N:
            cost, node = heapq.heappop(minHeap)
            if node in visit:
                continue
            res += cost
            for neighCost, nei in adj[node]:
                if nei not in visit:
                    heapq.heappush(minHeap, [neighCost, nei])
            visit.add(node)
        return res

class Solution:
    def to_tuple(self, points):
        return tuple(tuple(point) for point in points)

    def getDistance(self, x, y):
        return abs(y[0]-x[0])+abs(y[1]-x[1])

    def computeEdges(self, pointsTuple, length):
        edges = []
        for point1 in range(length-1):
            for point2 in range(point1+1,length):
                dist = self.getDistance(pointsTuple[point1], pointsTuple[point2])
                edges.append((pointsTuple[point1], pointsTuple[point2], dist))
        return edges

    def minCostConnectPoints(self, points: List[List[int]]) -> int:
        def find(parent, node):
            if node != parent[node]:
                parent[node] = find(parent, parent[node])
            return parent[node]

        def union(parent, rank, parent1, parent2):
            if rank[parent2] > rank[parent1]:
                parent[parent1] = parent2
                rank[parent2] += rank[parent1]
            else:
                parent[parent2] = parent1
                rank[parent1] += rank[parent2]

        pointsTuple = self.to_tuple(points)
        length = len(pointsTuple)
        edges = self.computeEdges(pointsTuple, length)
        edges.sort(key=lambda x:x[2])

        parent, rank, visited, current, mincost = {}, {}, 0, 0, 0
        for node in pointsTuple:
            parent[node] = node
            rank[node] = 1

        while visited < length - 1:
            node1, node2, cost = edges[current]
            current += 1
            parent1, parent2 = find(parent, node1), find(parent, node2)
            if parent1 != parent2:
                mincost += cost
                visited += 1
                union(parent, rank, parent1, parent2)

        return mincost

class Solution:
    def minCostConnectPoints(self, points: List[List[int]]) -> int:
        if len(points) == 1: return 0

        # calculates manhattan distance
        def dist(u, v):
            x1, y1 = points[u]
            x2, y2 = points[v]
            return abs(x1 - x2) + abs(y1 - y2)

        def find(n):
            p = parent[n]
            while p != parent[p]:
                p = parent[p]
            return p

        def union(u, v):
            p1 = find(u)
            p2 = find(v)

            # cycle found
            if p1 == p2:
                return True

            if rank[p1] > rank[p2]:
                parent[p2] = p1
                rank[p1] += rank[p2]
            else:
                parent[p1] = p2
                rank[p2] += rank[p1]

            return False

        n = len(points)
        edge_weight_map = defaultdict(int)
        # connect each pair of points with a weighted edge
        for i in range(0, n):
            for j in range(i + 1, n):
                edge_weight_map[(i, j)] = dist(i, j)

        # sort edges in non-decreasing order by weight
        sorted_edges_list = sorted(edge_weight_map.items(), key = lambda x : x[1])

        parent = [i for i in range(0, n)]
        rank = [1 for _ in range(0, n)]

        cost = 0
        edges_count = 0

        # Find mst using Kruskal's algo
        for edge, weight in sorted_edges_list:
            u, v = edge
            # pick smallest edge
            # if it forms a cycle(detect using union-find), discard it
            # else include this edge in mst
            if not union(u, v):
                cost += weight
                edges_count += 1
            # mst found
            if edges_count == n - 1:
                return cost

class Solution:
    def minCostConnectPoints(self, points: List[List[int]]) -> int:
        visited = set()
        def getManhattanDist(x1, y1):
            res = []
            for x2, y2 in points:
                if (x2, y2) not in visited:
                    res.append([abs(x1 - x2) + abs(y1 - y2), (x2, y2)])
            return res        

        minheap = []
        heappush(minheap, [0, (points[0][0], points[0][1])])
        ans = 0
        while len(minheap) > 0:
            if len(visited) == len(points):
                break
            c, (x, y) = heappop(minheap)
            if (x, y) not in visited:
                ans += c
                visited.add((x, y))
                values = getManhattanDist(x, y)
                for value in values:
                    heappush(minheap, value)

        return ans

class Solution:
    def minCostConnectPoints(self, points: List[List[int]]) -> int:
        """Given an array points representing integer coordinates
        of some points on a 2D-plane, where points[i] = [xi, yi],
        return the minimum cost to make all points connected. All
        points are connected if there is exactly one simple path
        between any two points."""
        result = 0
        MAX = 20000001
        dist = {}
        for i in range(len(points)):
            dist[points[i][0], points[i][1]] = MAX if i else 0
        while dist:
            temp_min = MAX
            for i in dist:
                if dist[i] <= temp_min:
                    temp_min = dist[i]
                    x, y = i[0], i[1]
            result += dist.pop((x, y))
            for i in dist:
                temp_min = (abs(x - i[0]) + abs(y - i[1]))
                if temp_min < dist[i]:
                    dist[i] = temp_min
        return result

class Solution:
    def find_dist(self, pair1, pair2):
        return abs(pair1[0] - pair2[0]) + abs(pair1[1] - pair2[1])

    def minCostConnectPoints(self, points: List[List[int]]) -> int:
        total_points = len(points)
        d = collections.defaultdict(list)

        for i in range(total_points):
            for j in range(i+1, total_points):
                dist = self.find_dist(points[i], points[j])
                d[i].append((dist, j))
                d[j].append((dist, i))

        heap = d[0]
        heapq.heapify(heap)
        res = 0 

        """
        inital visit '0' point + we also exclude this point, so as not to return here if the distance between the zero and the next point is the smallest.
        """
        current_points_cnt = 1
        visited = set([0])

        while heap and current_points_cnt != total_points:
            dist, p = heapq.heappop(heap) # select minimum distance among the possible neighbors for the last visited point

            if p not in visited:
                visited.add(p)

                for v in d[p]:
                    heapq.heappush(heap, v) # adding distances to neighbors

                res += dist # add min dist
                current_points_cnt += 1 # inc visited point count

        return res

class Solution:
    def isTransformable(self, s: str, t: str) -> bool:
        if sorted(s) != sorted(t): return False # edge case 

        pos = [deque() for _ in range(10)]
        for i, ss in enumerate(s): pos[int(ss)].append(i)

        for tt in t: 
            i = pos[int(tt)].popleft()
            for ii in range(int(tt)): 
                if pos[ii] and pos[ii][0] < i: return False # cannot swap 
        return True

