class Solution:
    def maxSumRangeQuery(self, nums: List[int], requests: List[List[int]]) -> int:
        chg = [0]*len(nums) # change 
        for i, j in requests: 
            chg[i] += 1
            if j+1 < len(nums): chg[j+1] -= 1
        for i in range(1, len(nums)): chg[i] += chg[i-1] # cumulated change
        return sum(n*c for n, c in zip(sorted(nums), sorted(chg))) % 1_000_000_007

class Solution:
    def minSubarray(self, nums: List[int], p: int) -> int:
        s = sum(nums)
        if s % p == 0: return 0 


        moddict = {}
        minv = float('inf')
        t = 0 

        moddict[0] = 0 
        cnt = 1
        for num in nums:
            t = (t + num) % p 
            if (t-s) % p in moddict:
                minv = min(minv, cnt - moddict[(t-s)%p])
            moddict[t] = cnt
            cnt += 1

        if minv == float('inf') or minv == len(nums):
            return -1
        else:
            return minv

class Solution:
    def minSubarray(self, nums: List[int], p: int) -> int:
        suffix = [0]
        for x in reversed(nums): suffix.append((suffix[-1] + x)%p)
        suffix.reverse()

        if suffix[0] % p == 0: return 0 # edge case 

        ans = inf 
        prefix = 0
        seen = {0: -1}
        for i, x in enumerate(nums): 
            if (p - suffix[i+1])%p in seen: 
                ans = min(ans, i - seen[(p - suffix[i+1])%p])
            prefix = (prefix + x) % p
            seen[prefix] = i
        return ans if ans < len(nums) else -1

class Solution:
    def minSubarray(self, nums: List[int], p: int) -> int:
        target = sum(nums) % p # targetted remainder 
        ans = inf
        seen = {(prefix := 0): -1}
        for i, x in enumerate(nums): 
            seen[(prefix := (prefix+x)%p)] = i # update seen before check 
            if (prefix-target) % p in seen: 
                ans = min(ans, i - seen[(prefix-target) % p])
        return ans if ans < len(nums) else -1 # not allowed to remove whole array

