            """Find max length via backtracking."""
            ans = 0
            if i < len(s): # boundary condition when i == len(s)
                for ii in range(i+1, len(s)+1): 
                    if s[i:ii] not in seen: 
                        seen.add(s[i:ii])
                        ans = max(ans, 1 + fn(ii, seen))
                        seen.remove(s[i:ii])
            return ans 

        return fn(0)

