        items = list(zip(keyName, iter(datetime.datetime.strptime(item, "%H:%M") for item in keyTime)))
        items.sort(key=lambda l: l[1])
        res = set()
        for name, time in items:
            if len(d[name]) == 2:
                if (time - d[name][0]).seconds <= 3600:
                    res.add(name)
