class Solution:
    def restoreMatrix(self, rowSum: List[int], colSum: List[int]) -> List[List[int]]:
        def backtrack(y, x):
            choice = min(rowSum[y], colSum[x])
            result[y][x] = choice
            rowSum[y] -= choice
            colSum[x] -= choice
            if y == 0 and x == 0:
                return

            elif not rowSum[y]:
                backtrack(y - 1, x)
            elif not colSum[x]:
                backtrack(y, x - 1)

        Y, X = len(rowSum), len(colSum)
        result = [[0 for _ in range(X)] for _ in range(Y)]
        backtrack(Y-1, X-1)
        return result

class Solution:
    def restoreMatrix(self, rowSum: List[int], colSum: List[int]) -> List[List[int]]:
        n,m=len(rowSum),len(colSum)
        matrix = [[0 for i in range(m)] for j in range(n)]
        total = 0
        for i in range(n):
            matrix[i][0] = rowSum[i]
            total += rowSum[i]
        for c in range(m):
            if total == colSum[c]:
                break
            else:
                nextTotal = total - colSum[c]
                total = nextTotal
                for r in range(n):
                    curr = min(matrix[r][c],total)
                    matrix[r][c] -= curr
                    total -= curr
                    if c+1 < m:
                        matrix[r][c+1] = curr
                total = nextTotal
        return matrix

