    def countSubgraphsForEachDiameter(self, n: int, edges: List[List[int]]) -> List[int]:

        def fn(edges): 
            """ """
            graph = {} # graph as adjacency list 
            for u, v in edges:
                graph.setdefault(u-1, []).append(v-1) # 0-indexed 
                graph.setdefault(v-1, []).append(u-1)
            group = [None]*n
            dist = [0]*n

            def dfs(x, d=0): 
                """ """
                seen.add(x) # mark visited 
                for xx in graph.get(x, []): 
                    dist[x] = max(dist[x], d)
                    if group[xx] is None: group[xx] = group[x]
                    if xx not in seen: dfs(xx, d+1)

            for i in range(n): 
                seen = set()
                if group[i] is None: group[i] = i
                dfs(i)
            return group, dist 

        ans = {} # answer 
        for r in range(1, len(edges)+1):
            for x in combinations(edges, r): 
                temp = {}
                d = {}
                seen, dist = fn(x)
                for i in range(n): 
                    temp.setdefault(seen[i], []).append(i)
                    if seen[i] not in d: d[seen[i]] = dist[i]
                    else: d[seen[i]] = max(d[seen[i]], dist[i])
                for k, v in temp.items(): 
                    if len(v) > 1: 
                        ans.setdefault(d[k], set()).add(tuple(sorted(v)))
        return [len(ans.get(x, set())) for x in range(1, n)]

class Solution:
    def countSubgraphsForEachDiameter(self, n: int, edges: List[List[int]]) -> List[int]:
        def maxDistance(subtree):
            edges,node,maxD=[0]*3
            for i in range(n):
                if (subtree>>i)&amp;1==0:continue
                node+=1
                for j in range(i+1,n):
                    if (subtree>>j)&amp;1==0:continue
                    edges+=dist[i][j]==1
                    maxD=max(maxD,dist[i][j])
            if edges!=node-1:
                return 0
            else:
                return maxD
        dist=[[float('inf')]*n for i in range(n)]
        for i,j in edges:
            dist[i-1][j-1]=dist[j-1][i-1]=1
        for mid in range(n):
            for n1 in range(n):
                for n2 in range(n):
                    dist[n1][n2]=min(dist[n1][n2],dist[n1][mid]+dist[mid][n2])
        ans=[0]*(n-1)
        for i in range(1,2**n):
            d=maxDistance(i)
            if d>0:
                ans[d-1]+=1
        return ans

