class Solution:
    def maxLengthBetweenEqualCharacters(self, s: str) -> int:
        data, result = {}, -1
        for index, char in enumerate(s):
            if char not in data:
                data[char] = index
            elif index - 1 - data[char] > result:
                result = index - 1 - data[char]
        return result

class Solution:
    def findLexSmallestString(self, s: str, a: int, b: int) -> str:
        op1 = lambda s: "".join(str((int(c)+a)%10) if i&amp;1 else c for i, c in enumerate(s))
        op2 = lambda s: s[-b:] + s[:-b]

        seen = set()
        stack = [s]
        while stack: 
            s = stack.pop()
            seen.add(s)
            if (ss := op1(s)) not in seen: stack.append(ss)
            if (ss := op2(s)) not in seen: stack.append(ss)
        return min(seen)

class Solution:
    def __init__(self):
        self.smallest = float("inf")
        self.seen = {}

    def rotate(self, s, b):
        s = [char for char in s]
        def reverse_segment(start, end):
            end -= 1
            while start < end:
                s[start], s[end] = s[end], s[start]
                start += 1
                end -= 1
        rotations = b % len(s)
        reverse_segment(0, len(s))
        reverse_segment(0, rotations)
        reverse_segment(rotations, len(s))
        return "".join(s) 

    def add_one(self, char, a):
        return str((int(char)+a) % 10)

    def add(self, s, a):
        s = [char for char in s]
        for idx in range(len(s)):
            if idx % 2 != 0:
                s[idx] = self.add_one(s[idx], a)
        return "".join(s)

    def findLexSmallestString(self, s: str, a: int, b: int) -> str:
        if self.smallest == float("inf"):
            self.smallest = s        
        if int(s) < int(self.smallest):
            self.smallest = s
        if s in self.seen:
            return
        self.seen[s] = True
        self.findLexSmallestString(self.rotate(s,b), a, b)
        self.findLexSmallestString(self.add(s,a), a, b)
        return self.smallest

class Solution:
    def findLexSmallestString(self, s: str, a: int, b: int) -> str:
        dq, visited = collections.deque([s]), set([s])
        ans, n = s, len(s)
        while dq:
            cur = dq.popleft()
            ans = min(ans, cur)
            cur_a = ''.join([
                str((int(cur[i]) + a) % 10) if i % 2 else cur[i] 
                for i in range(n)
            ])
            cur_b = cur[b:] + cur[:b]
            if cur_a not in visited: 
                dq.append(cur_a)
                visited.add(cur_a)
            if cur_b not in visited: 
                dq.append(cur_b)
                visited.add(cur_b)
        return ans

