class Solution:
    def minimumEffortPath(self, heights: List[List[int]]) -> int:
        m, n = len(heights), len(heights[0])

        def fn(x): 
            """Return True if given effort is enough."""
            stack = [(0, 0)] # i|j|h starting from top-left 
            seen = set()
            while stack: 
                i, j = stack.pop()
                seen.add((i, j))
                if i == m-1 and j == n-1: return True # reaching bottom-right 
                for ii, jj in (i-1, j), (i, j-1), (i, j+1), (i+1, j): 
                    if 0 <= ii < m and 0 <= jj < n and (ii, jj) not in seen and abs(heights[ii][jj] - heights[i][j]) <= x: 
                        stack.append((ii, jj))
            return False 

        lo, hi = 0, 10**6
        while lo < hi: 
            mid = lo + hi >> 1
            if not fn(mid): lo = mid + 1
            else: hi = mid
        return lo

class Solution:
    def minimumEffortPath(self, heights: List[List[int]]) -> int:
        m,n = len(heights),len(heights[0])
        parent = list(range(m*n))
        rank = [1 for _ in range(m*n)]
        def find(node):
            if parent[node]!=node:
                parent[node] = find(parent[node])
            return parent[node]
        def union(node1, node2):
            p1,p2 = find(node1),find(node2)
            if p1==p2:
                return
            if rank[p1]>rank[p2]:
                p1,p2 = p2,p1
            parent[p1] = p2
            rank[p2] += rank[p1]
        edges = []
        for i in range(m):
            for j in range(n):
                if i>0:
                    edges.append((abs(heights[i][j]-heights[i-1][j]),(i-1)*n+j,i*n+j))
                if j>0:
                    edges.append((abs(heights[i][j]-heights[i][j-1]),i*n+j-1,i*n+j))
        edges.sort()
        for t in edges:
            union(t[1],t[2])
            if find(0)==find(m*n-1):
                return t[0]
        return 0

class Solution:
