            if (i,j) in visited:
                return False
            if i<0 or j<0 or i>m-1 or j>n-1 or abs(heights[i][j]-pre)>target:
                return False
            if i==m-1 and j==n-1:
                return True
            visited.add((i,j))
            return dfs(i+1,j,heights[i][j],target) or\
                   dfs(i-1,j,heights[i][j],target) or\
                   dfs(i,j+1,heights[i][j],target) or\
                   dfs(i,j-1,heights[i][j],target)
