class Solution:
    def minDeletions(self, s: str) -> int:
        ## RC ##
        ## APPROACH : HASHMAP ##
        ## LOGIC ##
        ## Lets take an example freq {3,3,3,4,4,4} ##
        ## 1. We can establish that, distinct freq we can have are {1, 2, 3, 4} ##
        ## 2. So, obvisouly we add highest freq value as it is,
        ## 3. for the next highest, if it equal to previous, we delete one character ##
        ## 4. We repeat the same for other also, ( but instead of deleting one char at a time and checking if it is unique or not, we can store previous value that is added to set and incase if the current value is equal to previous, we add previous value-1 (deleting a character) to set and change prev=previous-1, we stop iterating when we have all distinct freqs and remaning chars should be deleted, in the above example we stop at 2nd 3, so we delete [3,3] and we add [1,2,3,4] to set)

        counts = collections.Counter(s)
        final_set = set()
        for key,val in sorted(counts.items(), key=lambda item: -item[1]):
            if val not in final_set:
                final_set.add(val)
                prev=val
            else:
                # indicates it is same freq as prev element
                final_set.add(prev - 1)
                prev=prev-1
                if prev == 0:
                    break
        return len(s) - sum(final_set)

class Solution:
    def minDeletions(self, s: str) -> int:

        #listing element quantities: example "ceabaacb" -> [2,1,3,2]
        s = list(collections.Counter(s).values())
        freq, count = set(), 0

        for i in s:
            while i in freq:
                i -= 1
                count += 1
            if i > 0: freq.add(i)

        return count
